import axios from 'axios';
import React, { useState } from 'react'
import { Grid, TextField, Button } from '@mui/material';
import { FormControl, InputLabel, MenuItem, Select } from '@mui/material';
import { TextareaAutosize } from '@mui/base/TextareaAutosize';
import { toast } from 'react-toastify';

const CreateDoctor = () => {

    const [doctorDetails, setdoctorDetails] = useState({
        docId: '',
        drName: '',
        drGender: '',
        drEmail: '',
        drNum: '',
        drAddress: ''
    });

    const handleInput = (e) => {
        const name = e.target.name;
        const value = e.target.value;

        setdoctorDetails({ ...doctorDetails, [name]: value });
    }

    const handleSubmit = (e) => {

        e.preventDefault(); // Prevent default form submission behavior

        // Here, you can collect all the data and submit it
        const submittedData = {
            doctorDetails
        };

        console.log('Submitted Data:', submittedData);

        // Assuming you have an API endpoint for submission
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.post(`${apiBaseUrl}/auth/create-doctor`, submittedData)
            .then(response => {
                toast.success('Doctor Created successfully'); // Display success message
                // console.log('Submission successful:', response.data);
                // Clear the data after successful submission
                setdoctorDetails({
                    docId: '',
                    drName: '',
                    drGender: '',
                    drEmail: '',
                    drNum: '',
                    drAddress: ''
                });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    }

    return (
        <>
            <div className='container'>
        <h5 style={{ textAlign: 'left' }}>Create Doctor &rarr;</h5>
                <form action="" onSubmit={handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={6} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Doctor Name" name="drName" id="drName" value={doctorDetails.drName} onChange={handleInput} required/>
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Gender" name="drGender" id="drGender" value={doctorDetails.drGender} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>
                    </Grid>

                    <Grid container spacing={2}>
                        <Grid item xs={6} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Email" name="drEmail" id="drEmail" value={doctorDetails.drEmail} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Number" name="drNum" id="drNum" value={doctorDetails.drNum} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>
                    </Grid>

                    <Grid container spacing={2}>
                        <Grid item xs={12} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >

                                    {/* <TextField variant="outlined" label="Email" name="drEmail" id="drEmail" value={doctorDetails.drEmail}  /> */}
                                    <TextareaAutosize variant="outlined" label="Address" name="drAddress" id="drAddress" minRows="10" value={doctorDetails.drAddress} onChange={handleInput}> </TextareaAutosize>
                                </FormControl>

                            </div>
                        </Grid>
                    </Grid>

                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <div>
                                <Button type='submit' style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }} >CREATE</Button>
                            </div>
                        </Grid>
                    </Grid>
                </form>
            </div>
        </>
    )
}

export default CreateDoctor