import React, { useState, useEffect } from 'react';
import axios from 'axios';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import {
    Table,
    TableContainer,
    TableHead,
    TableRow,
    TableCell,
    TableBody,
    Paper,
    Grid,
    TablePagination,
    MenuItem,
    Select,
    Button,
} from '@mui/material';
import CollectionNav from './CollectionNav';

const DeptWiseCollection = () => {
    const [departments, setDepartments] = useState([]);
    const [selectedDepartment, setSelectedDepartment] = useState('');
    const [departmentWiseCollectionData, setDepartmentWiseCollectionData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedDate, setSelectedDate] = useState(new Date());

    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(8);

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        // Fetch list of departments
        axios
            .get(`${apiBaseUrl}/auth/getDepartments`)
            .then((response) => {
                // Add "All" and "LAB" to the list of departments
                const updatedDepartments = [
                    { id: 'all', department: 'All' },
                    { id: 'lab', department: 'Lab' },
                    ...response.data.departments,
                ];

                setDepartments(updatedDepartments);
            })
            .catch((error) => {
                console.error('Error fetching departments:', error);
            });
    }, []);

    useEffect(() => {
        const formattedDate = selectedDate.toISOString().split('T')[0];
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        if (selectedDepartment) {
            // Adjust the API endpoint to get department-wise collection based on department ID
            axios
                .get(`${apiBaseUrl}/auth/deptWiseCollection/${selectedDepartment}/${formattedDate}`)
                .then((response) => {
                    setDepartmentWiseCollectionData(response.data);
                    setIsLoading(false);
                })
                .catch((error) => {
                    console.error('Error fetching department-wise collection data:', error);
                    setIsLoading(false);
                });
        }
    }, [selectedDepartment, selectedDate]);

    const downloadExcelFile = async () => {
        if (selectedDepartment) {
            const formattedDate = selectedDate.toISOString().split('T')[0];
            const apiBaseUrl = process.env.REACT_APP_API_KEY;

            try {
                const response = await axios.get(
                    `${apiBaseUrl}/auth/downloadDeptWiseCollection/${selectedDepartment}/${formattedDate}`,
                    {
                        responseType: 'blob',
                    }
                );

                const blob = new Blob([response.data], {
                    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                });
                const url = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = 'department-wise-collection.xlsx';
                a.click();

                window.URL.revokeObjectURL(url);
            } catch (error) {
                console.error('Error downloading Excel file:', error);
            }
        } else {
            console.error('Please select a department before downloading.');
        }
    };

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    return (
        <div className="container">
            <CollectionNav />
            <h5 style={{ textAlign: 'center' }}>Department-wise Collection Report</h5>
            <Select
                value={selectedDepartment}
                onChange={(event) => setSelectedDepartment(event.target.value)}
                displayEmpty
                style={{ marginBottom: '20px', marginRight: '10px', width: '200px' }}
            >
                <MenuItem value="" disabled>
                    Select Department
                </MenuItem>
                {departments.map((department) => (
                    <MenuItem key={department._id} value={department.department}>
                        {department.department}
                    </MenuItem>
                ))}
            </Select>
            <DatePicker
                selected={selectedDate}
                onChange={(date) => setSelectedDate(date)}
                dateFormat="yyyy-MM-dd"
                style={{ marginBottom: '20px', marginRight: '10px', width: '200px' }}
            />
            <Button
                style={{
                    backgroundColor: '#8F00FF',
                    color: 'white',
                    border: 'none',
                    marginLeft: '10px',
                    marginBottom: '20px',
                }}
                variant="contained"
                color="primary"
                onClick={downloadExcelFile}
            >
                Download Excel
            </Button>

            <Grid container spacing={2} style={{ marginTop: '20px' }}>
                {/* Box 1: Number of Bills */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
                        <strong>Number of Bills</strong>
                        <br />
                        {departmentWiseCollectionData.length}
                    </Paper>
                </Grid>

                {/* Box 2: Bill Total */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white' }}>
                        <strong>Revenue</strong>
                        <br />
                        {/* Calculate the total bill amount */}
                        {departmentWiseCollectionData.reduce((total, item) => total + item.fees, 0)}
                    </Paper>
                </Grid>
            </Grid>

            {isLoading ? (
                <img
                    src={require('../../assets/images/loading.gif')}
                    alt="bb"
                    style={{ width: '100px', height: '100px' }}
                />
            ) : (
                <div>
                    <TableContainer component={Paper}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>
                                        <strong>Date</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Doctor Name</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Patient Name</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Revenue</strong>
                                    </TableCell>
                                    {/* <TableCell>
                                        <strong>Discount</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Revenue</strong>
                                    </TableCell> */}
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {departmentWiseCollectionData
                                    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                                    .map((doctorData) => (
                                        <TableRow key={doctorData.doctorId}>
                                            <TableCell>{doctorData.createdAt}</TableCell>
                                            <TableCell>{doctorData.doctorName ? doctorData.doctorName.drName : 'N/A'}</TableCell>
                                            <TableCell>
                                                {doctorData.refpId ? `${doctorData.refpId.pSalutation}. ${doctorData.refpId.pName}` : 'N/A'}
                                            </TableCell>
                                            <TableCell>{doctorData.fees}</TableCell>
                                            {/* Add similar checks for other properties if needed */}
                                        </TableRow>
                                    ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                    <TablePagination
                        rowsPerPageOptions={[8, 16, 24]}
                        component="div"
                        count={departmentWiseCollectionData.length}
                        rowsPerPage={rowsPerPage}
                        page={page}
                        onPageChange={handleChangePage}
                        onRowsPerPageChange={handleChangeRowsPerPage}
                    />
                </div>
            )}
        </div>
    );
};

export default DeptWiseCollection;
