import React, { useState, useEffect, useRef } from 'react';
import { TextField, Button, Grid, Container } from '@mui/material';
import axios from 'axios';
import { Bar } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

// Register the necessary components
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

const BestPerformedTests = () => {
  const [fromDate, setFromDate] = useState(() => {
    // Set default to one month ago
    const date = new Date();
    date.setMonth(date.getMonth() - 1);
    return date.toISOString().split('T')[0];
  });
  const [toDate, setToDate] = useState(() => {
    // Set default to today
    return new Date().toISOString().split('T')[0];
  });
  const [data, setData] = useState([]);
  const chartRef = useRef(null);

  const fetchData = async () => {
    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      const response = await axios.get(`${apiBaseUrl}/auth/performance`, {
        params: { fromDate, toDate }
      });

      // Aggregate the data by test name
      const aggregatedData = response.data.reduce((acc, test) => {
        if (!acc[test.name]) {
          acc[test.name] = { name: test.name, count: 0 };
        }
        acc[test.name].count += test.count;
        return acc;
      }, {});

      // Convert the aggregated data object to an array
      const aggregatedArray = Object.values(aggregatedData);

      setData(aggregatedArray);
    } catch (error) {
      console.error('Error fetching data:', error);
    }
  };

  useEffect(() => {
    if (fromDate && toDate) {
      fetchData();
    }
  }, [fromDate, toDate]);

  const handleDateChange = (setter) => (event) => {
    setter(event.target.value);
  };

  const colors = [
    'rgba(75, 192, 192, 0.6)',
    'rgba(153, 102, 255, 0.6)',
    'rgba(255, 159, 64, 0.6)',
    'rgba(54, 162, 235, 0.6)',
    'rgba(255, 99, 132, 0.6)',
    'rgba(255, 206, 86, 0.6)',
  ];

  const getColor = (index) => colors[index % colors.length];

  const singleTestsData = {
    labels: data.map(test => test.name),
    datasets: [
      {
        label: 'Tests',
        data: data.map(test => test.count),
        backgroundColor: data.map((_, index) => getColor(index)),
        borderColor: data.map((_, index) => getColor(index)),
        borderWidth: 1,
      },
    ],
  };

  const options = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
      },
      title: {
        display: true,
        text: 'Best Performed Tests',
      },
    },
  };

  const downloadPDF = () => {
    if (chartRef.current) {
      html2canvas(chartRef.current).then(canvas => {
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF();
        const imgWidth = 190; // PDF width
        const pageHeight = 295; // PDF height
        const imgHeight = canvas.height * imgWidth / canvas.width;
        let heightLeft = imgHeight;
        let position = 0;

        pdf.addImage(imgData, 'PNG', 10, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;

        while (heightLeft >= 0) {
          position -= pageHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 10, position, imgWidth, imgHeight);
          heightLeft -= pageHeight;
        }

        pdf.save('best_performed_tests.pdf');
      });
    }
  };

  return (
    <Container>
      <h5 style={{ textAlign: 'left'}}>Best Performed Test  &rarr;</h5>
      <Grid container spacing={3}>
        <Grid item xs={6}>
          <TextField
            type="date"
            label="From Date"
            value={fromDate}
            onChange={handleDateChange(setFromDate)}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={6}>
          <TextField
            type="date"
            label="To Date"
            value={toDate}
            onChange={handleDateChange(setToDate)}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={12}>
          <Button
            variant="contained"
            color="primary"
            onClick={fetchData}
            disabled={!fromDate || !toDate}
          >
            Fetch Data
          </Button>
        </Grid>
        <Grid item xs={12}>
          <Button
            variant="contained"
            color="secondary"
            onClick={downloadPDF}
          >
            Download as PDF
          </Button>
        </Grid>
      </Grid>
      <div ref={chartRef}>
        <Bar data={singleTestsData} options={options} />
      </div>
    </Container>
  );
};

export default BestPerformedTests;
