import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Grid, TextField, Button } from '@mui/material';
import InputLabel from '@mui/material/InputLabel';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import Autocomplete from '@mui/material/Autocomplete';
import { toast } from 'react-toastify';
import './ModelSteps.css'

const ModelSteps = () => {
    const [userRegistration, setUserRegistration] = useState({
        pSalutation: '',
        pName: '',
        pAge: '',
        pGender: '',
        pNum: '',
        pEmail: '',
        doctorName: '',
    });

    const [selectedTests, setSelectedTests] = useState([]);
    const [availableTests, setAvailableTests] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [filteredTests, setFilteredTests] = useState([]);
    const [billAmount, setBillAmount] = useState(0);
    const [amountPaid, setAmountPaid] = useState(0);
    const [amountDue, setAmountDue] = useState(0);
    const [discountPercentage, setDiscountPercentage] = useState(0);
    const [discountAmount, setDiscountAmount] = useState(0);
    const [paymentMethod, setPaymentMethod] = useState('Cash');
    const [paymentError, setPaymentError] = useState('');
    const [patientIdCounter, setPatientIdCounter] = useState();
    const [availableDoctors, setavailableDoctors] = useState([]);

    // Update formIsValid based on required fields
    const [formIsValid, setFormIsValid] = useState(false);

    const [billGenerated, setBillGenerated] = useState(false);
    const [printedBillId, setPrintedBillId] = useState(null);

    const [Iscreated, setIscreated] = useState(false);
    const [isPrinting, setIsPrinting] = useState(false);



    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.get(`${apiBaseUrl}/auth/get-doctors`)
            .then(response => {
                setavailableDoctors(response.data);
            })
            .catch(error => {
                console.error('Error fetching available tests:', error);
            });
    }, []);



    const handleSubmit = () => {
        // Here, you can collect all the data and submit it
        setPatientIdCounter(patientIdCounter + 1);

        const submittedData = {
            userRegistration,
            selectedTests,
        };

        console.log('Submitted Data:', submittedData);

        setIscreated(true);

        // Assuming you have an API endpoint for submission
        axios.post(`${apiBaseUrl}/auth/register`, submittedData)
            .then(response => {
                console.log('Submission successful:', response.data);
                toast.success('Bill Created successfully'); // Display success message
                // Clear the data after successful submission
                setUserRegistration({
                    pId: '',
                    pSalutation: '',
                    pName: '',
                    pAge: '',
                    pGender: '',
                    pNum: '',
                    pEmail: '',
                    doctorName: '',
                });
                setSelectedTests([]);
                setBillGenerated(true); // Set billGenerated to true
                setPrintedBillId(response.data.billId); // Store the generated bill ID

                // Reset bill-related values here
                setBillAmount(0);
                setAmountPaid(0);
                setAmountDue(0);
                setDiscountPercentage(0);
                setDiscountAmount(0);
                // navigate("/bil-list");

                setFormIsValid(false);


            })
            .catch(error => {
                console.error('Submission error:', error);
            }).finally(() => {
                // Perform cleanup or hide loading state if needed
                setIscreated(false);
            });
    }

    useEffect(() => {
        axios.get(`${apiBaseUrl}/auth/next-patient-id`)
            .then(response => {
                setPatientIdCounter(response.data.nextPatientId);
            })
            .catch(error => {
                console.error('Error fetching next patient ID:', error);
            });
    }, []);

    const handleInput = (e) => {
        const name = e.target.name;
        const value = e.target.value;
        let genderValue = userRegistration.pGender; // Preserve the existing gender value

        if (name === 'pSalutation') {
            if (value === 'Mr') {
                genderValue = 'Male';
            } else if (value === 'Miss' || value === 'Mrs') {
                genderValue = 'Female';
            }
        }

        setUserRegistration({ ...userRegistration, [name]: value, pGender: genderValue });
    };

    const handleDoctorSelection = (e) => {
        const selectedDoctor = e.target.value;
        setUserRegistration({ ...userRegistration, doctorName: selectedDoctor });
    };

    const handleAmountPaidChange = (e) => {
        const inputValue = e.target.value;
        const paidAmount = inputValue === '' ? '' : parseFloat(inputValue);

        if (isNaN(paidAmount)) {
            setPaymentError('Invalid input. Please enter a valid number.');
        } else if (paidAmount > billAmount) {
            setPaymentError('Received amount cannot be greater than the bill amount');
        } else {
            setPaymentError('');
            setAmountPaid(paidAmount);
        }
    };

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        const fetchAllTests = async () => {
            try {
                const [testsResponse, groupTestsResponse, profileTestsResponse, feesResponse] = await Promise.all([
                    axios.get(`${apiBaseUrl}/auth/tests`),
                    axios.get(`${apiBaseUrl}/auth/getGroupTestList`),
                    axios.get(`${apiBaseUrl}/auth/getProfileList`),
                    axios.get(`${apiBaseUrl}/auth/getfeesList`),
                ]);

                const testsWithTypes = [
                    ...testsResponse.data.map((test) => ({ ...test, type: 'Test', department: 'Lab' })),
                    ...groupTestsResponse.data.map((test) => ({ ...test, type: 'Group', department: 'Lab' })),
                    ...profileTestsResponse.data.map((test) => ({ ...test, type: 'Profile', department: 'Lab' })),
                    ...feesResponse.data.map((test) => ({ ...test, type: 'OtherFees' })),
                ];

                setAvailableTests(testsWithTypes);
                setFilteredTests(testsWithTypes);
            } catch (error) {
                console.error('Error fetching available tests:', error);
            }
        };

        fetchAllTests();
    }, []);

    useEffect(() => {
        const filtered = availableTests.filter((test) => {
            if (test.type === 'Profile') {
                const profileName = test.profileName || '';
                return profileName.toLowerCase().includes(searchTerm.toLowerCase());
            } else if (test.type === 'Group') {
                const groupName = test.groupName || '';
                return groupName.toLowerCase().includes(searchTerm.toLowerCase());
            } else if (test.type === 'OtherFees') {
                const feesName = test.feesName || '';
                return feesName.toLowerCase().includes(searchTerm.toLowerCase());
            } else {
                const testName = test.name || '';
                return testName.toLowerCase().includes(searchTerm.toLowerCase());
            }
        });

        setFilteredTests(filtered);
    }, [searchTerm, availableTests]);

    useEffect(() => {
        let total = 0;
        selectedTests.forEach((item) => {
            if (item.type === 'Test') {
                total += parseFloat(item.fees);
            } else if (item.type === 'Profile') {
                total += parseFloat(item.profilePrice);
            } else if (item.type === 'Group') {
                total += parseFloat(item.groupPrice);
            } else if (item.type === 'OtherFees') {
                total += parseFloat(item.opFees);
            }
        });
        setBillAmount(total);
    }, [selectedTests, discountPercentage, discountAmount]);

    useEffect(() => {
        const discountValueFromPercentage = (discountPercentage / 100) * billAmount;
        const discountedBillAmount = billAmount - discountValueFromPercentage;
        const finalBillAmount = discountedBillAmount - parseFloat(discountAmount);
        const dueAmount = finalBillAmount - amountPaid;
        setAmountDue(dueAmount);
    }, [billAmount, amountPaid, discountPercentage, discountAmount]);

    useEffect(() => {
        const updatedTests = selectedTests.map((test) => ({
            ...test,
            billAmount,
            amountPaid,
            amountDue,
            discountAmount,
            paymentMethod,
        }));
        setSelectedTests(updatedTests);
    }, [billAmount, amountPaid, amountDue, discountAmount, paymentMethod]);

    const handleTestSelection = (newTests) => {
        const uniqueNewTests = newTests.filter((test) => {
            return !selectedTests.some((selectedTest) => selectedTest._id === test._id);
        });

        setSelectedTests([...selectedTests, ...uniqueNewTests]);
        setSearchTerm('');

        // Check if all required fields are filled
        const isFormValid =
            userRegistration.pSalutation.trim() !== '' &&
            userRegistration.pName.trim() !== '' &&
            userRegistration.pAge.trim() !== '' &&
            userRegistration.pGender.trim() !== '' &&
            userRegistration.pNum.trim() !== '' &&
            userRegistration.doctorName.trim() !== '' &&
            (selectedTests.length + uniqueNewTests.length) > 0;

        setFormIsValid(isFormValid);
    };

    const handleRemoveTest = (testToRemove) => {
        const updatedSelectedTests = selectedTests.filter((test) => test !== testToRemove);
        setSelectedTests(updatedSelectedTests);

        // Check if all required fields are filled
        const isFormValid =
            userRegistration.pSalutation.trim() !== '' &&
            userRegistration.pName.trim() !== '' &&
            userRegistration.pAge.trim() !== '' &&
            userRegistration.pGender.trim() !== '' &&
            userRegistration.pNum.trim() !== '' &&
            userRegistration.doctorName.trim() !== '' &&
            updatedSelectedTests.length > 0;

        setFormIsValid(isFormValid);
    };

    const handlePrintBill = async (billId) => {
        setIsPrinting(true);
        try {
            const apiBaseUrl = process.env.REACT_APP_API_KEY;

            const response = await axios.post(
                `${apiBaseUrl}/auth/print-bill/${billId}`,
                {},
                {
                    responseType: 'blob',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                }
            );

            // Create a blob from the binary data
            const blob = new Blob([response.data], { type: 'application/pdf' });

            // Create a URL for the blob
            const pdfUrl = URL.createObjectURL(blob);

            // Open the PDF in a new tab/window
            window.open(pdfUrl, '_blank');

            setBillGenerated(false);
        } catch (error) {
            // Handle error
            console.error('Error printing bill:', error);
        } finally {
            setIsPrinting(false);
        }
    };


    const renderSelectedTests = () => {
        if (selectedTests.length > 0) {
            return (
                <div className="selected-tests">
                    <h4>Selected Tests:</h4>
                    <ul>
                        {selectedTests.map((test) => {
                            const testName =
                                test.type === 'Profile'
                                    ? test.profileName
                                    : test.type === 'Group'
                                        ? test.groupName
                                        : test.type === 'OtherFees'
                                            ? test.feesName
                                            : test.name;

                            const testPrice =
                                test.type === 'Profile'
                                    ? test.profilePrice
                                    : test.type === 'Group'
                                        ? test.groupPrice
                                        : test.type === 'OtherFees'
                                            ? test.opFees
                                            : test.fees;

                            return (
                                <li key={`${test.type}-${test._id}`}>
                                    {`${test.type} Name: ${testName} - Price: ₹${testPrice}  ${test.units || ''}`}
                                    <Button
                                        variant="contained"
                                        color="secondary"
                                        style={{
                                            backgroundColor: '#8F00FF',
                                            color: 'white',
                                            border: 'none',
                                            fontWeight: 'bold',
                                            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
                                        }}
                                        onClick={() => handleRemoveTest(test)}
                                    >
                                        Remove
                                    </Button>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            );
        }
        return null;
    };

    return (
        <div className="container">
                <h5 style={{ textAlign: 'left'}}>Create Bill &rarr;</h5>

            <Grid container spacing={2} className="registration-section">
                <Grid item sm={12} xs={12}>
                    <h5 style={{ color: '#8F00FF' }}>Enter The Patient Details</h5>
                </Grid >

                <Grid item sm={3} xs={6}>
                    <div>
                        <FormControl fullWidth>
                            <InputLabel id="pSa">Salutation</InputLabel>
                            <Select
                                labelId="pSalutan"
                                id="pSalutation"
                                name="pSalutation"
                                label="Salutation"
                                value={userRegistration.pSalutation}
                                onChange={handleInput}
                            >
                                <MenuItem value="">Select</MenuItem>
                                <MenuItem value={'Mr'}>Mr.</MenuItem>
                                <MenuItem value={'Miss'}>Miss.</MenuItem>
                                <MenuItem value={'Mrs'}>Mrs.</MenuItem>
                            </Select>
                        </FormControl>
                    </div>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <div>
                        <TextField
                            required
                            variant="outlined"
                            label="Full Name"
                            name="pName"
                            id="pName"
                            value={userRegistration.pName}
                            onChange={handleInput}
                        />
                    </div>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <div>
                        <TextField
                            required
                            variant="outlined"
                            label="Age"
                            name="pAge"
                            id="pAge"
                            value={userRegistration.pAge}
                            onChange={handleInput}
                        />
                    </div>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <div>
                        <FormControl fullWidth>
                            <InputLabel id="Gender">Gender</InputLabel>
                            <Select
                                required
                                labelId="Gender"
                                id="pGender"
                                name="pGender"
                                label="Gender"
                                value={userRegistration.pGender}
                                onChange={handleInput}
                            >
                                <MenuItem value={'Male'}>Male</MenuItem>
                                <MenuItem value={'Female'}>Female</MenuItem>
                            </Select>
                        </FormControl>
                    </div>
                </Grid>
                {/* </Grid> */}

                {/* <Grid container spacing={2}  className="registration-section"> */}
                <Grid item sm={3} xs={6}>
                    <div>
                        <TextField
                            required
                            variant="outlined"
                            label="Number"
                            name="pNum"
                            id="pNum"
                            value={userRegistration.pNum}
                            onChange={handleInput}
                        />
                    </div>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <div>
                        <TextField
                            variant="outlined"
                            label="Email"
                            type="email"
                            name="pEmail"
                            id="pEmail"
                            value={userRegistration.pEmail}
                            onChange={handleInput}
                        />
                    </div>
                </Grid>

                <Grid item sm={3} xs={6}>
                    <div>
                        <FormControl fullWidth style={{ width: '300px' }}>
                            <InputLabel id="doctorSelection">Select a Doctor</InputLabel>
                            <Select
                                required
                                labelId="doctorSelection"
                                id="doctorName"
                                value={userRegistration.doctorName}
                                onChange={handleDoctorSelection}
                                variant="outlined"
                            >
                                <MenuItem value="">
                                    <em>Select a Doctor</em>
                                </MenuItem>
                                {availableDoctors.map((doctor) => (
                                    <MenuItem key={doctor._id} value={doctor._id}>
                                        {doctor.drName}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </div>
                </Grid>
            </Grid>

            <div className="select-test-section">
                <h5 style={{ color: '#8F00FF' }}>Select The Tests</h5>

                <Autocomplete
                    style={{ marginTop: '15px' }}
                    multiple
                    options={filteredTests}
                    getOptionLabel={(option) => {
                        if (option.type === 'Profile') {
                            return option.profileName;
                        } else if (option.type === 'Group') {
                            return option.groupName;
                        } else if (option.type === 'OtherFees') {
                            return option.feesName;
                        } else {
                            return option.name;
                        }
                    }}
                    value={selectedTests}
                    onChange={(event, newValue) => {
                        if (newValue) {
                            handleTestSelection(newValue);
                        }
                    }}
                    renderInput={(params) => (
                        <TextField
                            {...params}
                            type="text"
                            label="Search for tests"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    )}
                />

                {renderSelectedTests()}
            </div>

            {/* <h5>Bill Details</h5> */}

            <Grid container spacing={2} style={{ marginTop: '15px' }} className="bill-details-section">

                <Grid item xs={12} sm={12}>
                    <h5 style={{ color: '#8F00FF' }}>Bill Details</h5>
                </Grid >

                <Grid item xs={6} sm={3}>
                    <div>
                        <TextField
                            disabled
                            variant="outlined"
                            label="Bill Amount"
                            name="billAmount"
                            id="billAmount"
                            value={billAmount}
                        />
                    </div>
                </Grid>

                <Grid item xs={6} sm={3}>
                    <div>
                        <TextField
                            variant="outlined"
                            label="Amount Received"
                            name="amountPaid"
                            id="amountReceived"
                            value={amountPaid}
                            onChange={handleAmountPaidChange}
                            error={paymentError !== ''}
                            helperText={paymentError}
                        />
                    </div>
                </Grid>

                <Grid item xs={6} sm={3}>
                    <div>
                        <TextField
                            variant="outlined"
                            label="Amount Due"
                            name="amountDue"
                            id="amountDue"
                            value={amountDue}
                            disabled
                        />
                    </div>
                </Grid>

                <Grid item xs={6} sm={3}>
                    <FormControl fullWidth>
                        <InputLabel id="paymentMethod">Payment Method</InputLabel>
                        <Select
                            labelId="paymentMethod"
                            id="paymentMethod"
                            name="paymentMethod"
                            label="Payment Method"
                            value={paymentMethod}
                            onChange={(e) => setPaymentMethod(e.target.value)}
                        >
                            <MenuItem value={'Cash'}>Cash</MenuItem>
                            <MenuItem value={'Card'}>Card</MenuItem>
                            <MenuItem value={'UPI'}>UPI</MenuItem>
                        </Select>
                    </FormControl>
                </Grid>
                {/* </Grid> */}

                {/* <Grid container spacing={2} className="bill-details-section"> */}
                <Grid item xs={6} sm={3}>
                    <div>
                        <TextField
                            disabled
                            label="Calculated Discount"
                            variant="outlined"
                            name="discountAmount"
                            id="discountAmount"
                            value={discountPercentage / 100 * billAmount + parseFloat(discountAmount)}
                        />
                    </div>
                </Grid>

                <Grid item xs={6} sm={3}>
                    <div>
                        <TextField
                            label="Discount Percentage"
                            variant="outlined"
                            value={discountPercentage}
                            onChange={(e) => setDiscountPercentage(e.target.value)}
                        />
                    </div>
                </Grid>

                <Grid item xs={6} sm={3}>
                    <div>
                        <TextField
                            label="Discount Amount"
                            variant="outlined"
                            value={discountAmount}
                            onChange={(e) => setDiscountAmount(e.target.value)}
                        />
                    </div>
                </Grid>

            </Grid>


            <div style={{ display: 'flex', justifyContent: 'center' }} className='downButtons'>
                <div style={{ marginRight: '10px' }}>
                    <Button
                        disabled={Iscreated || !formIsValid}
                        variant="contained"
                        color="primary"
                        onClick={handleSubmit}
                    // disabled={}
                    >
                        {Iscreated ? 'Creating Bill ...' : 'Create Bill'}
                    </Button>
                </div>

                {billGenerated && (
                    <div>
                        <Button
                            disabled={isPrinting}
                            variant="contained"
                            color="secondary"
                            onClick={() => handlePrintBill(printedBillId)}
                        >
                            {isPrinting ? 'Printing ...' : 'Print Bill'}
                        </Button>
                    </div>
                )}
            </div>

        </div>
    );
};

export default ModelSteps;
