import React, { useState, useEffect } from 'react';
import axios from 'axios';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import {
    Table,
    TableContainer,
    TableHead,
    TableRow,
    TableCell,
    TableBody,
    TextField,
    Paper,
    Grid,
    Button,
    TablePagination,
} from '@mui/material';
import CollectionNav from './CollectionNav';

const RegistrationReport = () => {
    const [dailyCollectionData, setDailyCollectionData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedDate, setSelectedDate] = useState(new Date());

    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(8);

    useEffect(() => {
        const formattedDate = selectedDate.toISOString().split('T')[0];
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        axios
            .get(`${apiBaseUrl}/auth/dailyRegistration/${formattedDate}`)
            .then((response) => {
                setDailyCollectionData(response.data);
                setIsLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching daily collection data:', error);
                setIsLoading(false);
            });
    }, [selectedDate]);

    const downloadExcelFile = async () => {
        const formattedDate = selectedDate.toISOString().split('T')[0];
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        try {
            const response = await axios.get(
                `${apiBaseUrl}/auth/downloadRegistration/${formattedDate}`,
                {
                    responseType: 'blob',
                }
            );

            const blob = new Blob([response.data], {
                type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'daily-registration.xlsx';
            a.click();

            window.URL.revokeObjectURL(url);
        } catch (error) {
            console.error('Error downloading Excel file:', error);
        }
    };

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    return (
        <div className="container">
            <CollectionNav />
            <h5 style={{ textAlign: 'center' }}>Registration Report</h5>
            <DatePicker
                selected={selectedDate}
                onChange={(date) => setSelectedDate(date)}
                dateFormat="yyyy-MM-dd"
            />
            <Button
                style={{
                    backgroundColor: '#8F00FF',
                    color: 'white',
                    border: 'none',
                }}
                variant="contained"
                color="primary"
                onClick={downloadExcelFile}
            >
                Download Excel
            </Button>
            <Grid container spacing={2} style={{ marginTop: '20px' }}>
                {/* Box 1: Number of Bills */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
                        <strong>Total Registration's</strong>
                        <br />
                        {dailyCollectionData.length}
                    </Paper>
                </Grid>
            </Grid>

            {isLoading ? (
                // <p>Loading...</p>
                <img
                    src={require('../../assets/images/loading.gif')}
                    alt="bb"
                    style={{ width: '100px', height: '100px' }}
                />
            ) : (
                <div>
                    <TableContainer component={Paper}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>
                                        <strong>Date</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Patient Name</strong>
                                    </TableCell>
                                      <TableCell>
                                        <strong>Gender</strong>
                                    </TableCell> 
                                     <TableCell>
                                        <strong>Age</strong>
                                    </TableCell> 
                                    <TableCell>
                                        <strong>Contact No.</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Email</strong>
                                    </TableCell>
                                   
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {dailyCollectionData
                                    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                                    .map((item) => (
                                        <TableRow key={item._id}>
                                            <TableCell>{item.createdAt}</TableCell>
                                            {/* <TableCell>{item.billId}</TableCell> */}
                                            <TableCell>
                                                {item.pSalutation}. {item.pName}
                                            </TableCell>
                                            <TableCell>{item.pGender}</TableCell>
                                            <TableCell>{item.pAge}</TableCell>
                                            <TableCell>{item.pNum}</TableCell>
                                            <TableCell>{item.pEmail}</TableCell>
                                        </TableRow>
                                    ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                    <TablePagination
                        rowsPerPageOptions={[8, 16, 24]}
                        component="div"
                        count={dailyCollectionData.length}
                        rowsPerPage={rowsPerPage}
                        page={page}
                        onPageChange={handleChangePage}
                        onRowsPerPageChange={handleChangeRowsPerPage}
                    />
                </div>
            )}
        </div>
    );
};

export default RegistrationReport;
