import axios from 'axios';
import React, { useState, useEffect } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TextField,
  TableRow,
  Paper,
} from '@mui/material';
import { Link } from 'react-router-dom';
import { Button, Modal } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { TablePagination } from '@mui/material';

const GroupTestList = () => {
  const navigate = useNavigate();
  const [testMasters, setTestMasters] = useState([]);
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [testToDelete, setTestToDelete] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10); // Set rowsPerPage to 10

 
  const filteredTests = testMasters.filter((test) =>
    test.groupCategory.toLowerCase().includes(searchTerm.toLowerCase()) ||
    test.groupName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = () => {
    navigate("/create-group-test");
  };

  useEffect(() => {
    const apiBaseUrl = process.env.REACT_APP_API_KEY;
    axios
      .get(`${apiBaseUrl}/auth/getGroupTestList`)
      .then((response) => {
        setTestMasters(response.data);
        setIsLoading(false);
      })
      .catch((error) => {
        console.error('Error fetching Group Tests:', error);
        setIsLoading(false);
      });
  }, []);

  const handleDelete = (groupId) => {
    setTestToDelete(groupId);
    setShowConfirmation(true);
  };

  const handleConfirmDelete = () => {
    setShowConfirmation(false);

    const apiBaseUrl = process.env.REACT_APP_API_KEY;
    axios
      .delete(`${apiBaseUrl}/auth/deleteGroup/${testToDelete}`)
      .then((response) => {
        toast.success('Group test deleted successfully');
        setTestMasters(testMasters.filter((test) => test._id !== testToDelete));
      })
      .catch((error) => {
        console.error('Error deleting Group Test:', error);
      });
  };

  const handleCancelDelete = () => {
    setShowConfirmation(false);
    setTestToDelete(null);
  };

  const exportToExcel = () => {
    setIsExporting(true);
    const apiBaseUrl = process.env.REACT_APP_API_KEY;
    axios.get(`${apiBaseUrl}/auth/export-groupTest`, { responseType: 'blob' })
      .then((response) => {
        const blob = new Blob([response.data], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'GroupTestList.xlsx';
        a.click();
        window.URL.revokeObjectURL(url);
        setIsExporting(false);
      })
      .catch((error) => {
        console.error('Error exporting to Excel:', error);
        setIsExporting(false);
      });
  };

  if (isLoading) {
    return (
      <img
        src={require('../../assets/images/loading.gif')}
        alt="bb"
        style={{ width: '100px', height: '100px' }}
      />
    );
  }

  return (
    <>
      <div className='container'>
      <h5 style={{ textAlign: 'left' }}>Group List &rarr;</h5>
        <Button onClick={handleSubmit} style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none', marginBottom: '10px' }}>
          Create Test
        </Button>
        <Button onClick={exportToExcel} style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none', marginBottom: '10px', marginLeft: '10px' }}>
          {isExporting ? 'Exporting...' : 'Export List'}
        </Button>
        <TableContainer component={Paper} >
          <TextField
            type="text"
            placeholder="Search Test Name"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={{marginBottom: '10px'}}
          />
          <Table>
            <TableHead style={{backgroundColor:'#8F00FF'}}>
              <TableRow>
                <TableCell style={{ color:'white'}}><strong>Test Category</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Name</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Price</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Edit/Delete</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredTests.slice(page * rowsPerPage, (page + 1) * rowsPerPage).map((test) => (
                <TableRow key={test._id}>
                  <TableCell>{test.groupCategory}</TableCell>
                  <TableCell>{test.groupName}</TableCell>
                  <TableCell>{test.groupPrice}</TableCell>
                  <TableCell>
                    <Link to={`/editGroupTest/${test._id}`}>
                      <Button style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>Edit</Button>
                    </Link>
                    <Button onClick={() => handleDelete(test._id)} style={{ backgroundColor: 'red', color: 'white', border: 'none' }}>Delete</Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          <TablePagination
            component="div"
            count={filteredTests.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={(event, newPage) => setPage(newPage)}
            onRowsPerPageChange={(event) => {
              setRowsPerPage(parseInt(event.target.value, 10));
              setPage(0);
            }}
            rowsPerPageOptions={[5, 10, 25]}
          />
        </TableContainer>
      </div>
      <Modal show={showConfirmation} onHide={handleCancelDelete}>
        <Modal.Header closeButton>
          <Modal.Title>Confirm Deletion</Modal.Title>
        </Modal.Header>
        <Modal.Body>Are you sure you want to delete this group test?</Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCancelDelete}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleConfirmDelete}>
            Delete
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default GroupTestList;
