// export default Header;

import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Navbar, Nav, NavDropdown } from 'react-bootstrap';
import { useAuth } from './AuthContext';
import { useNavigate } from 'react-router-dom';
import './Header.css';

const Header = () => {
    const navigate = useNavigate();
    const location = useLocation();

    const { user, logout, userName } = useAuth();
    const [userPermissions, setUserPermissions] = useState([]);
    const [isLoading, setLoading] = useState(true);
    const [isCollapsed, setIsCollapsed] = useState(true); // Manage collapse state

    useEffect(() => {
        if (user) {
            const apiBaseUrl = process.env.REACT_APP_API_KEY;
            fetch(`${apiBaseUrl}/auth/getAccess/${user}`)
                .then((response) => response.json())
                .then((data) => setUserPermissions(data.permissions))
                .catch((error) => console.error('Error fetching user permissions:', error))
                .finally(() => setLoading(false));
        }
    }, [user]);

    const hasPermission = (permission) => userPermissions.includes(permission);

    const handleLogout = () => {
        logout();
        navigate('/');
    };

    const getNavLinkStyle = (path) => {
        return {
            color: location.pathname === path ? 'white' : 'white',
            borderBottom: location.pathname === path ? '2px solid white' : 'none',
            marginLeft: '30px', // Add left margin
            fontWeight: location.pathname === path ? 'bold' : 'normal',
        };
    };

    // Toggle the collapse state
    const handleNavClick = () => {
        setIsCollapsed(true); // Collapse navbar after clicking
    };

    return (
        <div className='container-fluid'>
            <Navbar expand="lg" style={{ marginBottom: '20px', backgroundColor: '#8F00FF' }} expanded={!isCollapsed}>
                <Navbar.Brand as={Link} to="/dash">
                    <img
                        src={require('../../assets/images/home.png')}
                        alt="bb"
                        style={{ width: '40px', height: '40px' }}
                    />
                </Navbar.Brand>
                <Navbar.Toggle 
                    aria-controls="basic-navbar-nav" 
                    onClick={() => setIsCollapsed(!isCollapsed)} // Toggle the navbar
                />
                <Navbar.Collapse id="basic-navbar-nav" className="justify-content-start" style={{ color: 'white' }}>

                    <Nav className="mr-auto">
                        {isLoading ? null : (
                            <>
                                {user && (
                                    <>
                                        {hasPermission('createBill') && (
                                            <Nav.Link 
                                                as={Link} 
                                                to="/steps" 
                                                style={getNavLinkStyle('/steps')} 
                                                onClick={handleNavClick} // Close navbar after click
                                            >
                                                Create Bill
                                            </Nav.Link>
                                        )}

                                        {hasPermission('Bills') && (
                                            <Nav.Link 
                                                as={Link} 
                                                to="/bil-list" 
                                                style={getNavLinkStyle('/bil-list')} 
                                                onClick={handleNavClick} // Close navbar after click
                                            >
                                                Bills
                                            </Nav.Link>
                                        )}

                                        {hasPermission('LabReports') && (
                                            <Nav.Link 
                                                as={Link} 
                                                to="/reportList" 
                                                style={getNavLinkStyle('/reportList')} 
                                                onClick={handleNavClick} // Close navbar after click
                                            >
                                                Reports
                                            </Nav.Link>
                                        )}

                                        {hasPermission('UpdatePatient') && (
                                            <Nav.Link 
                                                as={Link} 
                                                to="/patient-list" 
                                                style={getNavLinkStyle('/patient-list')} 
                                                onClick={handleNavClick} // Close navbar after click
                                            >
                                                Patients
                                            </Nav.Link>
                                        )}

                                        <NavDropdown title={<span className="dropdown-text">Masters</span>} className='masters dropdown-container'>
                                            {isLoading ? null : (
                                                <>
                                                    {hasPermission('createDoctor') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/doctor-list" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            Doctor Master
                                                        </NavDropdown.Item>
                                                    )}
                                                    {hasPermission('feesMaster') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/feesMaster" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            Fees Master
                                                        </NavDropdown.Item>
                                                    )}
                                                     {hasPermission('TestMasterList') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/test-list" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            Test Master
                                                        </NavDropdown.Item>
                                                    )}
                                                    {hasPermission('GroupMasterList') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/group-list" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            Group Master
                                                        </NavDropdown.Item>
                                                    )}
                                                    
                                                    {hasPermission('ProfileMasterList') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/profileList" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            Profile Master
                                                        </NavDropdown.Item>
                                                    )}
                                                    {hasPermission('StaffManagement') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/createUser" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            User Master
                                                        </NavDropdown.Item>
                                                    )}
                                                    {hasPermission('UserAccess') && (
                                                        <NavDropdown.Item 
                                                            as={Link} 
                                                            to="/userAccess" 
                                                            onClick={handleNavClick} // Close navbar after click
                                                        >
                                                            User Access Master
                                                        </NavDropdown.Item>
                                                    )}
                                                    
                                                    {/* Add more conditionally rendered NavDropdown.Item items based on permissions */}
                                                </>
                                            )}
                                        </NavDropdown>

                                        <NavDropdown title={<span className="dropdown-text">Accounts</span>} className='accounts dropdown-container'>
                                            {hasPermission('CollReports') && (
                                                <>
                                                    <NavDropdown.Item 
                                                        as={Link} 
                                                        to="/dailyCollection" 
                                                        onClick={handleNavClick} // Close navbar after click
                                                    >
                                                        Daily Collection
                                                    </NavDropdown.Item>

                                                    {/* Uncomment the following line if needed */} 
                                                    {/* <NavDropdown.Item as={Link} to="/doctorWise">Doctor Collection</NavDropdown.Item> */}
                                                    <NavDropdown.Item 
                                                        as={Link} 
                                                        to="/dueReport" 
                                                        onClick={handleNavClick} // Close navbar after click
                                                    >
                                                        Due Report
                                                    </NavDropdown.Item>
                                                    <NavDropdown.Item 
                                                        as={Link} 
                                                        to="/doctorWise" 
                                                        onClick={handleNavClick} // Close navbar after click
                                                    >
                                                        Doctor Wise Collection
                                                    </NavDropdown.Item>
                                                    <NavDropdown.Item 
                                                        as={Link} 
                                                        to="/deptWise" 
                                                        onClick={handleNavClick} // Close navbar after click
                                                    >
                                                        Department Wise Collection
                                                    </NavDropdown.Item>
                                                    <NavDropdown.Item 
                                                        as={Link} 
                                                        to="/monthlyCollection" 
                                                        onClick={handleNavClick} // Close navbar after click
                                                    >
                                                        Monthly Collection
                                                    </NavDropdown.Item>
                                                    <NavDropdown.Item 
                                                        as={Link} 
                                                        to="/regReport" 
                                                        onClick={handleNavClick} // Close navbar after click
                                                    >
                                                        Registration Report
                                                    </NavDropdown.Item>
                                                </>
                                            )}
                                        </NavDropdown>
                                    </>
                                )}
                            </>
                        )}
                    </Nav>

                    <Nav>
                        {user ? (
                            <>
                                <Navbar.Text className="text-white mr-3" >Logged in as: {userName}</Navbar.Text>
                                <Nav.Link className="text-white" onClick={handleLogout}>
                                    Logout
                                </Nav.Link>
                            </>
                        ) : (
                            // Add login-related Nav.Link items for users who are not logged in
                            <>
                                {/* <Nav.Link as={Link} to="/login" style={{ color: 'white' }} >
                                    Login
                                </Nav.Link>
                                <Nav.Link as={Link} to="/register" style={{ color: 'white' }} >
                                    Register
                                </Nav.Link> */}
                            </>
                        )}
                    </Nav>
                </Navbar.Collapse>
            </Navbar>
        </div>
    );
};

export default Header;
