import React, { useEffect, useState } from 'react';
import axios from 'axios';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
import { Grid } from '@mui/material';
import { toast } from 'react-toastify';
import Select from '@mui/material/Select';
import MenuItem from '@mui/material/MenuItem';
import UserManagement from './UserManagment';

const UserUpdate = () => {
  const [users, setUsers] = useState([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [userData, setUserData] = useState({
    username: '',
    password: '',
  });

  useEffect(() => {
    // Fetch the list of users from the backend and update the state
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      const response = await axios.get(`${apiBaseUrl}/auth/getUser`); // Replace with your actual backend route
      const users = response.data; // Assuming the response contains a list of users
      setUsers(users);
    } catch (error) {
      console.error('Error fetching users:', error);
    }
  };

  const handleUserSelect = (event) => {
    const selectedUserId = event.target.value;
    setSelectedUserId(selectedUserId);

    // After selecting a user, fetch their data and update the state
    fetchUserData(selectedUserId);
  };

  const fetchUserData = async (userId) => {
    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      const response = await axios.get(`${apiBaseUrl}/auth/getUser/${userId}`); // Replace with your actual backend route
      const userData = response.data; // Assuming the response contains user data
      setUserData(userData);
    } catch (error) {
      console.error('Error fetching user data:', error);
    }
  };

  const handleInputChange = (field) => (event) => {
    setUserData({ ...userData, [field]: event.target.value });
  };

  const handleUpdateUser = async (event) => {
    event.preventDefault();

    try {
      // Send a PUT request to update the user
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      await axios.put(`${apiBaseUrl}/auth/updateUser/${selectedUserId}`, userData);
      console.log('User updated successfully');
      toast.success('User updated successfully');
    } catch (error) {
      console.error('Error updating user:', error);
    }
  };

  return (
    <div className='container'>
      <UserManagement />
      <h5 style={{ textAlign: 'left', marginTop: '20px' }}>Update User &rarr;</h5>
      <Grid container spacing={2}>
        <Grid item xs={12}>
          <Select
            required
            label="Select User"
            variant="outlined"
            fullWidth
            value={selectedUserId}
            onChange={handleUserSelect}
          >
            {users.map((user) => (
              <MenuItem key={user._id} value={user._id}>
                {user.username}
              </MenuItem>
            ))}
          </Select>
        </Grid>
        <Grid item xs={12}>
          <form onSubmit={handleUpdateUser}>
            <TextField
              label="Username"
              variant="outlined"
              fullWidth
              value={userData.username}
              onChange={handleInputChange('username')}
            />

            <TextField
              style={{ marginTop: '15px' }}
              label="Password (optional)"
              variant="outlined"
              fullWidth
              type="password"
              value={userData.password}
              onChange={handleInputChange('password')}
            />

            <Button
              style={{  backgroundColor: '#8F00FF', color: 'white', border: 'none', marginTop: '15px' }}
              variant="contained"
              color="primary"
              type="submit"
              fullWidth
            >
              Update User
            </Button>
          </form>
        </Grid>
      </Grid>
    </div>
  );
};

export default UserUpdate;
