// export default OutSource;

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import { Grid, TextField, FormControl, InputLabel, MenuItem, Select, Button } from '@mui/material';

const OutSource = () => {
    const { patientId } = useParams();
    const [pdfUrl, setPdfUrl] = useState(null);
    const [isLoading, setIsLoading] = useState(true);

    const [patientDetails, setPatientDetails] = useState({
        pId: '',
        billId: '',
        pSal: '',
        pName: '',
        pAge: '',
        pGender: '',
        pNum: '',
        pEmail: '',
        doctorName: '',
    });

    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    useEffect(() => {
        if (patientId) {
            fetchPatientDetails(patientId);
            fetchPdf();
        }
        // Cleanup object URL
        return () => {
            if (pdfUrl) URL.revokeObjectURL(pdfUrl);
        };
    }, [patientId]);

    const fetchPatientDetails = async (patientId) => {
        try {
            const response = await axios.get(`${apiBaseUrl}/auth/findPatientByidnewVisit/${patientId}`);
            setPatientDetails(response.data);
        } catch (error) {
            console.error('Error fetching patient details:', error);
            toast.error('Failed to fetch patient details');
        }
    };

    const fetchPdf = async () => {
        setIsLoading(true);
        try {
            const response = await axios.post(
                `${apiBaseUrl}/auth/find-pdf/${patientId}`,
                {},
                { responseType: 'blob' }
            );

            const blob = new Blob([response.data], { type: 'application/pdf' });
            const url = URL.createObjectURL(blob);
            setPdfUrl(url);
        } catch (error) {
            console.error('Error fetching PDF:', error);
            toast.error('Failed to load prescription PDF');
        } finally {
            setIsLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setPatientDetails((prev) => ({ ...prev, [name]: value }));
    };

    return (
        <div style={{ padding: '20px' }} className='container'>
            {/* <h3>Patient Details</h3> */}
            <h5>Patient Details &rarr;</h5>


            <Grid container spacing={2}>
                <Grid item sm={3} xs={6}>
                    <FormControl fullWidth>
                        <InputLabel>Salutation</InputLabel>
                        <Select 
                            name="pSal" 
                            value={patientDetails.pSal} 
                            onChange={handleInputChange}
                        >
                            <MenuItem value="">Select</MenuItem>
                            <MenuItem value="Mr">Mr.</MenuItem>
                            <MenuItem value="Miss">Miss.</MenuItem>
                            <MenuItem value="Mrs">Mrs.</MenuItem>
                        </Select>
                    </FormControl>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField 
                        fullWidth 
                        label="Full Name" 
                        name="pName" 
                        value={patientDetails.pName} 
                        onChange={handleInputChange} 
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField 
                        fullWidth 
                        label="Age" 
                        name="pAge" 
                        type="number"
                        value={patientDetails.pAge} 
                        onChange={handleInputChange} 
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <FormControl fullWidth>
                        <InputLabel>Gender</InputLabel>
                        <Select 
                            name="pGender" 
                            value={patientDetails.pGender} 
                            onChange={handleInputChange}
                        >
                            <MenuItem value="Male">Male</MenuItem>
                            <MenuItem value="Female">Female</MenuItem>
                        </Select>
                    </FormControl>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField 
                        fullWidth 
                        label="Phone Number" 
                        name="pNum" 
                        value={patientDetails.pNum} 
                        onChange={handleInputChange}
                        inputProps={{ pattern: "[0-9]{10}", maxLength: 10 }}
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField 
                        fullWidth 
                        label="Email" 
                        name="pEmail" 
                        type="email"
                        value={patientDetails.pEmail} 
                        onChange={handleInputChange} 
                    />
                </Grid>
            </Grid>

            <h3 style={{ marginTop: '20px' }}></h3>
            {isLoading ? (
                <p>Loading PDF...</p>
            ) : (
                <div style={{ height: '600px', marginTop: '20px' }}>
                    {pdfUrl && (
                        <iframe
                            title="prescription-pdf"
                            src={pdfUrl}
                            width="100%"
                            height="100%"
                            style={{ border: '1px solid #ddd', borderRadius: '4px' }}
                        />
                    )}
                </div>
            )}

            <Button 
                variant="contained" 
                color="primary" 
                style={{ marginTop: '20px' }}
                onClick={() => {
                    const link = document.createElement('a');
                    link.href = pdfUrl;
                    link.download = `lab-report-${patientId}.pdf`;
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);
                }}
                disabled={!pdfUrl}
            >
                Download Report
            </Button>
        </div>
    );
};

export default OutSource;