import axios from 'axios';
import React, { useState, useEffect } from 'react'
import { Grid, TextField, Button } from '@mui/material';
import { FormControl, InputLabel, MenuItem, Select } from '@mui/material';
import { TextareaAutosize } from '@mui/base/TextareaAutosize';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';

const UpdatePatient = () => {

    const { pId } = useParams();

    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    const [availableDoctors, setavailableDoctors] = useState([]);



    const [patientDetails, setpatientDetails] = useState({
        pId: '',
        pSalutation: '',
        pName: '',
        pGender: '',
        pAge: '',
        pEmail: '',
        pNum: '',
        doctorName: ''
    });



    useEffect(() => {
        axios.get(`${apiBaseUrl}/auth/findPatientByid/${pId}`)
            .then(response => {
                setpatientDetails(response.data);
            })
            .catch(error => {
                console.error('Error fetching patient details:', error);
            });
    }, [pId]);

    useEffect(() => {
        axios.get(`${apiBaseUrl}/auth/get-doctors`)
            .then(response => {
                setavailableDoctors(response.data);
            })
            .catch(error => {
                console.error('Error fetching available tests:', error);
            });
    }, []);


    const handleInput = (e) => {
        const name = e.target.name;
        const value = e.target.value;

        let genderValue = patientDetails.pGender; // Preserve the existing gender value

        if (name === "pSalutation") {
            // Only change genderValue if the name is "pSalutation"
            if (value === "Mr") {
                genderValue = "Male";
            } else if (value === "Miss" || value === "Mrs") {
                genderValue = "Female";
            }
        }

        setpatientDetails({ ...patientDetails, [name]: value, pGender: genderValue });
    }

    const handleSubmit = (e) => {

        e.preventDefault(); // Prevent default form submission behavior

        // Here, you can collect all the data and submit it
        // Here, you can collect all the data and submit it
        const updatedData = patientDetails;

        console.log('Submitted Data:', updatedData);

        // Assuming you have an API endpoint for submission

        axios.put(`${apiBaseUrl}/auth/update-patient/${pId}`, updatedData)
            .then(response => {
                toast.success('Patient Updated successfully'); // Display success message
                // console.log('Submission successful:', response.data);
                // Clear the data after successful submission
                setpatientDetails({
                    pId: '',
                    pSalutation: '',
                    pName: '',
                    pGender: '',
                    pAge: '',
                    pEmail: '',
                    pNum: '',
                    doctorName: '',
                });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    }

    const handleDoctorSelection = (e) => {
        const selectedDoctor = e.target.value;
        setpatientDetails({ ...patientDetails, doctorName: selectedDoctor });
    };

    return (
        <>
            <div className='container'>
                <h5 style={{ textAlign: 'left' }}>Update Patient &rarr;</h5>
                <form action="" onSubmit={handleSubmit}>
                    <Grid container spacing={2}>

                        <Grid item xs={3} style={{ display: 'none' }}>
                            <div>
                                <TextField
                                    variant="outlined"
                                    label="Patient ID"
                                    name="pId"
                                    id="pId"
                                    value={patientDetails.pId}
                                    InputProps={{
                                        readOnly: true,
                                    }}
                                />
                            </div>
                        </Grid>

                        <Grid item xs={3} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth>
                                    <InputLabel id="pSa">Salutation</InputLabel>
                                    <Select
                                        labelId="pSalutan"
                                        id="pSalutation"
                                        name="pSalutation"
                                        label="Salutation"
                                        value={patientDetails.pSalutation}
                                        onChange={handleInput}
                                    >
                                        <MenuItem value="">Select</MenuItem>
                                        <MenuItem value={"Mr"} >Mr.</MenuItem>
                                        <MenuItem value={"Miss"}>Miss.</MenuItem>
                                        <MenuItem value={"Mrs"}>Mrs.</MenuItem>
                                    </Select>
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={9} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Name" name="pName" id="pName" value={patientDetails.pName} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>

                        {/* <Grid item xs={4}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Gender" name="pGender" id="pGender" value={patientDetails.pGender} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid> */}



                    </Grid>

                    <Grid container spacing={2}>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Gender" name="pGender" id="pGender" value={patientDetails.pGender} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Age" name="pAge" id="pAge" value={patientDetails.pAge} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Email" name="pEmail" id="pEmail" value={patientDetails.pEmail} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Number" name="pNum" id="pNum" value={patientDetails.pNum} onChange={handleInput} />
                                </FormControl>
                            </div>
                        </Grid>
                    </Grid>

                    {/* <Grid container spacing={2}>
                        <Grid item xs={12} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >

                                    <TextareaAutosize variant="outlined" label="Address" name="pAddress" id="pAddress" minRows="10" value={patientDetails.pAddress} onChange={handleInput}> </TextareaAutosize>
                                </FormControl>

                            </div>
                        </Grid>
                    </Grid> */}

                    <Grid container spacing={2}>
                        <Grid item xs={6} style={{ marginBottom: '20px' }}>
                            <FormControl fullWidth>
                                <InputLabel id="doctorSelection">Select a Doctor</InputLabel>
                                <Select
                                    labelId="doctorSelection"
                                    id="doctorName"
                                    value={patientDetails.doctorName}
                                    onChange={handleDoctorSelection}
                                    variant="outlined"
                                >
                                    <MenuItem value="">
                                        <em>Select a Doctor</em>
                                    </MenuItem>
                                    {availableDoctors.map((doctor) => (
                                        <MenuItem key={doctor} value={doctor._id}>
                                            {doctor.drName}
                                        </MenuItem>
                                    ))}
                                </Select>
                            </FormControl>
                        </Grid>
                    </Grid>


                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <div>
                                <Button type='submit' style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }} >UPDATE</Button>
                            </div>
                        </Grid>
                    </Grid>
                </form>
            </div>
        </>
    )
}

export default UpdatePatient