// export default DoctorList

import axios from 'axios';
import React, { useEffect, useState } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
} from '@mui/material';
import { Link } from 'react-router-dom';
import { Button, Modal } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';

const DoctorList = () => {
  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  const [doctorList, setDoctorList] = useState([]);
  const [showConfirmation, setShowConfirmation] = useState(false); // State for confirmation dialog
  const [doctorToDelete, setDoctorToDelete] = useState(null); // State to store the doctor to delete
  const [isLoading, setIsLoading] = useState(true); // Added loading state
  const navigate = useNavigate();

  useEffect(() => {
    axios
      .get(`${apiBaseUrl}/auth/get-doctors`)
      .then((response) => {
        setDoctorList(response.data);
        setIsLoading(false); // Set loading to false when data is fetched
      })
      .catch((error) => {
        console.error('Error fetching available tests:', error);
        setIsLoading(false); // Set loading to false on error
      });
  }, []);

  const handleSubmit = () => {
    navigate('/create-doctor');
  };

  const handleDelete = (doctorId) => {
    // Set the doctor to be deleted
    setDoctorToDelete(doctorId);
    // Show the confirmation dialog
    setShowConfirmation(true);
  };

  const handleConfirmDelete = () => {
    // Close the confirmation dialog
    setShowConfirmation(false);

    // Perform the delete operation
    axios
      .delete(`${apiBaseUrl}/auth/delete-doctor/${doctorToDelete}`)
      .then((response) => {
        toast.success('Doctor deleted successfully');
        // Update the doctor list after deletion
        setDoctorList(doctorList.filter((doctor) => doctor._id !== doctorToDelete));
      })
      .catch((error) => {
        console.error('Error deleting doctor:', error);
      });
  };

  const handleCancelDelete = () => {
    // Close the confirmation dialog and clear the doctor to delete
    setShowConfirmation(false);
    setDoctorToDelete(null);
  };

  if (isLoading) {
    return <img
    src={require('../../assets/images/loading.gif')}
    alt="bb"
    style={{ width: '100px', height: '100px' }}
  /> // Render loading indicator
  }

  return (
    <>
      <div className="container">
        <h5 style={{ textAlign: 'left' }}>Doctors &rarr;</h5>
        <Button onClick={handleSubmit} style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none', marginBottom:'10px'}}>Create Doctor</Button>
        <TableContainer component={Paper}>
          <Table>
            <TableHead  style={{backgroundColor:'#8F00FF'}}> 
              <TableRow >
                <TableCell style={{ color:'white'}}>
                  <strong>Name</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Gender</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Email</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Number</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Address</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Edit/Delete</strong>
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {doctorList.map((doctor) => (
                <TableRow key={doctor._id}>
                  <TableCell>{doctor.drName}</TableCell>
                  <TableCell>{doctor.drGender}</TableCell>
                  <TableCell>{doctor.drEmail}</TableCell>
                  <TableCell>{doctor.drNum}</TableCell>
                  <TableCell>{doctor.drAddress}</TableCell>
                  <TableCell>
                    <Link to={`/doctor/${doctor._id}`}>
                      <Button style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>Edit</Button>
                    </Link>
                    <Button onClick={() => handleDelete(doctor._id)} style={{ backgroundColor: 'red', color: 'white', border: 'none' }}>Delete</Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </div>

      {/* Confirmation dialog for deleting doctors */}
      <Modal show={showConfirmation} onHide={handleCancelDelete}>
        <Modal.Header closeButton>
          <Modal.Title>Confirm Deletion</Modal.Title>
        </Modal.Header>
        <Modal.Body>Are you sure you want to delete this doctor?</Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCancelDelete}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleConfirmDelete}>
            Delete
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default DoctorList;
