import React, { useEffect, useState } from 'react';
import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, Button } from '@mui/material';
import axios from 'axios';
import { toast } from 'react-toastify';
import UserManagement from './UserManagment';


const UserDelete = () => {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    // Fetch the list of users from your backend API
    const apiBaseUrl = process.env.REACT_APP_API_KEY;
    axios
      .get(`${apiBaseUrl}/auth/getUser`) // Replace with your actual API endpoint
      .then((response) => {
        // Assuming the response.data contains the list of users
        setUsers(response.data);
      })
      .catch((error) => {
        console.error('Error fetching users:', error);
      });
  }, []);

  const handleDeleteUser = (userId) => {
    // Send a DELETE request to delete the user by ID
    const apiBaseUrl = process.env.REACT_APP_API_KEY;
    axios
      .delete(`${apiBaseUrl}/auth/deleteUser/${userId}`) // Replace with your actual API endpoint
      .then((response) => {
        console.log('User deleted successfully:', response.data.message);
      toast.success('User deleted successfully');
        // Update the user list by removing the deleted user
        setUsers((prevUsers) => prevUsers.filter((user) => user._id !== userId));
      })
      .catch((error) => {
        console.error('Error deleting user:', error);
      });
  };

  return (
    <div className='container'>
        <UserManagement />
        <h5 style={{ textAlign: 'left',marginTop:'20px'  }}>Delete User &rarr;</h5>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              {/* <TableCell>ID</TableCell> */}
              <TableCell><strong>Username</strong></TableCell>
              <TableCell><strong>Action</strong></TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {users.map((user) => (
              <TableRow key={user._id}>
                {/* <TableCell>{user._id}</TableCell> */}
                <TableCell>{user.username}</TableCell>
                <TableCell>
                  <Button
                    variant="contained"
                    color="secondary"
                    onClick={() => handleDeleteUser(user._id)}
                  >
                    Delete
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </div>
  );
};

export default UserDelete;
