import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import { createRoot } from 'react-dom/client';
import ModelSteps from './Components/Reception/ModelSteps';
import CreateorSearch from './Components/Reception/CreateorSearch';
import Dashboard from './Components/Reception/Dashboard';
import Layout from './Components/Reception/Layout';
import CreateDoctor from './Components/Reception/CreateDoctor';
import DoctorList from './Components/Reception/DoctorList';
import UpdateDoctor from './Components/UpdateDoctor';
import PatientList from './Components/Reception/PatientList';
import Createpatient from './Components/Reception/Createpatient';
import UpdatePatient from './Components/Reception/UpdatePatient';
import TestMasterForm from './Components/Reception/TestMasterForm';
import TestMasterList from './Components/Reception/TestMasterList';
import UpdateTest from './Components/Reception/UpdateTest';
import GroupTestCreation from './Components/Reception/GroupTestCreation';
import GroupTestList from './Components/Reception/GroupTestList';
import UpdateGroupTest from './Components/Reception/UpdateGroupTest';
import CreateProfile from './Components/Reception/CreateProfile';
import ProfileList from './Components/Reception/ProfileList';
import UpdateProfile from './Components/Reception/UpdateProfile';
import BillList from './Components/Reception/BillList';
import { AuthProvider } from './Components/Reception/AuthContext';
import BillDetail from './Components/Reception/BillDetail';
import LabResultEntry from './Components/Reception/LabResultEntry';
import CollectionNav from './Components/Reception/CollectionNav';
import DailyCollection from './Components/Reception/DailyCollection';
import MonthlyCollection from './Components/Reception/MonthlyCollection';
import DueReport from './Components/Reception/DueReport';
import ReportList from './Components/Reception/ReportList';
import UserCreate from './Components/Reception/UserCreate';
import UserUpdate from './Components/Reception/UserUpdate';
import UserDelete from './Components/Reception/UserDelete';
import UserManagement from './Components/Reception/UserManagment';
import UserAccess from './Components/Reception/UserAccess';
import LoginPage from './Components/LoginPage';
import RegistrationReport from './Components/Reception/RegistrationReport';
import DoctorWiseCollection from './Components/Reception/DoctorWiseCollection';
import DeptWiseCollection from './Components/Reception/DeptWiseCollection';
import FeesMaster from './Components/Reception/FeesMaster';
import PatientPrescription from './Components/Reception/PatientPrescription';
import OldPatientBilling from './Components/Reception/OldPatientBilling';
import BestPerformedTests from './Components/Reception/BestPerformedTests';
import PatientPerformance from './Components/Reception/PatientPerformance';
import MostVisitingPatients from './Components/Reception/MostVisitingPatients';
import MostConductedTests from './Components/Reception/MostConductedTests';
import PatientPromotion from './Components/Reception/PatientPromotion';
import PrescriptionList from './Components/Reception/PrescriptionList';
import { Navigate } from 'react-router-dom';
import { useAuth } from './Components/Reception/AuthContext';

import 'bootstrap/dist/css/bootstrap.min.css';
import 'react-datepicker/dist/react-datepicker.css'; 
import MedicineForm from './Components/Reception/MedicineForm';
import NewVisit from './Components/Reception/NewVisit';
import OutSource from './Components/Reception/OutSource';

const PrivateRoute = ({ element }) => {
  const { user } = useAuth(); 

  if (!user) {
    return <Navigate to="/" />;
  }

  return element;
};

const App = () => {
  return (
    <AuthProvider>
      <Router>
        <Layout>
          <Routes>
            <Route path="/" element={<LoginPage />} />
            <Route
            path="/dash"
            element={
              <PrivateRoute element={<Dashboard />} />
            }
          />
          <Route
            path="/doctorWise"
            element={
              <PrivateRoute element={<DoctorWiseCollection />} />
            }
          />
           <Route
            path="/deptWise"
            element={
              <PrivateRoute element={<DeptWiseCollection />} />
            }
          />
          <Route
            path="/userAccess"
            element={
              <PrivateRoute element={<UserAccess />} />
            }
          />
          <Route
            path="/feesMaster"
            element={
              <PrivateRoute element={<FeesMaster />} />
            }
          />
          <Route
            path="/userDelete"
            element={
              <PrivateRoute element={<UserDelete />} />
            }
          />
          <Route
            path="/updateUser"
            element={
              <PrivateRoute element={<UserUpdate />} />
            }
          />
          <Route
            path="/createUser"
            element={
              <PrivateRoute element={<UserCreate />} />
            }
          />
          <Route
            path="/report-nav"
            element={
              <PrivateRoute element={<CollectionNav />} />
            }
          />
          <Route
            path="/user-nav"
            element={
              <PrivateRoute element={<UserManagement />} />
            }
          />
          <Route
            path="/reportList"
            element={
              <PrivateRoute element={<ReportList />} />
            }
          />
          <Route
            path="/dailyCollection"
            element={
              <PrivateRoute element={<DailyCollection />} />
            }
          />
          <Route
            path="/monthlyCollection"
            element={
              <PrivateRoute element={<MonthlyCollection />} />
            }
          />
          <Route
            path="/dueReport"
            element={
              <PrivateRoute element={<DueReport />} />
            }
          />
          <Route
            path="/regReport"
            element={
              <PrivateRoute element={<RegistrationReport />} />
            }
          />
          <Route
            path="/bil-list"
            element={
              <PrivateRoute element={<BillList />} />
            }
          />
          <Route
            path="/prescription-list"
            element={
              <PrivateRoute element={<PrescriptionList />} />
            }
          />
           <Route
            path="/prescription-list/:patientId"
            element={
              <PrivateRoute element={<PrescriptionList />} />
            }
          />
          <Route
            path="/labResultentry/:objbillId"
            element={
              <PrivateRoute element={<LabResultEntry />} />
            }
          />
          <Route
            path="/billDetail/:objbillId"
            element={
              <PrivateRoute element={<BillDetail />} />
            }
          />
          <Route
            path="/profileList"
            element={
              <PrivateRoute element={<ProfileList />} />
            }
          />
          <Route
            path="/updateProfile/:profileId"
            element={
              <PrivateRoute element={<UpdateProfile />} />
            }
          />
          <Route
            path="/create-profile"
            element={
              <PrivateRoute element={<CreateProfile />} />
            }
          />
          <Route
            path="/create-or-search"
            element={
              <PrivateRoute element={<CreateorSearch />} />
            }
          />
          <Route
            path="/create-group-test"
            element={
              <PrivateRoute element={<GroupTestCreation />} />
            }
          />
          <Route
            path="/group-list"
            element={
              <PrivateRoute element={<GroupTestList />} />
            }
          />
          <Route
            path="/editGroupTest/:groupId"
            element={
              <PrivateRoute element={<UpdateGroupTest />} />
            }
          />
          <Route
            path="/test-master"
            element={
              <PrivateRoute element={<TestMasterForm />} />
            }
          />
          <Route
            path="/test-list"
            element={
              <PrivateRoute element={<TestMasterList />} />
            }
          />
          <Route
            path="/steps"
            element={
              <PrivateRoute element={<ModelSteps />} />
            }
          />
          <Route
            path="/create-patient"
            element={
              <PrivateRoute element={<Createpatient />} />
            }
          />
          <Route
            path="/edit/:pId"
            element={
              <PrivateRoute element={<UpdatePatient />} />
            }
          />
           <Route
            path="/steps/:patientId"
            element={
              <PrivateRoute element={<PatientPrescription />} />
            }
          />
           <Route
            path="/newPre/:ptid"
            element={
              <PrivateRoute element={<NewVisit />} />
            }
          />
           <Route
            path="/outSource/:patientId"
            element={
              <PrivateRoute element={<OutSource />} />
            }
          />
            <Route
            path="/oldBill/:patientId"
            element={
              <PrivateRoute element={<OldPatientBilling />} />
            }
          />
          <Route
            path="/editTest/:testId"
            element={
              <PrivateRoute element={<UpdateTest />} />
            }
          />
          <Route
            path="/patient-list"
            element={
              <PrivateRoute element={<PatientList />} />
            }
          />
          <Route
            path="/create-doctor"
            element={
              <PrivateRoute element={<CreateDoctor />} />
            }
          />
          <Route
            path="/doctor-list"
            element={
              <PrivateRoute element={<DoctorList />} />
            }
          />
          <Route
            path="/doctor/:doctorId"
            element={
              <PrivateRoute element={<UpdateDoctor />} />
            }
          />
           <Route
              path="/bestTests"
              element={
                <PrivateRoute element={<BestPerformedTests />} />
              }
            />
            <Route
              path="/patinetPerformance"
              element={
                <PrivateRoute element={<PatientPerformance />} />
              }
            />
            <Route
              path="/mostVisit"
              element={
                <PrivateRoute element={<MostVisitingPatients />} />
              }
            />
            <Route
              path="/medicine"
              element={
                <PrivateRoute element={<MedicineForm />} />
              }
            />
            <Route
              path="/mostTest"
              element={
                <PrivateRoute element={<MostConductedTests />} />
              }
            />
              <Route
              path="/patientPromotion"
              element={
                <PrivateRoute element={<PatientPromotion />} />
              }
            />
          </Routes>
        </Layout>
      </Router>
    </AuthProvider>
  );
};

const root = createRoot(document.getElementById('root'));
root.render(<App />);

export default App;
