import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  Table,
  TableContainer,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  TextField,
  Paper,
  IconButton,
  TablePagination,
  Grid,
} from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { Button } from 'react-bootstrap';
import SearchIcon from '@mui/icons-material/Search';
import { format } from 'date-fns';

const BillList = () => {
  const navigate = useNavigate();
  const [bills, setBills] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [loading, setLoading] = useState(true);

  const currentDate = new Date().toISOString().split('T')[0]; // Get current date in "yyyy-MM-dd" format
  const [selectedDate, setSelectedDate] = useState(currentDate);

  useEffect(() => {
    const fetchBills = async () => {
      try {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        const response = await axios.get(`${apiBaseUrl}/auth/bills`, {
          params: { date: selectedDate },
        });
        setBills(response.data.bills);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching bills:', error);
        setLoading(false);
      }
    };

    fetchBills();
  }, [selectedDate]);

  const searchTermLower = searchTerm.toLowerCase();

  const filteredBills = bills.filter((bill) => {
    const billIdString = bill.billId.toString();
    const pNumString = bill.pNum.toString();
    const pNameLower = bill.pName.toLowerCase();

    return (
      billIdString.includes(searchTerm) ||
      pNumString.includes(searchTerm) ||
      pNameLower.includes(searchTermLower)
    );
  });

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleSubmit = () => {
    navigate('/steps');
  };

  const handleRowClick = (objbillId) => {
    navigate(`/billDetail/${objbillId}`);
  };

  const handleGoToPrescription = (objbillId) => {
    navigate(`/steps/${objbillId}`);
  };

  return (
    <div className="container">
      <h5 style={{ textAlign: 'left'}}>Bills &rarr;</h5>
      <Grid container style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
        <Grid item>
          <Button
            onClick={handleSubmit}
            style={{
              backgroundColor: '#8F00FF',
              color: 'white',
              border: 'none',
              fontWeight: 'bold',
              boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
            }}
          >
            CREATE BILL
          </Button>
        </Grid>
        <Grid item style={{ marginLeft: '10px' }}>
          <TextField
            style={{ marginBottom: '15px' }}
            label="Select a Date"
            type="date"
            variant="outlined"
            fullWidth
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
          />
        </Grid>
      </Grid>

      <TextField
        label="Search by Bill ID, Name, Phone"
        variant="outlined"
        fullWidth
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        InputProps={{
          endAdornment: (
            <IconButton>
              <SearchIcon />
            </IconButton>
          ),
        }}
        style={{ marginBottom: 16 }}
      />

      {loading ? (
        <img
          src={require('../../assets/images/loading.gif')}
          alt="loading"
          style={{ width: '100px', height: '100px' }}
        />
      ) : (
        <>
          <TableContainer component={Paper}>
            <Table>
              <TableHead style={{backgroundColor:'#8F00FF'}}>
                <TableRow>
                  <TableCell style={{ color:'white'}}>
                    <strong>Bill Date</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Bill ID</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Patient Name</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Phone</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Doctor</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Bill Total</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Amount Paid</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Discount</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Due</strong>
                  </TableCell>
                  <TableCell style={{ color:'white'}}>
                    <strong>Actions</strong>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {filteredBills
                  .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                  .map((bill) => (
                    <TableRow
                      key={bill._id}
                      onClick={() => handleRowClick(bill.objbillId)}
                      style={{ cursor: 'pointer' }}
                    >
                      <TableCell>{bill.billDate}</TableCell>
                      <TableCell>{bill.billId}</TableCell>
                      <TableCell>{bill.pSal}. {bill.pName}</TableCell>
                      <TableCell>{bill.pNum}</TableCell>
                      <TableCell>{bill.drName}</TableCell>
                      <TableCell>{bill.billAmount}</TableCell>
                      <TableCell>{bill.amountPaid}</TableCell>
                      <TableCell>{bill.discountAmount}</TableCell>
                      <TableCell>{bill.amountDue}</TableCell>
                      <TableCell>
                        <Button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleGoToPrescription(bill.objbillId);
                          }}
                          style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none', marginRight: '8px' }}
                        >
                          Prescription
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
              </TableBody>
            </Table>
          </TableContainer>

          <TablePagination
            rowsPerPageOptions={[10, 25, 50]}
            component="div"
            count={filteredBills.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </>
      )}
    </div>
  );
};

export default BillList;
