import React, { useState, useEffect } from 'react';
import axios from 'axios';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import {
  Table,
  TableContainer,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  Paper,
  Grid,
  TablePagination,
  MenuItem,
  Select,
  Button,
} from '@mui/material';
import CollectionNav from './CollectionNav';

const DoctorWiseCollection = () => {
  const [doctors, setDoctors] = useState([]);
  const [selectedDoctor, setSelectedDoctor] = useState('');
  const [doctorWiseCollectionData, setDoctorWiseCollectionData] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState(new Date());

  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(8);

  useEffect(() => {
    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    // Fetch list of doctors
    axios
      .get(`${apiBaseUrl}/auth/get-doctors`)
      .then((response) => {
        setDoctors(response.data);
      })
      .catch((error) => {
        console.error('Error fetching doctors:', error);
      });
  }, []);

  useEffect(() => {
    const formattedDate = selectedDate.toISOString().split('T')[0];
    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    if (selectedDoctor) {
      // Adjust the API endpoint to get doctor-wise collection based on doctor ID
      axios
        .get(`${apiBaseUrl}/auth/doctorWiseCollection/${selectedDoctor}/${formattedDate}`)
        .then((response) => {
          setDoctorWiseCollectionData(response.data);
          setIsLoading(false);
        })
        .catch((error) => {
          console.error('Error fetching doctor-wise collection data:', error);
          setIsLoading(false);
        });
    }
  }, [selectedDoctor, selectedDate]);

  const downloadExcelFile = async () => {
    if (selectedDoctor) {
      const formattedDate = selectedDate.toISOString().split('T')[0];
      const apiBaseUrl = process.env.REACT_APP_API_KEY;

      try {
        const response = await axios.get(
          `${apiBaseUrl}/auth/downloadDoctorWiseCollection/${selectedDoctor}/${formattedDate}`,
          {
            responseType: 'blob',
          }
        );

        const blob = new Blob([response.data], {
          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'doctor-wise-collection.xlsx';
        a.click();

        window.URL.revokeObjectURL(url);
      } catch (error) {
        console.error('Error downloading Excel file:', error);
      }
    } else {
      console.error('Please select a doctor before downloading.');
    }
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <div className="container">
      <CollectionNav />
      <h5 style={{ textAlign: 'center' }}>Doctor-wise Collection Report</h5>
      <Select
        value={selectedDoctor}
        onChange={(event) => setSelectedDoctor(event.target.value)}
        displayEmpty
        style={{ marginBottom: '20px', marginRight: '10px', width: '200px' }}
      >
        <MenuItem value="" disabled>
          Select Doctor
        </MenuItem>
        {doctors.map((doctor) => (
          <MenuItem key={doctor._id} value={doctor._id}>
            {doctor.drName}
          </MenuItem>
        ))}
      </Select>
      <DatePicker
        selected={selectedDate}
        onChange={(date) => setSelectedDate(date)}
        dateFormat="yyyy-MM-dd"
        style={{ marginBottom: '20px', marginRight: '10px', width: '200px' }}
      />
      <Button
        style={{
          backgroundColor: '#8F00FF',
          color: 'white',
          border: 'none',
          marginLeft: '10px',
          marginBottom: '20px',
        }}
        variant="contained"
        color="primary"
        onClick={downloadExcelFile}
      >
        Download Excel
      </Button>

      <Grid container spacing={2} style={{ marginTop: '20px' }}>
        {/* Box 1: Number of Bills */}
        <Grid item xs={3}>
          <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
            <strong>Number of Bills</strong>
            <br />
            {doctorWiseCollectionData.length}
          </Paper>
        </Grid>

        {/* Box 2: Bill Total */}
        <Grid item xs={3}>
          <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white' }}>
            <strong>Bill Total</strong>
            <br />
            {/* Calculate the total bill amount */}
            {doctorWiseCollectionData.reduce((total, item) => total + item.billAmount, 0)}
          </Paper>
        </Grid>

        {/* Box 3: Discount */}
        <Grid item xs={3}>
          <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
            <strong>Discount</strong>
            <br />
            {/* Calculate the total discount */}
            {doctorWiseCollectionData.reduce((total, item) => total + item.discountAmount, 0)}
          </Paper>
        </Grid>

        {/* Box 4: Revenue */}
        <Grid item xs={3}>
          <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
            <strong>Revenue</strong>
            <br />
            {/* Calculate the total revenue */}
            {doctorWiseCollectionData.reduce((total, item) => total + item.amountPaid, 0)}
          </Paper>
        </Grid>
      </Grid>

      {isLoading ? (
        <img
          src={require('../../assets/images/loading.gif')}
          alt="bb"
          style={{ width: '100px', height: '100px' }}
        />
      ) : (
        <div>
          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>
                    <strong>Date</strong>
                  </TableCell>
                  <TableCell>
                    <strong>Doctor Name</strong>
                  </TableCell>
                  <TableCell>
                    <strong>Patient Name</strong>
                  </TableCell>
                  <TableCell>
                    <strong>Bill Amount</strong>
                  </TableCell>
                  <TableCell>
                    <strong>Discount</strong>
                  </TableCell>
                  <TableCell>
                    <strong>Revenue</strong>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {doctorWiseCollectionData
                  .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                  .map((doctorData) => (
                    <TableRow key={doctorData.doctorId}>
                      <TableCell>{doctorData.createdAt}</TableCell>
                      <TableCell>{doctorData.doctorName.drName}</TableCell>
                      <TableCell>
                        {doctorData.refId.pSalutation}. {doctorData.refId.pName}
                      </TableCell>
                      <TableCell>{doctorData.billAmount}</TableCell>
                      <TableCell>{doctorData.discountAmount}</TableCell>
                      <TableCell>{doctorData.amountPaid}</TableCell>
                    </TableRow>
                  ))}
              </TableBody>
            </Table>
          </TableContainer>
          <TablePagination
            rowsPerPageOptions={[8, 16, 24]}
            component="div"
            count={doctorWiseCollectionData.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </div>
      )}
    </div>
  );
};

export default DoctorWiseCollection;
