// export default UserManagement

import React from 'react';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Button from '@mui/material/Button';
import { NavLink, useLocation } from 'react-router-dom';

const UserManagement = () => {
  const location = useLocation();

  const isActive = (path) => {
    return location.pathname === path;
  };

  return (
    <div className='container'>
      <AppBar position="static" style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>
        <Toolbar>
          <Button color="inherit" component={NavLink} to="/createUser" activeClassName="isActive" style={{ textDecoration: isActive('/createUser') ? 'underline' : 'none', fontWeight: isActive('/createUser') ? 'bold' : 'normal' }}>
            Create User
          </Button>
          <Button color="inherit" component={NavLink} to="/updateUser" activeClassName="isActive" style={{ textDecoration: isActive('/updateUser') ? 'underline' : 'none', fontWeight: isActive('/updateUser') ? 'bold' : 'normal' }}>
            Update User
          </Button>
          <Button color="inherit" component={NavLink} to="/userDelete" activeClassName="isActive" style={{ textDecoration: isActive('/userDelete') ? 'underline' : 'none', fontWeight: isActive('/userDelete') ? 'bold' : 'normal' }}>
            Delete User
          </Button>
        </Toolbar>
      </AppBar>
    </div>
  );
}

export default UserManagement;
