import React, { useState, useEffect } from 'react';
import { TextField, Button, Grid } from '@mui/material';
import { toast } from 'react-toastify';
import axios from 'axios';

const TestMasterForm = () => {


    const [nextestId, setNexttestId] = useState(); // Start from 1

    const [formData, setFormData] = useState({
        id: '',
        name: '',
        category: '',
        method: '',
        sample: '',
        units: '',
        parameters: '',
        comments: '',
        reference_range: '',
        fees: '',
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData((prevData) => ({
            ...prevData,
            [name]: value, id: nextestId
        }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        axios.post(`${apiBaseUrl}/auth/create-test`, formData)
            .then((response) => {
                console.log('Test Master created:', response.data);
                toast.success('Test created successfully');
                // Clear form fields after successful submission
                setFormData({
                    id: '',
                    name: '',
                    category: '',
                    method: '',
                    sample: '',
                    units: '',
                    parameters: '',
                    comments: '',
                    reference_range: '',
                    fees: '',
                });
            })
            .catch((error) => {
                console.error('Error creating Test Master:', error);
            });
    };

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        axios.get(`${apiBaseUrl}/auth/next-test-id`)
            .then(response => {
                setNexttestId(response.data.nextTestId);
                // console.log(response.data.nextTestId);
            })
            .catch(error => {
                console.error('Error fetching next test ID:', error);
            });
    }, []);

    return (
        <>
            <div className='container'>
                <form onSubmit={handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Category"
                                variant="outlined"
                                name="category"
                                value={formData.category}
                                onChange={handleChange}
                                required
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Name"
                                variant="outlined"
                                name="name"
                                value={formData.name}
                                onChange={handleChange}
                                required
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Cost"
                                variant="outlined"
                                name="fees"
                                value={formData.fees}
                                onChange={handleChange}
                                required
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Method"
                                variant="outlined"
                                name="method"
                                value={formData.method
                                }
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Sample"
                                variant="outlined"
                                name="sample"
                                value={formData.sample}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Units"
                                variant="outlined"
                                name="units"
                                value={formData.units}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Parameters"
                                variant="outlined"
                                name="parameters"
                                value={formData.parameters}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Comments"
                                variant="outlined"
                                name="comments"
                                value={formData.comments}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Reference Range"
                                variant="outlined"
                                name="reference_range"
                                value={formData.reference_range}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={12} xs={12}>
                            <Button type="submit" variant="contained" color="primary" style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>
                                Create Test
                            </Button>
                        </Grid>
                    </Grid>
                </form>
            </div>
        </>
    );
};

export default TestMasterForm;
