import axios from 'axios';
import React, { useEffect, useState } from 'react'
import { Grid, TextField, Button } from '@mui/material';
import { FormControl, InputLabel, MenuItem, Select } from '@mui/material';
import { TextareaAutosize } from '@mui/base/TextareaAutosize';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

const UpdateDoctor = () => {

    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    const { doctorId } = useParams();

    const [doctor, setDoctor] = useState({
        drName: '',
        drGender: '',
        drEmail: '',
        drNum: '',
        drAddress: ''
    });

    useEffect(() => {
        axios.get(`${apiBaseUrl}/auth/findDoctorByid/${doctorId}`)
            .then(response => {
                setDoctor(response.data);
            })
            .catch(error => {
                console.error('Error fetching doctor details:', error);
            });
    }, [doctorId]);

    // const handleUpdate = () => {
    //     // Implement the update logic here
    //     console.log('Update doctor:', doctor);
    //   };

    const handleSubmit = (e) => {

        e.preventDefault(); // Prevent default form submission behavior


        // Here, you can collect all the data and submit it
        const updatedData = doctor;

        console.log('Submitted Data:', updatedData);

        // Assuming you have an API endpoint for submission
        axios.put(`${apiBaseUrl}/auth/update-doctor/${doctorId}`, updatedData)
            .then(response => {
                toast.success('Doctor information updated successfully'); // Display success message
                console.log('Submission successful:', response.data);
                // Clear the data after successful submission
                // setDoctor({
                //     docId: '',
                //     drName: '',
                //     drGender: '',
                //     drEmail: '',
                //     drNum: '',
                //     drAddress: ''
                // });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    }

    return (
        <>
            {/* <div>
      <h2>Edit Doctor</h2>
      <form>
        <label>Name:</label>
        <input type="text" value={doctor.drName} onChange={(e) => setDoctor({ ...doctor, drName: e.target.value })} />
        <button onClick={handleUpdate}>Update</button>
      </form>
    </div> */}
            <div className='container'>
                <form action="" onSubmit={handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={6} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Doctor Name" name="drName" id="drName" value={doctor.drName} onChange={(e) => setDoctor({ ...doctor, drName: e.target.value })} />
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Gender" name="drGender" id="drGender" value={doctor.drGender} onChange={(e) => setDoctor({ ...doctor, drGender: e.target.value })} />
                                </FormControl>
                            </div>
                        </Grid>
                    </Grid>

                    <Grid container spacing={2}>
                        <Grid item xs={6} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Email" name="drEmail" id="drEmail" value={doctor.drEmail} onChange={(e) => setDoctor({ ...doctor, drEmail: e.target.value })} />
                                </FormControl>
                            </div>
                        </Grid>

                        <Grid item xs={6}>
                            <div>
                                <FormControl fullWidth >
                                    <TextField variant="outlined" label="Number" name="drNum" id="drNum" value={doctor.drNum} onChange={(e) => setDoctor({ ...doctor, drNum: e.target.value })} />
                                </FormControl>
                            </div>
                        </Grid>
                    </Grid>

                    <Grid container spacing={2}>
                        <Grid item xs={12} style={{ marginBottom: '16px' }}>
                            <div>
                                <FormControl fullWidth >

                                    {/* <TextField variant="outlined" label="Email" name="drEmail" id="drEmail" value={doctorDetails.drEmail}  /> */}
                                    <TextareaAutosize variant="outlined" label="Address" name="drAddress" id="drAddress" minRows="10" value={doctor.drAddress} onChange={(e) => setDoctor({ ...doctor, drAddress: e.target.value })}> </TextareaAutosize>
                                </FormControl>

                            </div>
                        </Grid>
                    </Grid>

                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <div>
                                <Button type='submit' style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }} >UPDATE</Button>
                            </div>
                        </Grid>
                    </Grid>
                </form>
            </div>
        </>
    )
}

export default UpdateDoctor