// export default MonthlyCollection

import React, { useEffect, useState } from 'react';
import axios from 'axios';
import DatePicker from 'react-datepicker';
import {
    Table,
    TableContainer,
    TableHead,
    TableRow,
    TableCell,
    TableBody,
    TextField,
    Paper,
    Grid,
    Button,
    TablePagination,
} from '@mui/material';
import 'react-datepicker/dist/react-datepicker.css';
import CollectionNav from './CollectionNav';

const MonthlyCollection = () => {
    const [monthlyCollectionData, setMonthlyCollectionData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedMonth, setSelectedMonth] = useState(new Date());

    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(8);

    useEffect(() => {
        const formattedMonth = selectedMonth.toISOString().split('T')[0];
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        axios
            .get(`${apiBaseUrl}/auth/monthlyCollection/${formattedMonth}`)
            .then((response) => {
                setMonthlyCollectionData(response.data);
                setIsLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching monthly collection data:', error);
                setIsLoading(false);
            });
    }, [selectedMonth]);

    // Function to trigger the download of the Excel file
    const downloadExcelFile = async () => {
        const formattedDate = selectedMonth.toISOString().split('T')[0];
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        try {
            const response = await axios.get(
                `${apiBaseUrl}/auth/downloadMonthlyCollection/${formattedDate}`,
                {
                    responseType: 'blob', // Set the response type to blob
                }
            );

            // Create a blob URL and trigger the download
            const blob = new Blob([response.data], {
                type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'monthly-collection.xlsx';
            a.click();

            window.URL.revokeObjectURL(url); // Release the object URL
        } catch (error) {
            console.error('Error downloading Excel file:', error);
        }
    };

    // Function to handle page change
    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    // Function to handle rows per page change
    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    return (
        <div className="container">
            <CollectionNav />
            <h5 style={{ textAlign: 'center' }}>Monthly Collection Report</h5>
            <DatePicker
                selected={selectedMonth}
                onChange={(date) => setSelectedMonth(date)}
                dateFormat="yyyy-MM"
                showMonthYearPicker
            />
            <Button
                style={{
                    backgroundColor: '#8F00FF',
                    color: 'white',
                    border: 'none',
                }}
                variant="contained"
                color="primary"
                onClick={downloadExcelFile}
            >
                Download Excel
            </Button>
            <Grid container spacing={2} style={{ marginTop: '20px' }}>
                {/* Box 1: Number of Bills */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center',  backgroundColor: '#8F00FF', color: 'white', }}>
                        <strong>Number of Bills</strong>
                        <br />
                        {monthlyCollectionData.length}
                    </Paper>
                </Grid>

                {/* Box 2: Bill Total */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center',  backgroundColor: '#8F00FF', color: 'white', }}>
                        <strong>Bill Total</strong>
                        <br />
                        {/* Calculate the total bill amount */}
                        {monthlyCollectionData.reduce((total, item) => total + item.billAmount, 0)}
                    </Paper>
                </Grid>

                {/* Box 3: Discount */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
                        <strong>Discount</strong>
                        <br />
                        {/* Calculate the total discount */}
                        {monthlyCollectionData.reduce((total, item) => total + item.discountAmount, 0)}
                    </Paper>
                </Grid>

                {/* Box 4: Revenue */}
                <Grid item xs={3}>
                    <Paper elevation={3} style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white', }}>
                        <strong>Revenue</strong>
                        <br />
                        {/* Calculate the total revenue */}
                        {monthlyCollectionData.reduce((total, item) => total + item.amountPaid, 0)}
                    </Paper>
                </Grid>
            </Grid>

            
            {isLoading ? (
                // <p>Loading...</p>
                <img
                    src={require('../../assets/images/loading.gif')}
                    alt="bb"
                    style={{ width: '100px', height: '100px' }}
                />
            ) : (
                <div>
                    <TableContainer component={Paper}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell>
                                        <strong>Date</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Bill ID</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Patient Name</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Doctor</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Bill Total</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Discount</strong>
                                    </TableCell>
                                    <TableCell>
                                        <strong>Revenue</strong>
                                    </TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {monthlyCollectionData
                                    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                                    .map((item) => (
                                        <TableRow key={item._id}>
                                            <TableCell>{item.createdAt}</TableCell>
                                            <TableCell>{item.billId}</TableCell>
                                            <TableCell>
                                                {item.refId.pSalutation}. {item.refId.pName}
                                            </TableCell>
                                            <TableCell>{item.doctorName.drName}</TableCell>
                                            <TableCell>{item.billAmount}</TableCell>
                                            <TableCell>{item.discountAmount}</TableCell>
                                            <TableCell>{item.amountPaid}</TableCell>
                                        </TableRow>
                                    ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                    <TablePagination
                        rowsPerPageOptions={[8, 16, 24]}
                        component="div"
                        count={monthlyCollectionData.length}
                        rowsPerPage={rowsPerPage}
                        page={page}
                        onPageChange={handleChangePage}
                        onRowsPerPageChange={handleChangeRowsPerPage}
                    />
                </div>
            )}
        </div>
    );
};

export default MonthlyCollection;
