import React, { useState, useEffect } from 'react';
import { Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, TextField, Button, Container } from '@mui/material';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import * as XLSX from 'xlsx';

const PatientPerformance = () => {
  // Helper function to get the current date in YYYY-MM-DD format
  const getCurrentDate = () => {
    const today = new Date();
    const year = today.getFullYear();
    const month = String(today.getMonth() + 1).padStart(2, '0');
    const day = String(today.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Initialize state with the current date
  const [fromDate, setFromDate] = useState(getCurrentDate());
  const [toDate, setToDate] = useState(getCurrentDate());
  const [performanceData, setPerformanceData] = useState([]);
  const [loading, setLoading] = useState(false);

  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  const fetchPerformanceData = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${apiBaseUrl}/auth/patient-performance`, {
        params: { fromDate, toDate }
      });
      setPerformanceData(response.data);
    } catch (error) {
      console.error('Error fetching performance data:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (fromDate && toDate) {
      fetchPerformanceData();
    }
  }, [fromDate, toDate]);

  const handleDateChange = (setter) => (event) => {
    setter(event.target.value);
  };

  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const downloadPDF = () => {
    const doc = new jsPDF();
  
    // Add Report Title
    doc.setFontSize(18);
    doc.text('Patient Performance Summary Report', 14, 20);
  
    // Add Date Range
    doc.setFontSize(12);
    doc.text(`From: ${fromDate}`, 14, 30);
    doc.text(`To: ${toDate}`, 14, 40);
  
    // Add Table Header
    doc.autoTable({
      head: [['Bill Date', 'Bill ID', 'Patient Name', 'Doctor Name', 'Number of Tests', 'Tests', 'Bill Amount', 'Paid Amount', 'Due Amount']],
      body: performanceData.map(item => [
        formatDate(item.billDetail.createdAt),
        item.billDetail.billId,
        item.patientName,
        item.doctorName,
        item.numberOfTests,
        item.tests.map(test => test.testName).join(', '),
        item.billDetail.billAmount,
        item.billDetail.amountPaid,
        item.billDetail.amountDue,
      ]),
      startY: 50, // Starting Y position for the table
    });
  
    // Calculate Total Amounts
    const totalPaidAmount = performanceData.reduce((sum, item) => sum + item.billDetail.amountPaid, 0);
    const totalDueAmount = performanceData.reduce((sum, item) => sum + item.billDetail.amountDue, 0);
  
    // Add Table Footer
    doc.autoTable({
      startY: doc.lastAutoTable.finalY + 10,
      body: [
        ['', '', '', '', '', '', `Total Paid: ${totalPaidAmount}`, `Total Due: ${totalDueAmount}`]
      ],
      styles: { fontSize: 12, fontStyle: 'bold' },
      theme: 'striped'
    });
  
    // Save the PDF
    doc.save('PatientPerformance.pdf');
  };

  const downloadExcel = () => {
    const totalPaidAmount = performanceData.reduce((sum, item) => sum + item.billDetail.amountPaid, 0);
    const totalDueAmount = performanceData.reduce((sum, item) => sum + item.billDetail.amountDue, 0);
  
    const ws = XLSX.utils.json_to_sheet(
      performanceData.map(item => ({
        'Bill Date': formatDate(item.billDetail.createdAt),
        'Bill ID': item.billDetail.billId,
        'Patient Name': item.patientName,
        'Doctor Name': item.doctorName,
        'Number of Tests': item.numberOfTests,
        'Tests': item.tests.map(test => test.testName).join(', '),
        'Bill Amount': item.billDetail.billAmount,
        'Paid Amount': item.billDetail.amountPaid,
        'Due Amount': item.billDetail.amountDue,
      }))
    );
  
    // Add title and date range
    const title = [['Patient Performance Summary Report']];
    const dateRange = [
      [`From Date: ${fromDate}`],
      [`To Date: ${toDate}`]
    ];

    XLSX.utils.sheet_add_aoa(ws, title, { origin: 'A1' });
    XLSX.utils.sheet_add_aoa(ws, dateRange, { origin: 'A3' });

    // Add a blank row before adding data
    XLSX.utils.sheet_add_aoa(ws, [[]], { origin: 'A5' });

    // Add totals to the sheet
    const totals = [
      [],
      [],
      [],
      [],
      [],
      [],
      ['Total Paid', totalPaidAmount],
      ['Total Due', totalDueAmount]
    ];

    XLSX.utils.sheet_add_aoa(ws, totals, { origin: -1 });

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Performance Data');
    XLSX.writeFile(wb, 'PatientPerformance.xlsx');
  };

  return (
    <Container>
        <h5 style={{ textAlign: 'left'}}>Test Summary Report  &rarr;</h5>

      <TextField
        type="date"
        label="From Date"
        value={fromDate}
        onChange={handleDateChange(setFromDate)}
        fullWidth
        InputLabelProps={{ shrink: true }}
        margin="normal"
      />
      <TextField
        type="date"
        label="To Date"
        value={toDate}
        onChange={handleDateChange(setToDate)}
        fullWidth
        InputLabelProps={{ shrink: true }}
        margin="normal"
      />
      <Button
        variant="contained"
        color="primary"
        onClick={fetchPerformanceData}
        disabled={!fromDate || !toDate || loading}
        style={{ marginTop: 16 }}
      >
        Fetch Data
      </Button>
      <Button
        variant="contained"
        color="secondary"
        onClick={downloadPDF}
        disabled={loading || performanceData.length === 0}
        style={{ marginTop: 16, marginLeft: 8 }}
      >
        Download PDF
      </Button>
      <Button
        variant="contained"
        color="secondary"
        onClick={downloadExcel}
        disabled={loading || performanceData.length === 0}
        style={{ marginTop: 16, marginLeft: 8 }}
      >
        Download Excel
      </Button>
      {loading ? (
        <p>Loading...</p>
      ) : (
        <TableContainer component={Paper} style={{ marginTop: 20 }}>
          <Table>
            <TableHead style={{backgroundColor:'#8F00FF'}}>
              <TableRow>
                <TableCell style={{ color:'white'}}><strong>Bill Date</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Bill ID</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Patient Name</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Doctor Name</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Number of Tests</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Tests</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Bill Amount</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Paid Amount</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Due Amount</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {performanceData.map((item, index) => (
                <TableRow key={index}>
                  <TableCell>{formatDate(item.billDetail.createdAt)}</TableCell>
                  <TableCell>{item.billDetail.billId}</TableCell>
                  <TableCell>{item.patientName}</TableCell>
                  <TableCell>{item.doctorName}</TableCell>
                  <TableCell>{item.numberOfTests}</TableCell>
                  <TableCell>
                    {item.tests.map((test, testIndex) => (
                      <div key={testIndex}>{test.testName}</div>
                    ))}
                  </TableCell>
                  <TableCell>{item.billDetail.billAmount}</TableCell>
                  <TableCell>{item.billDetail.amountPaid}</TableCell>
                  <TableCell>{item.billDetail.amountDue}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Container>
  );
};

export default PatientPerformance;
