import React, { useEffect, useState, useRef } from 'react';
import axios from 'axios';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TextField,
  Typography,
  Alert,
} from '@mui/material';
import { Link } from 'react-router-dom';
import { Button, Modal } from 'react-bootstrap'; // Import the Modal component
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import { TablePagination } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import {
  Receipt as ReceiptIcon,
  Description as DescriptionIcon,
  CloudUpload as CloudUploadIcon,
  Visibility as VisibilityIcon
} from '@mui/icons-material';
import { Tooltip } from '@mui/material';

const PatientList = () => {
  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  const [patientList, setPatientList] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [isLoading, setIsLoading] = useState(true); // Added loading state
  const navigate = useNavigate();

  // Pagination state variables
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  // Confirmation dialog state
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [patientToDelete, setPatientToDelete] = useState(null);

  // Lab Report Upload Modal state
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [selectedPatientId, setSelectedPatientId] = useState(null);
  const [files, setFiles] = useState([]);
  const [uploadLoading, setUploadLoading] = useState(false);
  const [uploadError, setUploadError] = useState('');
  const [uploadSuccess, setUploadSuccess] = useState('');

  // Ref for file input
  const fileInputRef = useRef(null);

  useEffect(() => {
    axios
      .get(`${apiBaseUrl}/auth/get-patients`)
      .then((response) => {
        setPatientList(response.data);
        setIsLoading(false); // Set loading to false when data is fetched
      })
      .catch((error) => {
        console.error('Error fetching available patients:', error);
        setIsLoading(false); // Set loading to false on error
      });
  }, []);

  const handleDelete = (patientId) => {
    // Set the patient to be deleted
    setPatientToDelete(patientId);
    // Show the confirmation dialog
    setShowConfirmation(true);
  };

  const handleConfirmDelete = () => {
    // Close the confirmation dialog
    setShowConfirmation(false);

    // Perform the delete operation
    axios
      .delete(`${apiBaseUrl}/auth/delete-patient/${patientToDelete}`)
      .then((response) => {
        toast.success('Patient deleted successfully');
        // Update the patient list after deletion
        setPatientList(patientList.filter((patients) => patients._id !== patientToDelete));
      })
      .catch((error) => {
        console.error('Error deleting patient:', error);
      });
  };

  const handleGoToPrescription = (patientId) => {
    navigate(`/steps/${patientId}`);
  };

  const handleGoToBilling = (patientId) => {
    navigate(`/oldBill/${patientId}`);
  };

  const handleOpenReports = (patientId) => {
    navigate(`/outSource/${patientId}`);
  };

  const handleGoToPrescriptioList = (patientId) => {
    navigate(`/prescription-list/${patientId}`);
  };

  const handleCancelDelete = () => {
    // Close the confirmation dialog and clear the patient to delete
    setShowConfirmation(false);
    setPatientToDelete(null);
  };

  const handleSubmit = () => {
    navigate('/create-patient');
  };

  // Lab Report Upload Functions
  const handleOpenUploadModal = (patientId) => {
    setSelectedPatientId(patientId);
    setShowUploadModal(true);
  };

  const handleCloseUploadModal = () => {
    setShowUploadModal(false);
    setFiles([]);
    setUploadError('');
    setUploadSuccess('');
  };

  const handleFileChange = (e) => {
    const selectedFiles = Array.from(e.target.files);
    setFiles(selectedFiles);
  };

  const handleFileButtonClick = () => {
    fileInputRef.current.click(); // Programmatically trigger the file input
  };

  // const handleUpload = async () => {
  //   if (files.length === 0) {
  //     setUploadError('Please select at least one file to upload.');
  //     return;
  //   }

  //   setUploadLoading(true);
  //   setUploadError('');
  //   setUploadSuccess('');

  //   const formData = new FormData();
  //   files.forEach((file) => {
  //     formData.append('labReports', file); // Append each file to the form data
  //   });
  //   formData.append('patientId', selectedPatientId); // Append patient ID

  //   try {
  //     const response = await axios.post(`${apiBaseUrl}/auth/upload-lab-reports`, formData, {
  //       headers: {
  //         'Content-Type': 'multipart/form-data', // Required for file uploads
  //       },
  //     });

  //     setUploadSuccess('Lab reports uploaded successfully!');
  //     setFiles([]); // Clear selected files
  //     console.log('Upload response:', response.data);
  //   } catch (error) {
  //     console.error('Error uploading lab reports:', error);
  //     setUploadError('Failed to upload lab reports. Please try again.');
  //   } finally {
  //     setUploadLoading(false);
  //   }
  // };

  //   const handleUpload = async () => {
  //     if (files.length === 0) {
  //         setUploadError('Please select at least one file to upload.');
  //         return;
  //     }

  //     setUploadLoading(true);
  //     setUploadError('');
  //     setUploadSuccess('');

  //     const formData = new FormData();
  //     files.forEach((file) => {
  //         formData.append('labReports', file);
  //     });
  //     formData.append('patientId', selectedPatientId);

  //     // Log formData values
  //     for (let [key, value] of formData.entries()) {
  //         console.log(`${key}:`, value);
  //     }

  //     try {
  //         const response = await axios.post(`${apiBaseUrl}/auth/upload-lab-reports`, formData, {
  //             headers: {
  //                 'Content-Type': 'multipart/form-data',
  //             },
  //         });

  //         setUploadSuccess('Lab reports uploaded successfully!');
  //         setFiles([]); // Clear selected files
  //         console.log('Upload response:', response.data);
  //     } catch (error) {
  //         console.error('Error uploading lab reports:', error);
  //         setUploadError(error.response?.data?.error || 'Failed to upload lab reports. Please try again.');
  //     } finally {
  //         setUploadLoading(false);
  //     }
  // };

  const handleUpload = async () => {
    if (files.length === 0) {
      setUploadError('Please select at least one file to upload.');
      return;
    }

    setUploadLoading(true);
    setUploadError('');
    setUploadSuccess('');

    const formData = new FormData();

    // Append patientId FIRST
    formData.append('patientId', selectedPatientId);  

    // Append files AFTER
    files.forEach((file) => {
      formData.append('labReports', file);
    });

    // Log formData values (for debugging)
    for (let [key, value] of formData.entries()) {
      console.log(`${key}:`, value);
    }

    try {
      const response = await axios.post(
        `${apiBaseUrl}/auth/upload-lab-reports`,
        formData,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );

      setUploadSuccess('Lab reports uploaded successfully!');
      setFiles([]);
      console.log('Upload response:', response.data);
    } catch (error) {
      console.error('Error uploading lab reports:', error);
      setUploadError(error.response?.data?.error || 'Failed to upload lab reports. Please try again.');
    } finally {
      setUploadLoading(false);
    }
  };

  // Filter the patient list based on the search query
  const filteredPatients = patientList.filter((patient) => {
    const searchTerms = searchQuery.toLowerCase().split(' ');
    return searchTerms.every(
      (term) =>
        patient.pName.toLowerCase().includes(term) ||
        patient.pGender.toLowerCase().includes(term) ||
        patient.pNum.toString().includes(term) || // Convert pNum to string for comparison
        patient.pEmail.toLowerCase().includes(term)
    );
  });

  // Pagination calculations
  const startIndex = page * rowsPerPage;
  const endIndex = startIndex + rowsPerPage;

  const paginatedPatients = filteredPatients.slice(startIndex, endIndex);

  // Handle page change
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  // Handle rows per page change
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  if (isLoading) {
    return (
      <img
        src={require('../../assets/images/loading.gif')}
        alt="loading"
        style={{ width: '100px', height: '100px' }}
      />
    ); // Render loading indicator
  }

  return (
    <>
      <div className="container">
        <h5 style={{ textAlign: 'left' }}>Patients &rarr;</h5>
        <TextField
          label="Search Patients"
          variant="outlined"
          fullWidth
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ marginBottom: '20px' }}
        />
        <TableContainer component={Paper}>
          <Table>
            <TableHead style={{ backgroundColor: '#8F00FF' }}>
              <TableRow>
                <TableCell style={{ color: 'white' }}>
                  <strong>Patient ID</strong>
                </TableCell>
                <TableCell style={{ color: 'white' }}>
                  <strong>Name</strong>
                </TableCell>
                {/* <TableCell style={{ color: 'white' }}>
                  <strong>Gender</strong>
                </TableCell> */}
                <TableCell style={{ color: 'white' }}>
                  <strong>Phone</strong>
                </TableCell>
                {/* <TableCell style={{ color: 'white' }}>
                  <strong>Email</strong>
                </TableCell> */}
                <TableCell style={{ color: 'white' }}>
                  <strong>Edit/Delete</strong>
                </TableCell>
                <TableCell style={{ color: 'white' }}>
                  <strong>Billing</strong>
                </TableCell>
                <TableCell style={{ color: 'white' }}>
                  <strong>Prescription</strong>
                </TableCell>
                <TableCell style={{ color: 'white' }}>
                  <strong>Upload</strong>
                </TableCell>
                <TableCell style={{ color: 'white' }}>
                  <strong>View Reports</strong>
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedPatients.map((patient) => (
                <TableRow key={patient._id}>
                  <TableCell>{patient.pId}</TableCell>
                  <TableCell>{patient.pSalutation}. {patient.pName}</TableCell>
                  {/* <TableCell>{patient.pGender}</TableCell> */}
                  <TableCell>{patient.pNum}</TableCell>
                  {/* <TableCell>{patient.pEmail}</TableCell> */}
                  <TableCell>
                    <Link to={`/edit/${patient._id}`}>
                      <Tooltip title="Edit" arrow>
                        <Link to={`/edit/${patient._id}`}>
                          <Button
                            style={{
                              backgroundColor: '#8F00FF',
                              color: 'white',
                              minWidth: '32px',
                              padding: '15px'
                            }}
                          >
                            <EditIcon fontSize="small" />
                          </Button>
                        </Link>
                      </Tooltip>
                    </Link>
                    <Tooltip title="Delete" arrow>
                      <Button
                        onClick={() => handleDelete(patient._id)}
                        style={{
                          backgroundColor: 'red',
                          color: 'white',
                          minWidth: '32px',
                          padding: '15px'
                        }}
                      >
                        <DeleteIcon fontSize="small" />
                      </Button>
                    </Tooltip>
                  </TableCell>
                  <TableCell>
                    <Tooltip title="Billing" arrow>
                      <Button
                        onClick={() => handleGoToBilling(patient._id)}
                        style={{ backgroundColor: '#8F00FF', color: 'white', padding: '15px', fontFamily: 'Arial' }}
                      >
                        ₹  {/* Rupee symbol */}
                      </Button>
                    </Tooltip>
                  </TableCell>
                  <TableCell>
                    <Tooltip title="Prescription" arrow>
                      <Button
                        onClick={() => handleGoToPrescriptioList(patient._id)}
                        style={{
                          backgroundColor: '#8F00FF',
                          color: 'white',
                          padding: '15px',
                          fontFamily: 'Times New Roman',
                          fontWeight: 'bold',
                          fontStyle: 'italic'
                        }}
                      >
                        ℞  {/* Rx symbol */}
                      </Button>
                    </Tooltip>
                  </TableCell>
                  <TableCell>
                    <Tooltip title="Upload Reports" arrow>
                      <Button
                        onClick={() => handleOpenUploadModal(patient._id)}
                        style={{ backgroundColor: '#8F00FF', color: 'white', padding: '15px', fontFamily: 'Arial' }}

                      >
                        <CloudUploadIcon fontSize="small" />
                      </Button>
                    </Tooltip>
                  </TableCell>
                  <TableCell>
                    <Tooltip title="View Reports" arrow>
                      <Button
                        onClick={() => handleOpenReports(patient._id)}
                        style={{ backgroundColor: '#8F00FF', color: 'white', padding: '15px', fontFamily: 'Arial' }}

                      >
                        <VisibilityIcon fontSize="small" />
                      </Button>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Table pagination */}
        <TablePagination
          rowsPerPageOptions={[10, 25, 50]}
          component="div"
          count={filteredPatients.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />
      </div>

      {/* Confirmation dialog for deleting patients */}
      <Modal show={showConfirmation} onHide={handleCancelDelete}>
        <Modal.Header closeButton>
          <Modal.Title>Confirm Deletion</Modal.Title>
        </Modal.Header>
        <Modal.Body>Are you sure you want to delete this patient?</Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCancelDelete}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleConfirmDelete}>
            Delete
          </Button>
        </Modal.Footer>
      </Modal>

      {/* Lab Report Upload Modal */}
      <Modal show={showUploadModal} onHide={handleCloseUploadModal}>
        <Modal.Header closeButton>
          <Modal.Title>Upload Lab Reports</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {/* File Input */}
          <input
            type="file"
            id="labReports"
            name="labReports"
            multiple
            onChange={handleFileChange}
            style={{ display: 'none' }}
            ref={fileInputRef}
          />
          {/* Button to Trigger File Input */}
          <Button
            variant="contained"
            onClick={handleFileButtonClick}
            style={{ backgroundColor: '#8F00FF', color: 'white', marginRight: '8px' }}
          >
            Choose Files
          </Button>
          {/* Display Selected Files */}
          <Typography variant="body2">
            {files.length > 0 ? `${files.length} file(s) selected` : 'No files selected'}
          </Typography>
          {/* Error and Success Messages */}
          {uploadError && (
            <Alert severity="error" style={{ marginTop: '16px' }}>
              {uploadError}
            </Alert>
          )}
          {uploadSuccess && (
            <Alert severity="success" style={{ marginTop: '16px' }}>
              {uploadSuccess}
            </Alert>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseUploadModal}>
            Close
          </Button>
          <Button
            variant="primary"
            onClick={handleUpload}
            disabled={uploadLoading || files.length === 0}
          >
            {uploadLoading ? 'Uploading...' : 'Upload'}
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default PatientList;