import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Grid, TextField, Button, Autocomplete, Paper, Typography, IconButton } from '@mui/material';
import InputLabel from '@mui/material/InputLabel';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import { CKEditor } from '@ckeditor/ckeditor5-react';
import ClassicEditor from 'ckeditor5-custom-build/build/ckeditor';
import DeleteIcon from '@mui/icons-material/Delete';
import { toast } from 'react-toastify';
import { useParams } from 'react-router-dom';
// import './ModelSteps.css';
import './Prescription.css'

const NewVisit = () => {
    const { ptid } = useParams();
    const [userRegistration, setUserRegistration] = useState({
        pId: '',
        billId: '',
        pSalutation: '',
        pName: '',
        pAge: '',
        pGender: '',
        pNum: '',
        pEmail: '',
        doctorName: '',
    });

    const [vitals, setVitals] = useState({
        bloodPressure: '',
        heartRate: '',
        temperature: '',
        respiratoryRate: '',
        height: '',
        weight: '',
    });

    const [availableDoctors, setAvailableDoctors] = useState([]);
    const [prescriptionContent, setPrescriptionContent] = useState('');
    const [isSavePrescription, setIsSavePrescription] = useState(false);
    const [isPrescription, setIsPrescription] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [isListening, setIsListening] = useState(false);

    const [complaintsContent, setComplaintsContent] = useState('');
    const [clinicalFindingsContent, setClinicalFindingsContent] = useState('');
    const [diagnosisContent, setDiagnosisContent] = useState('');
    const [knownDiagnosisContent, setKnownDiagnosisContent] = useState('');

    const [filteredTests, setFilteredTests] = useState([]);
    const [selectedTests, setSelectedTests] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');

    const [activeEditor, setActiveEditor] = useState('prescription');
    const recognitionRef = useRef(null);

    const [medicines, setMedicines] = useState([]);
    const [newMedicine, setNewMedicine] = useState({
        medicineName: '',
        composition: '',
        foodType: '',
        duration: '',
        frequency: '',
        tablets: ''
    });
    const [medicineSuggestions, setMedicineSuggestions] = useState([]);
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [allMedicines, setAllMedicines] = useState([]);



    // Medicine Autocomplete handlers
    const handleMedicineSelect = (event, value) => {
        if (value) {
            setNewMedicine(prev => ({
                ...prev,
                medicineName: value.medicine,
                composition: value.composition
            }));
        }
    };


    // const selectMedicine = (medicine) => {
    //     handleMedicineChange("medicineName", medicine.name);
    //     handleMedicineChange("composition", medicine.composition);
    //     setShowSuggestions(false);
    // };

    // Add medicine to prescription
    const addMedicine = () => {
        if (!newMedicine.medicineName || !newMedicine.composition) {
            toast.error("Please select a valid medicine.");
            return;
        }
        setMedicines([...medicines, newMedicine]);
        // Reset form
        setNewMedicine({
            medicineName: "",
            composition: "",
            foodType: "",
            duration: "",
            frequency: "",
            tablets: "",
        });
    };

    // Remove medicine
    const removeMedicine = (index) => {
        setMedicines(medicines.filter((_, i) => i !== index));
    };

    const handleComplaintsChange = (event, editor) => {
        setComplaintsContent(editor.getData());
    };

    const handleClinicalFindingsChange = (event, editor) => {
        setClinicalFindingsContent(editor.getData());
    };

    const handleDiagnosisChange = (event, editor) => {
        setDiagnosisContent(editor.getData());
    };

    const handleKnownDiagnosisChange = (event, editor) => {
        setKnownDiagnosisContent(editor.getData());
    };

    const apiBaseUrl = process.env.REACT_APP_API_KEY;


    useEffect(() => {
        if (ptid) {
            setIsLoading(true);
            fetchAdditionalPatientDetails(ptid);
            // fetchPrescriptions(ptid);
        }
    }, [ptid]);

    useEffect(() => {
        setIsLoading(true);
        axios.get(`${apiBaseUrl}/auth/get-doctors`)
            .then(response => {
                setAvailableDoctors(response.data);
            })
            .catch(error => {
                console.error('Error fetching available doctors:', error);
            }).finally(() => {
                setIsLoading(false);
            });
    }, []);

    // Fetch all medicines on component mount
    useEffect(() => {
        const fetchAllMedicines = async () => {
            try {
                const response = await axios.get(`${apiBaseUrl}/auth/medicines`);
                setAllMedicines(response.data);
            } catch (error) {
                console.error("Error fetching medicines:", error);
            }
        };
        fetchAllMedicines();
    }, []);

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        const fetchAllTests = async () => {
            try {
                const [testsResponse, groupTestsResponse, profileTestsResponse, feesResponse] = await Promise.all([
                    axios.get(`${apiBaseUrl}/auth/tests`),
                    axios.get(`${apiBaseUrl}/auth/getGroupTestList`),
                    axios.get(`${apiBaseUrl}/auth/getProfileList`),
                    axios.get(`${apiBaseUrl}/auth/getfeesList`),
                ]);

                const testsWithTypes = [
                    ...testsResponse.data.map((test) => ({ ...test, type: 'Test', department: 'Lab' })),
                    ...groupTestsResponse.data.map((test) => ({ ...test, type: 'Group', department: 'Lab' })),
                    ...profileTestsResponse.data.map((test) => ({ ...test, type: 'Profile', department: 'Lab' })),
                    ...feesResponse.data.map((test) => ({ ...test, type: 'OtherFees' })),
                ];

                setFilteredTests(testsWithTypes);
            } catch (error) {
                console.error('Error fetching available tests:', error);
            }
        };

        fetchAllTests();
    }, []);

    const handleTestSelection = (newValue) => {
        setSelectedTests(newValue);
    };

    const handleRemoveTest = (test) => {
        setSelectedTests((prevSelectedTests) =>
            prevSelectedTests.filter((selectedTest) => selectedTest._id !== test._id)
        );
    };

    const renderSelectedTests = () => {
        if (selectedTests.length > 0) {
            return (
                <div className="selected-tests">
                    <h4>Selected Tests:</h4>
                    <ul>
                        {selectedTests.map((test) => {
                            const testName =
                                test.type === 'Profile'
                                    ? test.profileName
                                    : test.type === 'Group'
                                        ? test.groupName
                                        : test.type === 'OtherFees'
                                            ? test.feesName
                                            : test.name;

                            const testPrice =
                                test.type === 'Profile'
                                    ? test.profilePrice
                                    : test.type === 'Group'
                                        ? test.groupPrice
                                        : test.type === 'OtherFees'
                                            ? test.opFees
                                            : test.fees;

                            return (
                                <li key={`${test.type}-${test._id}`}>
                                    {`${test.type} Name: ${testName} - Price: ₹${testPrice}  ${test.units || ''}`}
                                    <Button
                                        variant="contained"
                                        color="secondary"
                                        style={{
                                            backgroundColor: '#8F00FF',
                                            color: 'white',
                                            border: 'none',
                                            fontWeight: 'bold',
                                            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
                                        }}
                                        onClick={() => handleRemoveTest(test)}
                                    >
                                        Remove
                                    </Button>
                                </li>
                            );
                        })}
                    </ul>
                </div>
            );
        }
        return null;
    };

    const handleVitalsChange = (e) => {
        const name = e.target.name;
        const value = e.target.value;
        setVitals({ ...vitals, [name]: value });
    };

    const fetchAdditionalPatientDetails = (ptid) => {
        axios.get(`${apiBaseUrl}/auth/findPatientByidnewVisit/${ptid}`)
            .then(response => {
                const patientDetails = response.data;
                setUserRegistration({
                    ...userRegistration,
                    pId: patientDetails.pId,
                    pSalutation: patientDetails.pSal,
                    pName: patientDetails.pName,
                    pAge: patientDetails.pAge,
                    pGender: patientDetails.pGender,
                    pNum: patientDetails.pNum,
                    pEmail: patientDetails.pEmail,
                    billId: patientDetails.billId,
                    doctorName: patientDetails.drName,
                });
            })
            .catch(error => {
                console.error('Error fetching additional patient details:', error);
            }).finally(() => {
                setIsLoading(false);
            });
    };






    const handleInput = (e) => {
        const name = e.target.name;
        const value = e.target.value;
        setUserRegistration({ ...userRegistration, [name]: value });
    };

    const handleDoctorSelection = (e) => {
        const selectedDoctor = e.target.value;
        setUserRegistration({ ...userRegistration, [e.target.name]: selectedDoctor });
    };

    const handlePrescriptionChange = (event, editor) => {
        const data = editor.getData();
        setPrescriptionContent(data);
    };


    const savePrescription = async () => {
        setIsSavePrescription(true);
        const prescriptionData = {
            patientId: ptid,
            billId: userRegistration.pId,
            billNO: userRegistration.billId,
            doctorName: userRegistration.doctorName,
            content: prescriptionContent,
            complaints: complaintsContent,
            clinicalFindings: clinicalFindingsContent,
            diagnosis: diagnosisContent,
            knownDiagnosis: knownDiagnosisContent,
            medicines: medicines,
            vitals: vitals,
            selectedTests: selectedTests,
        };

        try {
            // Save the prescription and get the response
            const response = await axios.post(`${apiBaseUrl}/auth/save-prescription`, prescriptionData);
            const savedPrescriptionId = response.data._id; // Assuming the server returns the saved prescription with _id

            toast.success('Prescription saved successfully!');

            // Pass the saved prescription _id to the print function
            await printPrescription(savedPrescriptionId);
        } catch (error) {
            console.error('Error saving prescription:', error);
            toast.error('Error saving prescription. Please try again.');
        } finally {
            setIsSavePrescription(false);
        }
    };

    const printPrescription = async (prescriptionId) => {
        setIsPrescription(true);
        try {
            const response = await axios.post(
                `${apiBaseUrl}/auth/print-prescriptions/${prescriptionId}`, // Use the prescriptionId here
                {},
                {
                    responseType: 'blob',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                }
            );

            const blob = new Blob([response.data], { type: 'application/pdf' });
            const pdfUrl = URL.createObjectURL(blob);
            window.open(pdfUrl, '_blank');
        } catch (error) {
            console.error('Error printing prescription:', error);
        } finally {
            setIsPrescription(false);
        }
    };

    // const handleSpeechRecognition = () => {
    //     const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    //     const recognition = new SpeechRecognition();
    //     recognition.continuous = true;
    //     recognition.interimResults = true;

    //     recognition.onstart = () => {
    //         setIsListening(true);
    //     };

    //     recognition.onresult = (event) => {
    //         const transcript = Array.from(event.results)
    //             .map(result => result[0].transcript)
    //             .join('');
    //         setPrescriptionContent(transcript);
    //     };

    //     recognition.onend = () => {
    //         setIsListening(false);
    //     };

    //     if (isListening) {
    //         recognition.stop();
    //     } else {
    //         recognition.start();
    //     }
    // };

    useEffect(() => {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (SpeechRecognition) {
            const recognition = new SpeechRecognition();
            recognition.continuous = true;
            recognition.interimResults = true;

            recognition.onresult = (event) => {
                const transcript = Array.from(event.results)
                    .map(result => result[0].transcript)
                    .join('');

                switch (activeEditor) {
                    case 'complaints':
                        setComplaintsContent(transcript);
                        break;
                    case 'clinicalFindings':
                        setClinicalFindingsContent(transcript);
                        break;
                    case 'diagnosis':
                        setDiagnosisContent(transcript);
                        break;
                    case 'knownDiagnosis':
                        setKnownDiagnosisContent(transcript);
                        break;
                    default:
                        setPrescriptionContent(transcript);
                }
            };

            recognition.start();
            recognitionRef.current = recognition;

            return () => {
                recognition.stop();
            };
        }
    }, [activeEditor]);

    return (
        <div className="container">
            {isLoading && <img src={require('../../assets/images/loading.gif')} alt="Loading" className="loading-gif" />}
            <Grid container spacing={2} className="registration-section">
                <Grid item sm={12} xs={12}>
                    <h5>Prescription &rarr;</h5>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <FormControl fullWidth>
                        <InputLabel id="pSa">Salutation</InputLabel>
                        <Select
                            labelId="pSalutan"
                            id="pSalutation"
                            name="pSalutation"
                            label="Salutation"
                            value={userRegistration.pSalutation}
                            onChange={handleInput}
                        >
                            <MenuItem value="">Select</MenuItem>
                            <MenuItem value={'Mr'}>Mr.</MenuItem>
                            <MenuItem value={'Miss'}>Miss.</MenuItem>
                            <MenuItem value={'Mrs'}>Mrs.</MenuItem>
                        </Select>
                    </FormControl>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField
                        required
                        variant="outlined"
                        label="Full Name"
                        name="pName"
                        id="pName"
                        value={userRegistration.pName}
                        onChange={handleInput}
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField
                        required
                        variant="outlined"
                        label="Age"
                        name="pAge"
                        id="pAge"
                        value={userRegistration.pAge}
                        onChange={handleInput}
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <FormControl fullWidth>
                        <InputLabel id="Gender">Gender</InputLabel>
                        <Select
                            required
                            labelId="Gender"
                            id="pGender"
                            name="pGender"
                            label="Gender"
                            value={userRegistration.pGender}
                            onChange={handleInput}
                        >
                            <MenuItem value={'Male'}>Male</MenuItem>
                            <MenuItem value={'Female'}>Female</MenuItem>
                        </Select>
                    </FormControl>
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField
                        required
                        variant="outlined"
                        label="Number"
                        name="pNum"
                        id="pNum"
                        value={userRegistration.pNum}
                        onChange={handleInput}
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <TextField
                        variant="outlined"
                        label="Email"
                        type="email"
                        name="pEmail"
                        id="pEmail"
                        value={userRegistration.pEmail}
                        onChange={handleInput}
                    />
                </Grid>
                <Grid item sm={3} xs={6}>
                    <FormControl fullWidth style={{ width: '300px' }}>
                        <InputLabel id="doctorSelection">Select a Doctor</InputLabel>
                        <Select
                            required
                            labelId="doctorSelection"
                            id="doctorName"
                            name="doctorName"
                            label="Select a Doctor"
                            value={userRegistration.doctorName}
                            onChange={handleDoctorSelection}
                        >
                            {availableDoctors.map((doctor) => (
                                <MenuItem key={doctor._id} value={doctor._id}>
                                    {doctor.drName}
                                </MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>
                {/* <Grid item sm={3} xs={6}>
                    <TextField
                        variant="outlined"
                        label="Prescription ID"
                        name="billId"
                        id="billId"
                        value={userRegistration.billId}
                        onChange={handleInput}
                    />
                </Grid> */}
            </Grid>
            <div className="container mt-4">
                <Grid container spacing={2} className="vitals-section">
                    <Grid item sm={12} xs={12}>
                        <h5>Vitals &rarr;</h5>
                    </Grid>
                    <Grid item sm={3} xs={6}>
                        <TextField
                            variant="outlined"
                            label="Blood Pressure"
                            name="bloodPressure"
                            value={vitals.bloodPressure}
                            onChange={handleVitalsChange}
                        />
                    </Grid>
                    <Grid item sm={3} xs={6}>
                        <TextField
                            variant="outlined"
                            label="Heart Rate (bpm)"
                            name="heartRate"
                            value={vitals.heartRate}
                            onChange={handleVitalsChange}
                        />
                    </Grid>
                    <Grid item sm={3} xs={6}>
                        <TextField
                            variant="outlined"
                            label="Temperature (°C)"
                            name="temperature"
                            value={vitals.temperature}
                            onChange={handleVitalsChange}
                        />
                    </Grid>
                    <Grid item sm={3} xs={6}>
                        <TextField
                            variant="outlined"
                            label="Respiratory Rate (bpm)"
                            name="respiratoryRate"
                            value={vitals.respiratoryRate}
                            onChange={handleVitalsChange}
                        />
                    </Grid>
                    <Grid item sm={3} xs={6}>
                        <TextField
                            variant="outlined"
                            label="Height (cm)"
                            name="height"
                            value={vitals.height}
                            onChange={handleVitalsChange}
                        />
                    </Grid>
                    <Grid item sm={3} xs={6}>
                        <TextField
                            variant="outlined"
                            label="Weight (kg)"
                            name="weight"
                            value={vitals.weight}
                            onChange={handleVitalsChange}
                        />
                    </Grid>
                </Grid>

                {/* Medical Sections */}
                <div className="container mt-4">
                    <Grid container spacing={3}>
                        {/* Complaints & Clinical Findings Side by Side */}
                        <Grid container spacing={3}>
                            <Grid item xs={12} md={6}>
                                <h5>Complaints</h5>
                                <div onFocus={() => setActiveEditor('complaints')}>
                                    <CKEditor
                                        editor={ClassicEditor}
                                        data={complaintsContent}
                                        onChange={handleComplaintsChange}
                                    />
                                </div>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <h5>Clinical Findings</h5>
                                <div onFocus={() => setActiveEditor('clinicalFindings')}>
                                    <CKEditor
                                        editor={ClassicEditor}
                                        data={clinicalFindingsContent}
                                        onChange={handleClinicalFindingsChange}
                                    />
                                </div>
                            </Grid>
                        </Grid>

                        {/* Diagnosis Sections */}
                        <Grid container spacing={3}>
                            <Grid item xs={12} md={6}>
                                <h5>Diagnosis</h5>
                                <div onFocus={() => setActiveEditor('diagnosis')}>
                                    <CKEditor
                                        editor={ClassicEditor}
                                        data={diagnosisContent}
                                        onChange={handleDiagnosisChange}
                                    />
                                </div>
                            </Grid>

                            <Grid item xs={12} md={6}>
                                <h5>Known Diagnosis</h5>
                                <div onFocus={() => setActiveEditor('knownDiagnosis')}>
                                    <CKEditor
                                        editor={ClassicEditor}
                                        data={knownDiagnosisContent}
                                        onChange={handleKnownDiagnosisChange}
                                    />
                                </div>
                            </Grid>
                        </Grid>
                    </Grid>
                </div>

                {/* Advice on Medicines Section */}
                <div className="container mt-4">
                    <h5>Advice on Medicines &rarr;</h5>
                    <Paper elevation={3} className="medicine-section">
                        <Grid container spacing={2} alignItems="center">
                            {/* Medicine Search Autocomplete */}
                            <Grid item xs={12} md={4}>
                                <Autocomplete
                                    options={allMedicines}
                                    getOptionLabel={(option) => option.medicine}
                                    onChange={handleMedicineSelect}
                                    renderInput={(params) => (
                                        <TextField
                                            {...params}
                                            label="Search Medicine"
                                            variant="outlined"
                                            fullWidth
                                        />
                                    )}
                                />
                            </Grid>

                            {/* Composition Field */}
                            <Grid item xs={12} md={8}>
                                <TextField
                                    label="Composition"
                                    fullWidth
                                    value={newMedicine.composition}
                                    InputProps={{ readOnly: true }}
                                />
                            </Grid>

                            {/* Medicine Details */}
                            <Grid item xs={6} md={2}>
                                <Select
                                    fullWidth
                                    value={newMedicine.foodType}
                                    onChange={(e) => setNewMedicine(prev => ({ ...prev, foodType: e.target.value }))}
                                    displayEmpty
                                >
                                    <MenuItem value="">Food Type</MenuItem>
                                    <MenuItem value="Before Food">Before Food</MenuItem>
                                    <MenuItem value="After Food">After Food</MenuItem>
                                    <MenuItem value="Anytime">Anytime</MenuItem>
                                </Select>
                            </Grid>

                            <Grid item xs={6} md={2}>
                                <Select
                                    fullWidth
                                    value={newMedicine.duration}
                                    onChange={(e) => setNewMedicine(prev => ({ ...prev, duration: e.target.value }))}
                                    displayEmpty
                                >
                                    <MenuItem value="">Duration</MenuItem>
                                    <MenuItem value="1 Day">1 Day</MenuItem>
                                    <MenuItem value="3 Days">3 Days</MenuItem>
                                    <MenuItem value="1 Week">1 Week</MenuItem>
                                    <MenuItem value="2 Weeks">2 Weeks</MenuItem>
                                </Select>
                            </Grid>

                            <Grid item xs={6} md={2}>
                                <Select
                                    fullWidth
                                    value={newMedicine.frequency}
                                    onChange={(e) => setNewMedicine(prev => ({ ...prev, frequency: e.target.value }))}
                                    displayEmpty
                                >
                                    <MenuItem value="">Frequency</MenuItem>
                                    <MenuItem value="Once Daily">Once Daily</MenuItem>
                                    <MenuItem value="Twice Daily">Twice Daily</MenuItem>
                                    <MenuItem value="Thrice Daily">Thrice Daily</MenuItem>
                                </Select>
                            </Grid>

                            <Grid item xs={6} md={2}>
                                <TextField
                                    label="Tablets"
                                    type="number"
                                    fullWidth
                                    value={newMedicine.tablets}
                                    onChange={(e) => setNewMedicine(prev => ({ ...prev, tablets: e.target.value }))}
                                />
                            </Grid>

                            <Grid item xs={12} md={2}>
                                <Button
                                    variant="contained"
                                    color="primary"
                                    fullWidth
                                    onClick={addMedicine}
                                >
                                    Add Medicine
                                </Button>
                            </Grid>
                        </Grid>
                    </Paper>

                    {/* Added Medicines List */}
                    {medicines.length > 0 && (
                        <Paper elevation={3} className="medicine-section mt-3">
                            <Typography variant="h6" gutterBottom>
                                Added Medicines
                            </Typography>
                            {medicines.map((medicine, index) => (
                                <Paper key={index} elevation={1} className="medicine-item">
                                    <Grid container alignItems="center" spacing={2}>
                                        <Grid item xs={3}>
                                            <Typography variant="subtitle1">
                                                <strong>{medicine.medicineName}</strong>
                                            </Typography>
                                            <Typography variant="body2">
                                                {medicine.composition}
                                            </Typography>
                                        </Grid>
                                        <Grid item xs={2}>{medicine.foodType}</Grid>
                                        <Grid item xs={2}>{medicine.duration}</Grid>
                                        <Grid item xs={2}>{medicine.frequency}</Grid>
                                        <Grid item xs={2}>{medicine.tablets} tablets</Grid>
                                        <Grid item xs={1}>
                                            <IconButton onClick={() => removeMedicine(index)}>
                                                <DeleteIcon color="error" />
                                            </IconButton>
                                        </Grid>
                                    </Grid>
                                </Paper>
                            ))}
                        </Paper>
                    )}
                </div>

                <div className="select-test-section">
                    <h5 style={{ color: '#8F00FF' }}>Select The Tests</h5>

                    <Autocomplete
                        style={{ marginTop: '15px' }}
                        multiple
                        options={filteredTests}
                        getOptionLabel={(option) => {
                            if (option.type === 'Profile') {
                                return option.profileName;
                            } else if (option.type === 'Group') {
                                return option.groupName;
                            } else if (option.type === 'OtherFees') {
                                return option.feesName;
                            } else {
                                return option.name;
                            }
                        }}
                        value={selectedTests}
                        onChange={(event, newValue) => {
                            if (newValue) {
                                handleTestSelection(newValue);
                            }
                        }}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                type="text"
                                label="Search for tests"
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        )}
                    />

                    {/* Render selected tests below */}
                    {renderSelectedTests()}
                </div>


                <div onFocus={() => setActiveEditor('prescription')}>
                    <h5>Advice</h5>

                    <CKEditor
                        editor={ClassicEditor}
                        data={prescriptionContent}
                        onChange={handlePrescriptionChange}
                    />
                </div>

                {/* <Button
                    variant="contained"
                    color="primary"
                    onClick={handleSpeechRecognition}
                    className="speech-button"
                >
                    {isListening ? 'Stop Listening' : 'Start Speaking'}
                </Button> */}
                <div className="mt-3 text-center">
                    <Button
                        variant="contained"
                        color="primary"
                        onClick={savePrescription}
                        disabled={isSavePrescription}
                        style={{ marginRight: '20px' }}>
                        {isSavePrescription ? 'Saving...' : 'Save Prescription'}
                    </Button>
                    <Button
                        variant="contained"
                        color="primary"
                        onClick={printPrescription}
                        disabled={isPrescription}>
                        {isPrescription ? 'Generating PDF...' : 'Print Prescription'}
                    </Button>
                </div>
            </div>
        </div>
    );
};

export default NewVisit;