import React, { useState, useEffect, useRef } from 'react';
import { TextField, Button, Grid, Container, Card, CardContent, Typography } from '@mui/material';
import axios from 'axios';
import StarIcon from '@mui/icons-material/Star';
import StarBorderIcon from '@mui/icons-material/StarBorder';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

const MostVisitingPatients = () => {
  const [fromDate, setFromDate] = useState(new Date().toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [patients, setPatients] = useState([]);
  const componentRef = useRef();

  const fetchPatients = async () => {
    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      const response = await axios.get(`${apiBaseUrl}/auth/most-visiting-patients`, {
        params: { fromDate, toDate }
      });
      setPatients(response.data);
    } catch (error) {
      console.error('Error fetching patients:', error);
    }
  };

  useEffect(() => {
    if (fromDate && toDate) {
      fetchPatients();
    }
  }, [fromDate, toDate]);

  const handleDateChange = (setter) => (event) => {
    setter(event.target.value);
  };

  const renderStars = (count) => {
    const stars = [];
    for (let i = 0; i < 5; i++) {
      if (i < count) {
        stars.push(<StarIcon key={i} />);
      } else {
        stars.push(<StarBorderIcon key={i} />);
      }
    }
    return stars;
  };

  const downloadPDF = () => {
    const input = componentRef.current;
    html2canvas(input).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const imgProps = pdf.getImageProperties(imgData);
      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
      pdf.save('most-visiting-patients.pdf');
    });
  };

  return (
    <Container>
      <Typography variant="h5" gutterBottom>
      Frequent Patients &rarr;
      </Typography>
      <Grid container spacing={3}>
        <Grid item xs={6}>
          <TextField
            type="date"
            label="From Date"
            value={fromDate}
            onChange={handleDateChange(setFromDate)}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={6}>
          <TextField
            type="date"
            label="To Date"
            value={toDate}
            onChange={handleDateChange(setToDate)}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={12}>
          <Button
            variant="contained"
            color="primary"
            onClick={fetchPatients}
            disabled={!fromDate || !toDate}
          >
            Fetch Patients
          </Button>
          {/* <Button
            variant="contained"
            color="secondary"
            onClick={downloadPDF}
            style={{ marginLeft: '10px' }}
          >
            Download as PDF
          </Button> */}
        </Grid>
      </Grid>
      <div ref={componentRef} style={{ marginTop: '20px' }}>
        <Grid container spacing={3}>
          {patients.map((patient) => (
            <Grid item xs={12} sm={6} md={4} key={patient.patient._id}>
              <Card>
                <CardContent>
                  <Typography variant="h6">
                    {patient.patient.pName}
                  </Typography>
                  <Typography color="textSecondary">
                    {patient.patient.pNum}
                  </Typography>
                  <div>{renderStars(Math.min(patient.visitCount, 5))}</div>
                  <Typography variant="body2">
                    Visits: {patient.visitCount}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      </div>
    </Container>
  );
};

export default MostVisitingPatients;
