import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import { Grid, TextField, Typography, Modal } from '@mui/material';
import { useNavigate } from 'react-router-dom'; // Import useHistory
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  Autocomplete,
  Link,
  Dialog, // Import Dialog
  DialogTitle, // Import DialogTitle
  DialogContent, // Import DialogContent
  DialogContentText, // Import DialogContentText
  DialogActions, // Import DialogActions
} from '@mui/material';
import './BillDetail.css'

const BillDetail = () => {

  const { objbillId } = useParams();

  const navigate = useNavigate();

  const [billDetails, setBillDetails] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isModalOpenTest, setIsModalOpenTest] = useState(false);
  const [dueAmount, setDueAmount] = useState(0);

  const [availableTests, setAvailableTests] = useState([]);
  const [selectedTests, setSelectedTests] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredTests, setFilteredTests] = useState([]);

  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);

  const [isPrinting, setIsPrinting] = useState(false);


  const handleOpenDeleteDialog = () => {
    setIsDeleteDialogOpen(true);
  };

  const handleCloseDeleteDialog = () => {
    setIsDeleteDialogOpen(false);
  };

  // Modal CSS
  const modalStyle = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: '1000px', // Adjust width as needed
    backgroundColor: '#fff',
    padding: '20px',
    borderRadius: '8px',
    boxShadow: '0px 0px 10px rgba(0, 0, 0, 0.2)',
  };

  const handleonClick = () => {
    // Navigate to billDetails component with the selected billId
    navigate(`/labResultentry/${objbillId}`)
  };

  const handleOpenModal = () => {
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  // Handle opening and closing the modal
  const openModal = () => {
    setIsModalOpenTest(true);
  };

  const closeModal = () => {
    setIsModalOpenTest(false);
  };

  useEffect(() => {
    const fetchBillDetails = async () => {
      try {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        const response = await axios.get(`${apiBaseUrl}/auth/billDetails/${objbillId}`);
        setBillDetails(response.data); // Assuming the API response contains the bill details
      } catch (error) {
        console.error('Error fetching bill details:', error);
      }
    };

    fetchBillDetails();
  }, [objbillId]);

  useEffect(() => {
    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    const fetchAllTests = async () => {
      try {
        const [testsResponse, groupTestsResponse, profileTestsResponse, feesResponse] = await Promise.all([
          axios.get(`${apiBaseUrl}/auth/tests`),
          axios.get(`${apiBaseUrl}/auth/getGroupTestList`),
          axios.get(`${apiBaseUrl}/auth/getProfileList`),
          axios.get(`${apiBaseUrl}/auth/getfeesList`),

        ]);

        // Add type information to each test
        const testsWithTypes = [
          ...testsResponse.data.map((test) => ({ ...test, type: 'Test', department: 'Lab' })),
          ...groupTestsResponse.data.map((test) => ({ ...test, type: 'Group', department: 'Lab' })),
          ...profileTestsResponse.data.map((test) => ({ ...test, type: 'Profile', department: 'Lab' })),
          ...feesResponse.data.map((test) => ({ ...test, type: 'OtherFees' })),
        ];

        setAvailableTests(testsWithTypes);
        setFilteredTests(testsWithTypes); // Initialize filteredTests with all available tests
      } catch (error) {
        console.error('Error fetching available tests:', error);
      }
    };

    fetchAllTests();
  }, []);

  useEffect(() => {
    // Filter available tests based on the search term
    const filtered = availableTests.filter((test) => {
      if (test.type === 'Profile') {
        const profileName = test.profileName || '';
        return profileName.toLowerCase().includes(searchTerm.toLowerCase());
      } else if (test.type === 'Group') {
        const groupName = test.groupName || '';
        return groupName.toLowerCase().includes(searchTerm.toLowerCase());
      } else if (test.type === 'OtherFees') {
        const feesName = test.feesName || '';
        return feesName.toLowerCase().includes(searchTerm.toLowerCase());
      } else {
        const testName = test.name || '';
        return testName.toLowerCase().includes(searchTerm.toLowerCase());
      }
    });

    setFilteredTests(filtered);
  }, [searchTerm, availableTests]);



  const handleTestSelection = (newTests) => {
    // Filter out the tests that are already selected
    const uniqueNewTests = newTests.filter((test) => {
      return !selectedTests.some((selectedTest) => selectedTest._id === test._id);
    });

    setSelectedTests([...selectedTests, ...uniqueNewTests]);
    setSearchTerm(''); // Clear the search term after selecting
  };


  const handleRemoveTest = (testToRemove) => {
    const updatedSelectedTests = selectedTests.filter((test) => test !== testToRemove);
    setSelectedTests(updatedSelectedTests);
  };

  // Handle adding selected tests to the bill
  const handleAddTestsToBill = () => {
    // Make the PUT request to update the test
    const apiBaseUrl = process.env.REACT_APP_API_KEY;
    axios
      .put(`${apiBaseUrl}/auth/updateTest/${objbillId}`, { selectedTests })
      .then((response) => {
        // Handle a successful response
        console.log('Test updated successfully:', response.data);

        const updatedBillDetails = {
          ...billDetails,
          data: {
            ...billDetails.data,
            billAmount: response.data.billAmount,
            amountDue: response.data.amountDue,
          },
          feesData: [
            ...billDetails.feesData, // Include the existing tests
            ...response.data.updatedSelectedTests.map((test) => ({
              fees: test.fees,
              feesType: test.feesType,
              // ... other properties from the test object
            })),
          ],
        };

        // Update billDetails with the new data
        setBillDetails(updatedBillDetails);

      })
      .catch((error) => {
        // Handle errors if the request fails
        console.error('Error updating test:', error);
        // Optionally, display an error message to the user
      });

    closeModal();
  };

  const handleCollectDue = () => {
    const dueAmountNumber = parseFloat(dueAmount);
    const amountDueNumber = parseFloat(billDetails.data.amountDue);

    if (!isNaN(dueAmountNumber) && dueAmountNumber <= amountDueNumber) {
      // Make an API call to update the due amount
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      axios
        .put(`${apiBaseUrl}/auth/updateDueAmount/${objbillId}`, { dueAmount: dueAmountNumber })
        .then((response) => {
          // Handle the successful response from the API
          console.log('Due amount collected successfully:', response.data);

          // After collecting the due, you can close the modal.
          handleCloseModal();

          // Update the billDetails state with the new data received from the API response
          setBillDetails((prevBillDetails) => ({
            ...prevBillDetails,
            data: {
              ...prevBillDetails.data,
              amountDue: response.data.updatedBillDetails.amountDue,
              amountPaid: response.data.updatedBillDetails.amountPaid,
              billAmount: response.data.updatedBillDetails.billAmount,
            },
          }));
        })
        .catch((error) => {
          // Handle errors if the API call fails
          console.error('Error collecting due amount:', error);
          // You can also display an error message to the user if needed.
        });
    } else {
      // Display an error message or perform other actions to handle the case
      alert('Amount cannot be greater than the due amount or invalid input.');
    }
  };

  const handleDelete = () => {
    // Make an API call to delete the bill and its details
    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    axios
      .delete(`${apiBaseUrl}/auth/deleteBill/${objbillId}`)
      .then((response) => {
        // Handle a successful response (e.g., show a success message)
        console.log('Bill deleted successfully:', response.data);

        // Optionally, navigate the user to a different page or update the UI as needed
        // For example, navigate back to the bill list page
        navigate('/bil-list');
      })
      .catch((error) => {
        // Handle errors if the delete request fails
        console.error('Error deleting bill:', error);
        // Optionally, display an error message to the user
      });

    // Close the delete confirmation dialog
    handleCloseDeleteDialog();
  };



  const handlePrint = async () => {
    setIsPrinting(true);
    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;

      const response = await axios.post(
        `${apiBaseUrl}/auth/print-bill/${objbillId}`,
        {},
        {
          responseType: 'blob',
          headers: {
            'Content-Type': 'application/json',
          },
        }
      );

      // Create a blob from the binary data
      const blob = new Blob([response.data], { type: 'application/pdf' });

      // Create a URL for the blob
      const pdfUrl = URL.createObjectURL(blob);

      // Open the PDF in a new tab/window
      window.open(pdfUrl, '_blank');

    } catch (error) {
      // Handle error
      console.error('Error printing bill:', error);
    } finally {
      setIsPrinting(false);
    }
  };


  if (!billDetails) {
    // return <div>Loading...</div>;
    return <img
      src={require('../../assets/images/loading.gif')}
      alt="bb"
      style={{ width: '100px', height: '100px' }}
    />
  }

  return (
    <div className='container'>

      {/* Modal */}
      {/* <div className='container'> */}
      <Modal open={isModalOpenTest} onClose={closeModal}>
        <div style={modalStyle} className="modal-content">
          <h3>Add Tests to Bill</h3>
          {/* Autocomplete to select tests */}
          <Autocomplete
            style={{ marginBottom: '10px' }}
            multiple
            options={filteredTests}
            getOptionLabel={(option) => {
              if (option.type === 'Profile') {
                return option.profileName;
              } else if (option.type === 'Group') {
                return option.groupName;
              } else if (option.type === 'OtherFees') {
                return option.feesName;
              } else {
                return option.name;
              }
            }}
            value={selectedTests}
            onChange={(event, newValue) => {
              if (newValue) {
                handleTestSelection(newValue);
              }
            }}
            renderInput={(params) => (
              <TextField
                {...params}
                type="text"
                label="Search for tests"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            )}
          />

          {/* Selected tests */}
          {selectedTests.length > 0 && (
            <div className="selected-tests">
              <h4>Selected Tests:</h4>
              <ul>
                {selectedTests.map((test) => {
                  const testName =
                    test.type === 'Profile'
                      ? test.profileName
                      : test.type === 'Group'
                        ? test.groupName
                        : test.type === 'OtherFees'
                          ? test.feesName
                          : test.name;

                  const testPrice =
                    test.type === 'Profile'
                      ? test.profilePrice
                      : test.type === 'Group'
                        ? test.groupPrice
                        : test.type === 'OtherFees'
                          ? test.opFees
                          : test.fees;
                  return (
                    <li key={`${test.type}-${test._id}`}>
                      {`${test.type} Name: ${testName} - Price: ₹${testPrice} per ${test.units || ''}`}
                      <Button
                        variant="contained"
                        color="secondary"
                        onClick={() => handleRemoveTest(test)}
                      >
                        Remove
                      </Button>
                    </li>
                  );
                })}
              </ul>
            </div>
          )}

          {/* Button to add selected tests to the bill */}
          <Button style={{
            marginRight: '10px',
            backgroundColor: '#8F00FF',
            color: 'white',
            border: 'none',
            fontWeight: 'bold',
            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
          }} onClick={handleAddTestsToBill}>
            Add Tests to Bill
          </Button>
        </div>
      </Modal>

      <Dialog
        open={isDeleteDialogOpen}
        onClose={handleCloseDeleteDialog}
      >
        <DialogTitle>Confirm Delete</DialogTitle>
        <DialogContent>
          <DialogContentText>
            Are you sure you want to delete this bill? This action cannot be undone.
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDeleteDialog} color="primary">
            Cancel
          </Button>
          <Button onClick={handleDelete} color="secondary">
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* </div> */}
      <TableContainer component={Paper}>

        <Grid container>
          {billDetails.data && (
            <Grid item xs={12} >
              <Grid container>
                <Grid item xs={4} >
                  <Typography variant="body1">
                    Patient Name: <span style={{ fontWeight: 'bold', }}>{billDetails.data.pSal} {billDetails.data.pName}</span>
                  </Typography>
                  <Typography variant="body1">
                    Sex / Age: <span style={{ fontWeight: 'bold' }}> {billDetails.data.pGender} / {billDetails.data.pAge}</span>
                  </Typography>
                  <Typography>
                    Referred By: <span style={{ fontWeight: 'bold' }}>{billDetails.data.drName}</span>
                  </Typography>
                </Grid>


                <Grid item xs={4}>
                  <Typography variant="body1">
                    Date: <span style={{ fontWeight: 'bold' }}> {billDetails.data.billDate}</span>
                  </Typography>
                  <Typography>
                    Bill ID: <span style={{ fontWeight: 'bold' }}>{billDetails.data.billId}</span>
                  </Typography>
                </Grid>

                <Grid item xs={4}>

                  <Typography variant="body1">
                    Bill Amount: <span style={{ fontWeight: 'bold', }}>{billDetails.data.billAmount} </span>
                  </Typography>
                  <Typography variant="body1">
                    Discount Amount: <span style={{ fontWeight: 'bold', }}>{billDetails.data.discountAmount} </span>
                  </Typography>
                  <Typography variant="body1">
                    Paid: <span style={{ fontWeight: 'bold' }}>{billDetails.data.amountPaid}</span>
                  </Typography>
                  <Typography>
                    Due Amount: <span style={{ fontWeight: 'bold' }}>{billDetails.data.amountDue}</span>
                  </Typography>
                </Grid>
              </Grid>
            </Grid>


          )}
        </Grid>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell style={{ fontWeight: 'bold' }}>Test Name</TableCell>
              <TableCell style={{ fontWeight: 'bold' }}>Price</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {billDetails.feesData.map((details) => (
              <TableRow key={details.id}>
                <TableCell>{details.feesType}</TableCell>
                <TableCell>{details.fees}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
      <div className="buttons" style={{ marginTop: '20px' }}>
        <Button disabled={isPrinting} variant="contained" color="primary"
          style={{
            marginRight: '10px',
            backgroundColor: '#8F00FF',
            color: 'white',
            border: 'none',
            fontWeight: 'bold',
            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
          }} onClick={handlePrint} >
          {isPrinting ? 'Printing ...' : 'Print Bill'}
        </Button>
        {billDetails.data.amountDue > 0 && (
          <Button variant="contained" color="primary"
            style={{
              marginRight: '10px',
              backgroundColor: '#8F00FF',
              color: 'white',
              border: 'none',
              fontWeight: 'bold',
              boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
            }} onClick={handleOpenModal}>
            Collect Due
          </Button>
        )}
        {/* Button to open the modal */}

        <Button variant="contained" color="primary"
          style={{
            marginRight: '10px',
            backgroundColor: '#8F00FF',
            color: 'white',
            border: 'none',
            fontWeight: 'bold',
            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
          }}
          onClick={openModal} >
          Add Test
        </Button>

        <Button
          variant="contained"
          color="secondary"
          style={{
            marginRight: '10px',
            backgroundColor: 'red',
            color: 'white',
            border: 'none',
            fontWeight: 'bold',
            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
          }}
          onClick={handleOpenDeleteDialog}
        >
          Delete
        </Button>

        <Button variant="contained" color="secondary"
          style={{
            marginRight: '10px',
            backgroundColor: '#8F00FF',
            color: 'white',
            border: 'none',
            fontWeight: 'bold',
            boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)', // Add the box-shadow property
          }}
          onClick={handleonClick}>
          View Report
        </Button>

        {/* Due Collection Modal */}
        <Modal
          open={isModalOpen}
          onClose={handleCloseModal}
          aria-labelledby="modal-title"
          aria-describedby="modal-description"
        >
          <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }}>
            <Paper style={{ padding: '20px', textAlign: 'center' }}>
              <Typography variant="h5" id="modal-title">
                Collect Due Amount
              </Typography>
              <Typography variant="body1" id="modal-description">
                Due Amount: {billDetails.data.amountDue}
              </Typography>
              <TextField
                label="Amount to Collect"
                variant="outlined"
                fullWidth
                type="number"
                value={dueAmount}
                onChange={(e) => setDueAmount(e.target.value)}
                style={{ margin: '10px 0' }}
              />
              <Button variant="contained" color="primary" onClick={handleCollectDue}>
                Collect
              </Button>
            </Paper>
          </div>
        </Modal>
      </div>
    </div>
  );
};

export default BillDetail;
