import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import { Button } from 'react-bootstrap';
import { Grid, Autocomplete, TextField } from '@mui/material';


const UpdateProfile = () => {

    const { profileId } = useParams();


    const [availableTests, setAvailableTests] = useState([]);
    const [selectedTests, setSelectedTests] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [filteredTests, setFilteredTests] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');

    const [loadingTests, setLoadingTests] = useState(true);
    const [error, setError] = useState(null);

    const [groupTest, setGroupTest] = useState({
        groupCategory: '',
        profileName: '',
        profilePrice: 0,
        testFields: [],
    });

    useEffect(() => {
        const fetchTests = async () => {
            try {
                const apiBaseUrl = process.env.REACT_APP_API_KEY;
                const [testsResponse, groupTestsResponse] = await Promise.all([
                    axios.get(`${apiBaseUrl}/auth/tests`),
                    axios.get(`${apiBaseUrl}/auth/getGroupTestList`)
                ]);

                setAvailableTests([
                    ...testsResponse.data.map(test => ({ ...test, type: 'Test' })),
                    ...groupTestsResponse.data.map(test => ({ ...test, type: 'Group' }))
                ]);

                setLoadingTests(false);
            } catch (error) {
                console.error('Error fetching tests:', error);
                setError('Error fetching tests. Please try again.');
                setLoadingTests(false);
            }
        };

        fetchTests();
    }, []);


    useEffect(() => {
        // Filter available tests based on search query
        const filtered = availableTests.filter(test =>
            (test.name && test.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
            (test.groupName && test.groupName.toLowerCase().includes(searchQuery.toLowerCase()))
        );
        setFilteredTests(filtered);
    }, [searchQuery, availableTests]);


    useEffect(() => {
        // Fetch the existing group test data and populate the state
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.get(`${apiBaseUrl}/auth/findProfilebyId/${profileId}`)
            .then(response => {
                setGroupTest(response.data);
            })
            .catch(error => {
                console.error('Error fetching group test:', error);
            });
    }, [profileId]);


    const handleInputChange = (e) => {
        const { name, value } = e.target;
        const newValue = name === 'profilePrice' ? parseFloat(value) : value;
        setGroupTest({ ...groupTest, [name]: newValue });
    };



    const handleRemoveTestField = (index) => {
        const updatedTestFields = [...groupTest.testFields];
        updatedTestFields.splice(index, 1);
        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    const handleGroupTestCreation = (e) => {

        e.preventDefault(); // Prevent default form submission behavior

        // Create the group test object with the gathered information
        const updatedGroupTest = {
            profileName: groupTest.profileName,
            profilePrice: groupTest.profilePrice,
            testFields: groupTest.testFields.map(testField => {
                const { _id, ...rest } = testField;
                return rest;
            })
        };

        // const testFields = selectedTests.map((test) => [test.id, test.name]);
        const selectedTestsData = selectedTests.map((test) => ({
            testId: test._id,
            testName: test.name || test.groupName,
        }));

        const groupTestDetails = {
            updatedGroupTest,
            selectedTestsData,
        };

        console.log(groupTestDetails);

        // Assuming you have an API endpoint for submission
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.put(`${apiBaseUrl}/auth/updateProfileTest/${profileId}`, groupTestDetails)
            .then(response => {
                toast.success('Updated successfully'); // Display success message
                setGroupTest({
                    profileName: '',
                    profilePrice: '',
                    // groupCategory: ''
                });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    };

    const moveItemUp = (index) => {
        if (index === 0) return; // Can't move the first item up

        const updatedTestFields = [...groupTest.testFields];
        const movedItem = updatedTestFields.splice(index, 1)[0];
        updatedTestFields.splice(index - 1, 0, movedItem);

        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    const moveItemDown = (index) => {
        if (index === groupTest.testFields.length - 1) return; // Can't move the last item down

        const updatedTestFields = [...groupTest.testFields];
        const movedItem = updatedTestFields.splice(index, 1)[0];
        updatedTestFields.splice(index + 1, 0, movedItem);

        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    const handleDragEnd = (result) => {
        if (!result.destination) return;

        const updatedTestFields = [...groupTest.testFields]; // Clone the array

        const [movedTestField] = updatedTestFields.splice(result.source.index, 1);
        updatedTestFields.splice(result.destination.index, 0, movedTestField);

        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };




    return (
        <div className='container'>
            <h5 style={{ textAlign: 'left'}}>Update Profile &rarr;</h5>

            <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                <Grid item xs={12}>
                    <TextField
                        label="Profile Name"
                        variant="outlined"
                        name="profileName"
                        required
                        fullWidth
                        value={groupTest.profileName}
                        onChange={handleInputChange}
                    />
                </Grid>
            </Grid>

            <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                <Grid item xs={12}>
                    <TextField
                        label="Price"
                        variant="outlined"
                        name="profilePrice"
                        required
                        fullWidth
                        value={groupTest.profilePrice}
                        onChange={handleInputChange}
                    />
                </Grid>
            </Grid>

            <Autocomplete
                multiple
                id="test-select"
                options={availableTests}
                // getOptionLabel={(option) => option.name}
                getOptionLabel={(option) => (option.name || option.groupName || '')}
                value={selectedTests}
                onChange={(event, newValue) => setSelectedTests(newValue)}
                renderInput={(params) => (
                    <TextField
                        {...params}
                        label="Search Tests"
                        variant="outlined"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                )}
            />

            <div>
                <h4>Test Fields</h4>
                <DragDropContext onDragEnd={handleDragEnd}>
                    <Droppable droppableId="testFields">
                        {(provided) => (
                            <div {...provided.droppableProps} ref={provided.innerRef}>
                                {groupTest.testFields && groupTest.testFields.map((testField, index) => (
                                    <Draggable
                                        key={testField.testName}
                                        draggableId={testField.testName}
                                        index={index}
                                    >
                                        {(provided) => (
                                            <div
                                                {...provided.draggableProps}
                                                {...provided.dragHandleProps}
                                                ref={provided.innerRef}
                                                style={{
                                                    border: '1px solid lightgray',
                                                    padding: '8px',
                                                    marginBottom: '8px',
                                                    backgroundColor: 'white',
                                                    position: 'relative', // Make the container relative

                                                }}
                                            >
                                                <div style={{ position: 'absolute', top: '0', right: '0' }}>

                                                    <Button
                                                        onClick={() => moveItemUp(index)}
                                                        disabled={index === 0}
                                                    >
                                                        Up
                                                    </Button>
                                                    <Button
                                                        onClick={() => moveItemDown(index)}
                                                        disabled={index === groupTest.testFields.length - 1}
                                                    >
                                                        Down
                                                    </Button>
                                                    <Button
                                                        onClick={() => handleRemoveTestField(index)}
                                                        variant="danger" // You can customize the variant
                                                    >
                                                        Delete
                                                    </Button>
                                                </div>
                                                <div style={{ fontWeight: 'bold' }}>
                                                    {testField.testName}
                                                </div>
                                            </div>
                                        )}
                                    </Draggable>
                                ))}
                                {provided.placeholder}
                            </div>
                        )}
                    </Droppable>
                </DragDropContext>
            </div>
            <Button onClick={handleGroupTestCreation} >Update Profile </Button>

        </div>
    );
};

export default UpdateProfile;
