import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Button, TextField, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, TablePagination } from '@mui/material';
import { Link } from 'react-router-dom';
import { useNavigate } from 'react-router-dom';

const ProfileList = () => {
    const navigate = useNavigate();
    const [testMasters, setTestMasters] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');

    const [currentPage, setCurrentPage] = useState(0);
    const [itemsPerPage, setItemsPerPage] = useState(10);

    const totalPages = Math.ceil(testMasters.length / itemsPerPage);

    const startIndex = currentPage * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;

    const nextPage = () => {
        setCurrentPage(Math.min(currentPage + 1, totalPages - 1));
    };

    const prevPage = () => {
        setCurrentPage(Math.max(currentPage - 1, 0));
    };

    const filteredTests = testMasters.filter(test =>
        test.profileName.toLowerCase().includes(searchTerm.toLowerCase())
    );

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.get(`${apiBaseUrl}/auth/getProfileList`)
            .then((response) => {
                setTestMasters(response.data);
            })
            .catch((error) => {
                console.error('Error fetching Test Masters:', error);
            });
    }, []);

    const handleDelete = (profileId) => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.delete(`${apiBaseUrl}/auth/deleteProfile/${profileId}`)
            .then((response) => {
                console.log('Profile deleted:', response.data);
                setTestMasters(testMasters.filter(master => master._id !== profileId));
            })
            .catch((error) => {
                console.error('Error deleting Profile:', error);
            });
    };

    const handlePageChange = (event, newPage) => {
        setCurrentPage(newPage);
    };

    const handleRowsPerPageChange = (event) => {
        setItemsPerPage(parseInt(event.target.value, 10));
        setCurrentPage(0);
    };

    return (
        <div className='container'>
            <h5 style={{ textAlign: 'left' }}>Profile List &rarr;</h5>
            <Button onClick={() => navigate("/create-profile")} style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none', marginBottom: '20px' }}>Create Profile</Button>
            <TableContainer component={Paper} >
                <TextField
                    type="text"
                    placeholder="Search Profile"
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    style={{ marginBottom: '10px' }}

                />
                <Table>
                    <TableHead style={{ backgroundColor: '#8F00FF' }}>
                        <TableRow>
                            <TableCell style={{ color: 'white' }}><strong>Profile Name</strong></TableCell>
                            <TableCell style={{ color: 'white' }}><strong>Price</strong></TableCell>
                            <TableCell style={{ color: 'white' }}></TableCell>
                            <TableCell style={{ color: 'white' }}></TableCell>
                            <TableCell style={{ color: 'white' }}><strong>Edit/Delete</strong></TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {filteredTests.slice(startIndex, endIndex).map(test => (
                            <TableRow key={test._id}>
                                <TableCell>{test.profileName}</TableCell>
                                <TableCell>{test.profilePrice}</TableCell>
                                <TableCell></TableCell>
                                <TableCell></TableCell>
                                <TableCell>
                                    <Link to={`/updateProfile/${test._id}`}>
                                        <Button style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>Edit</Button>
                                    </Link>
                                    <Button onClick={() => handleDelete(test._id)} style={{ backgroundColor: 'red', color: 'white', border: 'none' }}>Delete</Button>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
                <TablePagination
                    rowsPerPageOptions={[5, 10, 25]}
                    component="div"
                    count={filteredTests.length}
                    page={currentPage}
                    onPageChange={handlePageChange}
                    rowsPerPage={itemsPerPage}
                    onRowsPerPageChange={handleRowsPerPageChange}
                />
            </TableContainer>
        </div>
    );
};

export default ProfileList;
