import React, { useState } from 'react';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
import { toast } from 'react-toastify';
import { Grid } from '@mui/material';
import axios from 'axios';
import UserManagement from './UserManagment';

const UserCreate = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    confirmPassword: '',
  });

  const handleInputChange = (field) => (event) => {
    setFormData({ ...formData, [field]: event.target.value });
  };

  const handleCreate = async (event) => {
    event.preventDefault();

    const { username, password, confirmPassword } = formData;

    // Check if passwords match
    if (password !== confirmPassword) {
      alert("Passwords don't match.");
      return;
    }

    const newUser = { username, password };

    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      const response = await axios.post(`${apiBaseUrl}/auth/createUser`, newUser); // Replace with your actual backend API endpoint
      console.log('User created successfully:', response.data);
      toast.success('User created successfully');

    } catch (error) {
      console.error('Error creating user:', error);
    }

    // Reset form fields
    setFormData({
      username: '',
      password: '',
      confirmPassword: '',
    });
  };

  return (
    <div className='container'>
    <UserManagement />
    <h5 style={{ textAlign: 'left', marginTop: '20px' }}>Create User &rarr;</h5>
    <form onSubmit={handleCreate}>
      <Grid container spacing={2}>
        <Grid item xs={12}>
          <TextField
            required
            label="Username"
            variant="outlined"
            fullWidth
            value={formData.username}
            onChange={handleInputChange('username')}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            required
            label="Password"
            variant="outlined"
            fullWidth
            type="password"
            value={formData.password}
            onChange={handleInputChange('password')}
          />
        </Grid>
        <Grid item xs={12}>
          <TextField
            required
            label="Confirm Password"
            variant="outlined"
            fullWidth
            type="password"
            value={formData.confirmPassword}
            onChange={handleInputChange('confirmPassword')}
          />
        </Grid>
        <Grid item xs={12}>
          <Button style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}
            variant="contained"
            color="primary"
            type="submit"
            fullWidth
          >
            Create User
          </Button>
        </Grid>
      </Grid>
    </form>
  </div>
  );
};

export default UserCreate;
