import React, { useState } from "react";
import { TextField, Button, Container, Typography, Paper } from "@mui/material";
import axios from "axios";

const MedicineForm = () => {
  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  const [formData, setFormData] = useState({
    name: "",
    composition: "",
  });

  const [errors, setErrors] = useState({
    name: false,
    composition: false,
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const validateForm = () => {
    const newErrors = {
      name: formData.name.trim() === "",
      composition: formData.composition.trim() === "",
    };
    setErrors(newErrors);
    return !newErrors.name && !newErrors.composition;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    try {
      await axios.post(`${apiBaseUrl}/auth/add-medicine`, formData);
      alert("Medicine added successfully!");
      setFormData({ name: "", composition: "" }); // Reset form
    } catch (error) {
      console.error("Error adding medicine:", error);
    }
  };

  return (
    <Container maxWidth="sm">
      <Paper elevation={3} style={{ padding: 20, marginTop: 20 }}>
        <Typography variant="h5" gutterBottom>
          Add Medicine
        </Typography>
        <form onSubmit={handleSubmit}>
          <TextField
            label="Medicine Name"
            name="name"
            value={formData.name}
            onChange={handleChange}
            error={errors.name}
            helperText={errors.name ? "Medicine name is required" : ""}
            fullWidth
            margin="normal"
          />
          <TextField
            label="Composition"
            name="composition"
            value={formData.composition}
            onChange={handleChange}
            error={errors.composition}
            helperText={errors.composition ? "Composition is required" : ""}
            fullWidth
            margin="normal"
          />
          <Button type="submit" variant="contained" color="primary" fullWidth>
            Add Medicine
          </Button>
        </form>
      </Paper>
    </Container>
  );
};

export default MedicineForm;
