import React, { useEffect, useState } from 'react';
import axios from 'axios';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  TextField,
  Checkbox,
  Button,
} from '@mui/material';
import { Modal } from 'react-bootstrap';
import { toast } from 'react-toastify';
import { TablePagination } from '@mui/material';

const PatientPromotion = () => {
  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  const [patientList, setPatientList] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [selectedPatients, setSelectedPatients] = useState(new Set());
  const [showConfirmation, setShowConfirmation] = useState(false);
  const [message, setMessage] = useState('');
  const [isSendingWhatsapp, setIsSendingWhatsapp] = useState(false);

  // Pagination state variables
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);

  useEffect(() => {
    axios
      .get(`${apiBaseUrl}/auth/get-patients`)
      .then((response) => {
        setPatientList(response.data);
        setIsLoading(false);
      })
      .catch((error) => {
        console.error('Error fetching available patients:', error);
        setIsLoading(false);
      });
  }, []);

  const handleSelectAll = (event) => {
    if (event.target.checked) {
      setSelectedPatients(new Set(patientList.map((patient) => patient._id)));
    } else {
      setSelectedPatients(new Set());
    }
  };

  const handleSelectOne = (patientId) => {
    const newSelectedPatients = new Set(selectedPatients);
    if (selectedPatients.has(patientId)) {
      newSelectedPatients.delete(patientId);
    } else {
      newSelectedPatients.add(patientId);
    }
    setSelectedPatients(newSelectedPatients);
  };

  const handleSendMessages = () => {
    setShowConfirmation(true);
  };

  const handleConfirmSend = async () => {
    setShowConfirmation(false);
    setIsSendingWhatsapp(true);
    try {
      const selectedPatientIds = Array.from(selectedPatients);
      const payload = {
        patientIds: selectedPatientIds,
        message: message,
      };

      const response = await axios.post(
        `${apiBaseUrl}/auth/send-whatsapp`,
        payload
      );

      toast.success('Sent Whatsapp Successfully');
    } catch (error) {
      toast.error('Sending Failed');
    } finally {
      setIsSendingWhatsapp(false);
    }
  };

  const handleCancelSend = () => {
    setShowConfirmation(false);
  };

  const filteredPatients = patientList.filter((patient) => {
    const searchTerms = searchQuery.toLowerCase().split(' ');
    return searchTerms.every(
      (term) =>
        patient.pName.toLowerCase().includes(term) ||
        patient.pGender.toLowerCase().includes(term) ||
        patient.pNum.toString().includes(term) ||
        patient.pEmail.toLowerCase().includes(term)
    );
  });

  const startIndex = page * rowsPerPage;
  const endIndex = startIndex + rowsPerPage;

  const paginatedPatients = filteredPatients.slice(startIndex, endIndex);

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  if (isLoading) {
    return <img
      src={require('../../assets/images/loading.gif')}
      alt="Loading"
      style={{ width: '100px', height: '100px' }}
    />;
  }

  return (
    <>
      <div className="container">
        <h5 style={{ textAlign: 'left'}}>Patient Promotions &rarr;</h5>
        <TextField
          label="Search Patients"
          variant="outlined"
          fullWidth
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          style={{ marginBottom: '20px' }}
        />
        <TableContainer component={Paper}>
          <Table>
            <TableHead style={{backgroundColor:'#8F00FF'}}>
              <TableRow >
                <TableCell padding="checkbox" style={{ color:'white'}}>
                  <Checkbox
                    indeterminate={selectedPatients.size > 0 && selectedPatients.size < patientList.length}
                    checked={selectedPatients.size === patientList.length}
                    onChange={handleSelectAll}
                    color="primary"
                  />
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Name</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Gender</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Phone</strong>
                </TableCell>
                <TableCell style={{ color:'white'}}>
                  <strong>Email</strong>
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedPatients.map((patient) => (
                <TableRow key={patient._id}>
                  <TableCell padding="checkbox">
                    <Checkbox
                      checked={selectedPatients.has(patient._id)}
                      onChange={() => handleSelectOne(patient._id)}
                      color="primary"
                    />
                  </TableCell>
                  <TableCell>{patient.pSalutation}. {patient.pName}</TableCell>
                  <TableCell>{patient.pGender}</TableCell>
                  <TableCell>{patient.pNum}</TableCell>
                  <TableCell>{patient.pEmail}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          rowsPerPageOptions={[10, 25, 50]}
          component="div"
          count={filteredPatients.length}
          rowsPerPage={rowsPerPage}
          page={page}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
        />

        <Button
          variant="contained"
          color="primary"
          onClick={handleSendMessages}
          style={{ marginTop: '20px' }}
        >
          Send Discount Messages
        </Button>
      </div>

      <Modal show={showConfirmation} onHide={handleCancelSend}>
        <Modal.Header closeButton>
          <Modal.Title>Confirm Sending Messages</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <TextField
            label="Message"
            variant="outlined"
            fullWidth
            multiline
            rows={4}
            value={message}
            onChange={(e) => setMessage(e.target.value)}
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCancelSend}>
            Cancel
          </Button>
          <Button variant="danger" onClick={handleConfirmSend}>
            {isSendingWhatsapp ? 'Sending...' : 'Send'}
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
};

export default PatientPromotion;
