import React from 'react';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Button from '@mui/material/Button';
import { NavLink, useLocation } from 'react-router-dom';

const CollectionNav = () => {
  const location = useLocation();

  const isActive = (path) => {
    return location.pathname === path;
  };

  // Common button styles
  const buttonStyles = (path) => ({
    textDecoration: isActive(path) ? 'underline' : 'none',
    fontWeight: isActive(path) ? 'bold' : 'normal',
    whiteSpace: 'nowrap',
    minWidth: 'unset',
    padding: '6px 10px',
    fontSize: '0.875rem'
  });

  return (
    <div className='container'>
      <AppBar position="static" style={{ 
        backgroundColor: '#8F00FF', 
        color: 'white', 
        border: 'none',
        boxShadow: 'none'
      }}>
        <Toolbar style={{ 
          overflowX: 'auto', 
          flexWrap: 'nowrap',
          gap: '8px',
          padding: '0 8px',
          minHeight: '64px' // Ensure consistent toolbar height
        }}>
          <Button 
            color="inherit" 
            component={NavLink} 
            to="/dailyCollection"
            style={buttonStyles('/dailyCollection')}
          >
            Daily Collection
          </Button>
          <Button 
            color="inherit" 
            component={NavLink} 
            to="/monthlyCollection"
            style={buttonStyles('/monthlyCollection')}
          >
            Monthly Collection
          </Button>
          <Button 
            color="inherit" 
            component={NavLink} 
            to="/dueReport"
            style={buttonStyles('/dueReport')}
          >
            Due Report
          </Button>
          <Button 
            color="inherit" 
            component={NavLink} 
            to="/regReport"
            style={buttonStyles('/regReport')}
          >
            Registration Report
          </Button>
          <Button 
            color="inherit" 
            component={NavLink} 
            to="/doctorWise"
            style={buttonStyles('/doctorWise')}
          >
            DoctorWise Report
          </Button>
          <Button 
            color="inherit" 
            component={NavLink} 
            to="/deptWise"
            style={buttonStyles('/deptWise')}
          >
            DeptWise Report
          </Button>
        </Toolbar>
      </AppBar>
    </div>
  );
}

export default CollectionNav;