// export default DueReport

import React, { useEffect, useState } from 'react';
import axios from 'axios';
import DatePicker from 'react-datepicker';
import {
    Table,
    TableContainer,
    TableHead,
    TableRow,
    TableCell,
    TableBody,
    Paper,
    Grid,
    TablePagination,
} from '@mui/material';
import 'react-datepicker/dist/react-datepicker.css';
import CollectionNav from './CollectionNav';

const DueReport = () => {
    const [dueCollectionData, setDueCollectionData] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [selectedMonth, setSelectedMonth] = useState(new Date());

    const [page, setPage] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(8);

    useEffect(() => {
        const formattedMonth = selectedMonth.toISOString().split('T')[0];
        const apiBaseUrl = process.env.REACT_APP_API_KEY;

        axios
            .get(`${apiBaseUrl}/auth/monthlydueCollection/${formattedMonth}`)
            .then((response) => {
                setDueCollectionData(response.data);
                setIsLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching monthly collection data:', error);
                setIsLoading(false);
            });
    }, [selectedMonth]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage);
    };

    const handleChangeRowsPerPage = (event) => {
        setRowsPerPage(parseInt(event.target.value, 10));
        setPage(0);
    };

    return (
        <div className="container">
            <CollectionNav />
            <h5 style={{ textAlign: 'center' }}>Due Report</h5>
            <DatePicker
                selected={selectedMonth}
                onChange={(date) => setSelectedMonth(date)}
                dateFormat="yyyy-MM"
                showMonthYearPicker
            />

            <Grid container spacing={2} style={{ marginTop: '20px' }}>
                <Grid item xs={3}>
                    <Paper
                        elevation={3}
                        style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white' }}
                    >
                        <strong>Number of Bills</strong>
                        <br />
                        {dueCollectionData.length}
                    </Paper>
                </Grid>
                <Grid item xs={3}>
                    <Paper
                        elevation={3}
                        style={{ padding: '10px', textAlign: 'center', backgroundColor: '#8F00FF', color: 'white' }}
                    >
                        <strong>Due Pending</strong>
                        <br />
                        {dueCollectionData.reduce((total, item) => total + item.amountDue, 0)}
                    </Paper>
                </Grid>
            </Grid>

            {isLoading ? (
                // <p>Loading...</p>
                <img
                    src={require('../../assets/images/loading.gif')}
                    alt="bb"
                    style={{ width: '100px', height: '100px' }}
                />
            ) : (
                <div>
                    <TableContainer component={Paper}>
                        <Table>
                            <TableHead>
                                <TableRow>
                                    <TableCell><strong>Date</strong></TableCell>
                                    <TableCell><strong>Bill ID</strong></TableCell>
                                    <TableCell><strong>Patient Name</strong></TableCell>
                                    <TableCell><strong>Doctor</strong></TableCell>
                                    <TableCell><strong>Due Amount</strong></TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {dueCollectionData
                                    .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                                    .map((item) => (
                                        <TableRow key={item.id}>
                                            <TableCell>{item.createdAt}</TableCell>
                                            <TableCell>{item.billId}</TableCell>
                                            <TableCell>{item.refId.pSalutation}. {item.refId.pName}</TableCell>
                                            <TableCell>{item.doctorName.drName}</TableCell>
                                            <TableCell>{item.amountDue}</TableCell>
                                        </TableRow>
                                    ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                    <TablePagination
                        rowsPerPageOptions={[8, 16, 24]}
                        component="div"
                        count={dueCollectionData.length}
                        rowsPerPage={rowsPerPage}
                        page={page}
                        onPageChange={handleChangePage}
                        onRowsPerPageChange={handleChangeRowsPerPage}
                    />
                </div>
            )}
        </div>
    );
};

export default DueReport;
