import React, { useState, useEffect} from 'react';
import { TextField, Button, Grid } from '@mui/material';
import { useParams } from 'react-router-dom';
import { toast } from 'react-toastify';
import axios from 'axios';

const UpdateTest = () => {


    const { testId } = useParams();


    const [formData, setFormData] = useState({
        name: '',
        category: '',
        method: '',
        sample: '',
        units: '',
        parameters: '',
        comments: '',
        reference_range: '',
        fees: '',
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData((prevData) => ({
            ...prevData,
            [name]: value
        }));
    };


    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.get(`${apiBaseUrl}/auth/findtestByid/${testId}`)
            .then(response => {
                setFormData(response.data);
            })
            .catch(error => {
                console.error('Error fetching doctor details:', error);
            });
    }, [testId]);


    const handleSubmit = (e) => {

        e.preventDefault(); // Prevent default form submission behavior


        // Here, you can collect all the data and submit it
        const updatedData = formData;

        console.log('Submitted Data:', updatedData);

        // Assuming you have an API endpoint for submission
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.put(`${apiBaseUrl}/auth/update-test/${testId}`, updatedData)
            .then(response => {
                toast.success('Test updated successfully'); // Display success message
                console.log('Submission successful:', response.data);
                // Clear the data after successful submission
                setFormData({
                    name: '',
                    category: '',
                    method: '',
                    sample: '',
                    units: '',
                    parameters: '',
                    comments: '',
                    reference_range: '',
                    fees: '',
                });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    }



    return (
        <>
            <div className='container'>
        <h5 style={{ textAlign: 'left' }}>Update Test &rarr;</h5>
                <form onSubmit={handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Category"
                                variant="outlined"
                                name="category"
                                value={formData.category}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Name"
                                variant="outlined"
                                name="name"
                                value={formData.name}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Cost"
                                variant="outlined"
                                name="fees"
                                value={formData.fees}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Method"
                                variant="outlined"
                                name="method"
                                value={formData.method
                                }
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Sample"
                                variant="outlined"
                                name="sample"
                                value={formData.sample}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Units"
                                variant="outlined"
                                name="units"
                                value={formData.units}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>
                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Parameters"
                                variant="outlined"
                                name="parameters"
                                value={formData.parameters}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Test Comments"
                                variant="outlined"
                                name="comments"
                                value={formData.comments}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={3} xs={6}>
                            <TextField
                                label="Reference Range"
                                variant="outlined"
                                name="reference_range"
                                value={formData.reference_range}
                                onChange={handleChange}
                                fullWidth
                            />
                        </Grid>

                        <Grid item sm={12} xs={12}>
                            <Button type="submit" variant="contained" color="primary" style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>
                                Update Test
                            </Button>
                        </Grid>
                    </Grid>
                </form>
            </div>
        </>
    );
};

export default UpdateTest;
