import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { toast } from 'react-toastify';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';
import { Button } from 'react-bootstrap';
import { FormControl, FormGroup, Grid, FormControlLabel, Checkbox, Autocomplete, TextField, MenuItem, Input, ListItemText, InputLabel, Select, Chip } from '@mui/material';


const UpdateGroupTest = () => {

    const { groupId } = useParams();

    const [loading, setLoading] = useState(true);
    const [availableTests, setAvailableTests] = useState([]);
    const [selectedTests, setSelectedTests] = useState([]);
    const [filteredTests, setFilteredTests] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');



    const [groupTest, setGroupTest] = useState({
        groupCategory: '',
        groupName: '',
        groupPrice: 0,
        testFields: [],
    });

    useEffect(() => {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.get(`${apiBaseUrl}/auth/tests`)
            .then(response => {
                setAvailableTests(response.data);
            })
            .catch(error => {
                console.error('Error fetching available tests:', error);
            });
    }, []);

    useEffect(() => {
        // Filter available tests based on search query
        const filtered = availableTests.filter(test =>
            test.name.toLowerCase().includes(searchQuery.toLowerCase())
        );
        setFilteredTests(filtered);
    }, [searchQuery, availableTests]);

    useEffect(() => {
        // Fetch the existing group test data and populate the state
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.get(`${apiBaseUrl}/auth/groupfindByidTest/${groupId}`)
            .then(response => {
                setGroupTest(response.data);
                setLoading(false); // Set loading to false after data is fetched
            })
            .catch(error => {
                console.error('Error fetching group test:', error);
                setLoading(false); // Set loading to false even if there's an error
            });
    }, [groupId]);


    const handleInputChange = (e) => {
        const { name, value } = e.target;
        const newValue = name === 'groupPrice' ? parseFloat(value) : value;
        setGroupTest({ ...groupTest, [name]: newValue });
    };



    const handleRemoveTestField = (index) => {
        const updatedTestFields = [...groupTest.testFields];
        updatedTestFields.splice(index, 1);
        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    const handleGroupTestCreation = (e) => {

        e.preventDefault(); // Prevent default form submission behavior


        // Create the group test object with the gathered information
        const updatedGroupTest = {
            groupCategory: groupTest.groupCategory,
            groupName: groupTest.groupName,
            groupPrice: groupTest.groupPrice,
            // testFields : groupTest.testFields
            testFields: groupTest.testFields.map(testField => {
                const { _id, ...rest } = testField;
                return rest;
            })
        };

        // const testFields = selectedTests.map((test) => [test.id, test.name]);
        const selectedTestsData = selectedTests.map((test) => ({
            testId: test._id,
            testName: test.name,
        }));

        const groupTestDetails = {
            updatedGroupTest,
            selectedTestsData,
        };

        console.log(groupTestDetails);

        // Assuming you have an API endpoint for submission
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.put(`${apiBaseUrl}/auth/update-groupTest/${groupId}`, groupTestDetails)
            .then(response => {
                toast.success('Updated successfully'); // Display success message
                // console.log('Submission successful:', response.data);
                // Clear the data after successful submission
                setGroupTest({
                    groupName: '',
                    groupPrice: '',
                    groupCategory: ''
                });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    };


    const handleDragEnd = (result) => {
        if (!result.destination) return; // No valid drop target

        const updatedTestFields = [...groupTest.testFields];
        const [movedItem] = updatedTestFields.splice(result.source.index, 1);
        updatedTestFields.splice(result.destination.index, 0, movedItem);

        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    const moveItemUp = (index) => {
        if (index === 0) return; // Can't move the first item up

        const updatedTestFields = [...groupTest.testFields];
        const movedItem = updatedTestFields.splice(index, 1)[0];
        updatedTestFields.splice(index - 1, 0, movedItem);

        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    const moveItemDown = (index) => {
        if (index === groupTest.testFields.length - 1) return; // Can't move the last item down

        const updatedTestFields = [...groupTest.testFields];
        const movedItem = updatedTestFields.splice(index, 1)[0];
        updatedTestFields.splice(index + 1, 0, movedItem);

        setGroupTest({ ...groupTest, testFields: updatedTestFields });
    };

    return (
        <div className='container'>
            {/* <h3>Update Group Test</h3> */}

            {loading ? (
                // Show image or any other loading indicator
                <img
                    src={require('../../assets/images/loading.gif')}
                    alt="bb"
                    style={{ width: '100px', height: '100px' }}
                />
            ) : (
                <>
                    <h5 style={{ textAlign: 'left' }}>Update Group &rarr;</h5>

                    {/* <form > */}
                    <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                        <Grid item xs={12}>
                            <TextField
                                label="Group Test Category"
                                variant="outlined"
                                name="groupCategory"
                                required
                                fullWidth
                                value={groupTest.groupCategory}
                                onChange={handleInputChange}
                            />
                        </Grid>
                    </Grid>

                    <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                        <Grid item xs={12}>
                            <TextField
                                label="Group Test Name"
                                variant="outlined"
                                name="groupName"
                                required
                                fullWidth
                                value={groupTest.groupName}
                                onChange={handleInputChange}
                            />
                        </Grid>
                    </Grid>

                    <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                        <Grid item xs={12}>
                            <TextField
                                label="Price"
                                variant="outlined"
                                name="groupPrice"
                                required
                                fullWidth
                                value={groupTest.groupPrice}
                                onChange={handleInputChange}
                            />
                        </Grid>
                    </Grid>

                    <Autocomplete
                        multiple
                        id="test-select"
                        options={availableTests}
                        getOptionLabel={(option) => option.name}
                        value={selectedTests}
                        onChange={(event, newValue) => setSelectedTests(newValue)}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                label="Search Tests"
                                variant="outlined"
                            />
                        )}
                    />

                    <div>
                        <h5>Test Fields</h5>
                        <DragDropContext onDragEnd={handleDragEnd}>
                            <Droppable droppableId="testFields">
                                {(provided) => (
                                    <div {...provided.droppableProps} ref={provided.innerRef}>
                                        {groupTest.testFields && groupTest.testFields.map((testField, index) => (
                                            <Draggable
                                                key={testField.testName}
                                                draggableId={testField.testName}
                                                index={index}
                                            >
                                                {(provided) => (
                                                    <div
                                                        {...provided.draggableProps}
                                                        {...provided.dragHandleProps}
                                                        ref={provided.innerRef}
                                                        style={{
                                                            border: '1px solid lightgray',
                                                            padding: '8px',
                                                            marginBottom: '8px',
                                                            backgroundColor: 'white',
                                                            position: 'relative', // Make the container relative
                                                        }}
                                                    >
                                                        <div style={{ position: 'absolute', top: '0', right: '0' }}>
                                                            <Button
                                                                style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}
                                                                onClick={() => moveItemUp(index)}
                                                                disabled={index === 0}
                                                            >
                                                                Up
                                                            </Button>
                                                            <Button
                                                                style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}
                                                                onClick={() => moveItemDown(index)}
                                                                disabled={index === groupTest.testFields.length - 1}
                                                            >
                                                                Down
                                                            </Button>
                                                            <Button
                                                                style={{ backgroundColor: 'red', color: 'white', border: 'none' }}
                                                                onClick={() => handleRemoveTestField(index)}
                                                            >
                                                                Delete
                                                            </Button>
                                                        </div>
                                                        {testField.testName}
                                                        <TextField
                                                            label="Sub Category"
                                                            variant="outlined"
                                                            fullWidth
                                                            value={testField.subCat}
                                                            onChange={(e) => {
                                                                const updatedTestFields = [...groupTest.testFields];
                                                                updatedTestFields[index].subCat = e.target.value;
                                                                setGroupTest({ ...groupTest, testFields: updatedTestFields });
                                                            }}
                                                        />
                                                    </div>
                                                )}
                                            </Draggable>
                                        ))}
                                        {provided.placeholder}
                                    </div>
                                )}
                            </Droppable>
                        </DragDropContext>
                    </div>
                    <Button onClick={handleGroupTestCreation} style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>Update Group Test</Button>
                    {/* </form> */}
                </>
            )}
        </div>
    );
};

export default UpdateGroupTest;
