import React, { useState, useEffect } from 'react';
import { TextField, Button, Grid, Container, Typography, Card, CardContent } from '@mui/material';
import axios from 'axios';
import jsPDF from 'jspdf';
import 'jspdf-autotable';

const MostConductedTests = () => {
  const [fromDate, setFromDate] = useState(new Date().toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [tests, setTests] = useState([]);

  const fetchTests = async () => {
    try {
      const apiBaseUrl = process.env.REACT_APP_API_KEY;
      const response = await axios.get(`${apiBaseUrl}/auth/most-conducted-tests`, {
        params: { fromDate, toDate }
      });
      setTests(response.data);
    } catch (error) {
      console.error('Error fetching tests:', error);
    }
  };

  useEffect(() => {
    if (fromDate && toDate) {
      fetchTests();
    }
  }, [fromDate, toDate]);

  const handleDateChange = (setter) => (event) => {
    setter(event.target.value);
  };

  const downloadPDF = () => {
    const doc = new jsPDF();
    
    // Add heading
    doc.setFontSize(18);
    doc.text('Most Conducted Tests', 14, 22);
    
    // Add date range
    doc.setFontSize(12);
    doc.text(`From Date: ${fromDate}`, 14, 32);
    doc.text(`To Date: ${toDate}`, 14, 42);
    
    // Add table with test data
    const tableData = tests.map(test => [test.name, test.type, test.conductCount]);
    doc.autoTable({
      startY: 52,
      head: [['Test Name', 'Type', 'Conduct Count']],
      body: tableData,
    });
    
    doc.save('Most_Conducted_Tests.pdf');
  };

  return (
    <Container>
      <Typography variant="h5" gutterBottom>
        Most Conducted Tests &rarr;
      </Typography>
      <Grid container spacing={3}>
        <Grid item xs={6}>
          <TextField
            type="date"
            label="From Date"
            value={fromDate}
            onChange={handleDateChange(setFromDate)}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={6}>
          <TextField
            type="date"
            label="To Date"
            value={toDate}
            onChange={handleDateChange(setToDate)}
            fullWidth
            InputLabelProps={{ shrink: true }}
          />
        </Grid>
        <Grid item xs={12}>
          <Button
            variant="contained"
            color="primary"
            onClick={fetchTests}
            disabled={!fromDate || !toDate}
          >
            Fetch Tests
          </Button>
          <Button
            variant="contained"
            color="secondary"
            onClick={downloadPDF}
            style={{ marginLeft: '10px' }}
          >
            Download PDF
          </Button>
        </Grid>
      </Grid>
      <Grid container spacing={3} style={{ marginTop: '20px' }}>
        {tests.map((test, index) => (
          <Grid item xs={12} sm={6} md={4} lg={3} key={index}>
            <Card>
              <CardContent>
                <Typography variant="h6" component="div">
                  {test.name}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Conducts: {test.conductCount}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Container>
  );
};

export default MostConductedTests;
