import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { Button } from 'react-bootstrap';
import { FormControl, FormGroup, Grid, FormControlLabel, Checkbox, Autocomplete, TextField, MenuItem, Input, ListItemText, InputLabel, Select, Chip } from '@mui/material';

const CreateProfile = () => {
    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    const [availableTests, setAvailableTests] = useState([]);
    const [selectedTests, setSelectedTests] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [groupDetails, setGroupDetails] = useState({
        profileName: '',
        profilePrice: '',
    });
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredTests, setFilteredTests] = useState([]);

    const [loadingTests, setLoadingTests] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchTests = async () => {
            try {
                const [testsResponse, groupTestsResponse] = await Promise.all([
                    axios.get(`${apiBaseUrl}/auth/tests`),
                    axios.get(`${apiBaseUrl}/auth/getGroupTestList`)
                ]);

                setAvailableTests([
                    ...testsResponse.data.map(test => ({ ...test, type: 'Test' })),
                    ...groupTestsResponse.data.map(test => ({ ...test, type: 'Group' }))
                ]);

                setLoadingTests(false);
            } catch (error) {
                console.error('Error fetching tests:', error);
                setError('Error fetching tests. Please try again.');
                setLoadingTests(false);
            }
        };

        fetchTests();
    }, []);

    useEffect(() => {
        // Filter available tests based on search query
        const filtered = availableTests.filter(test =>
            (test.name && test.name.toLowerCase().includes(searchQuery.toLowerCase())) ||
            (test.groupName && test.groupName.toLowerCase().includes(searchQuery.toLowerCase()))
        );
        setFilteredTests(filtered);
    }, [searchQuery, availableTests]);




    const handleGroupDetailsChange = (e) => {
        const { name, value } = e.target;
        setGroupDetails(prevDetails => ({
            ...prevDetails,
            [name]: value
        }));
    };

    const handleGroupTestCreation = (e) => {

        e.preventDefault(); // Prevent default form submission behavior

        // const testFields = selectedTests.map((test) => [test.id, test.name]);
        const testFields = selectedTests.map((test) => ({
            testId: test._id,
            testName: test.name || test.groupName,
            type: test.type
        }));


        // Create the group test object with the gathered information
        const groupTest = {
            // groupCategory: groupDetails.groupCategory,
            profileName: groupDetails.profileName,
            profilePrice: groupDetails.profilePrice,
            testFields,
        };

        // Assuming you have an API endpoint for submission
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios.post(`${apiBaseUrl}/auth/create-Profile`, groupTest)
            .then(response => {
                toast.success('Profile Created successfully'); // Display success message
                // console.log('Submission successful:', response.data);
                // Clear the data after successful submission
                setGroupDetails({
                    profileName: '',
                    profilePrice: '',
                    // groupCategory: ''
                });

            })
            .catch(error => {
                console.error('Submission error:', error);
            });

    };

    const handleRemoveTest = (testToRemove) => {
        const updatedSelectedTests = selectedTests.filter((test) => test !== testToRemove);
        setSelectedTests(updatedSelectedTests);
    };


    return (
        <div className='container'>
         <h5 style={{ textAlign: 'left'}}>Create Profile &rarr;</h5>
            <form action="" onSubmit={handleGroupTestCreation}>

                <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                    <Grid item xs={12}>
                        <TextField
                            label="Package Name"
                            variant="outlined"
                            name="profileName"
                            required
                            fullWidth
                            value={groupDetails.profileName}
                            onChange={handleGroupDetailsChange}
                        />
                    </Grid>
                </Grid>

                <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                    <Grid item xs={12}>
                        <TextField
                            label="Package Price"
                            variant="outlined"
                            name="profilePrice"
                            required
                            fullWidth
                            value={groupDetails.profilePrice}
                            onChange={handleGroupDetailsChange}
                        />
                    </Grid>
                </Grid>

                <Autocomplete
                    multiple
                    id="test-select"
                    options={availableTests}
                    // getOptionLabel={(option) => option.name}
                    getOptionLabel={(option) => (option.name || option.groupName || '')}
                    value={selectedTests} // Set the initial value to selectedTests
                    onChange={(event, newValue) => setSelectedTests(newValue)}
                    renderInput={(params) => (
                        <TextField
                            style={{ marginBottom: '30px' }}
                            {...params}
                            type="text"
                            label="Search for tests"
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                        />
                    )}
                />


                {selectedTests.length > 0 && (
                    <div className="selected-tests">
                        <h4>Selected Tests:</h4>
                        <ul>
                            {selectedTests.map((test) => (
                                <li key={test._id}>
                                    {test.type === 'Test' ? (
                                        `${test.name} - Price: $${test.fees}`
                                    ) : (
                                        `${test.groupName} - Price: $${test.groupPrice}`
                                    )}
                                    <Button
                                        variant="contained"
                                        color="secondary"
                                        onClick={() => handleRemoveTest(test)}
                                    >
                                        Remove
                                    </Button>
                                </li>
                            ))}
                        </ul>
                    </div>
                )}

                <Button type="submit" >Create Profile</Button>
            </form>
        </div>
    );

};

export default CreateProfile;
