import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Typography,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { Button } from 'react-bootstrap';
import { toast } from 'react-toastify';
import RemoveIcon from '@mui/icons-material/Remove';

const FeesMaster = () => {

  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  const departmentInputRef = React.createRef();

  // Existing state variables
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(3); // Add this line

  // Add this line
  const [displayedFees, setDisplayedFees] = useState([]);


  const [inputs, setInputs] = useState({
    txtDepartment: '',
    department: '',
    category: '',
    feesName: '',
    opFees: 0,
    ipFees: 0,
    filterDept: 'All',
  });

  const [departments, setDepartments] = useState([]);
  const [feesList, setFeesList] = useState([]);
  const [deptAddMode, setDeptAddMode] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [selectedFilter, setSelectedFilter] = useState('All');

  useEffect(() => {
    fetchDepartments();
    fetchFeesList();
  }, []);

  const fetchDepartments = async () => {
    try {
      const response = await axios.get(`${apiBaseUrl}/auth/getDepartments`);
      setDepartments(response.data.departments.map(dep => dep.department));
    } catch (error) {
      console.error('Error fetching departments:', error);
    }
  };


  const fetchFeesList = async () => {
    try {
      const response = await axios.get(`${apiBaseUrl}/auth/feesList`);
      setFeesList(response.data.feesList);
      setDisplayedFees(response.data.feesList);
    } catch (error) {
      console.error('Error fetching fees list:', error);
    }
  };

  const AddDepartment = async () => {
    try {
      // Extract the department name from the input field using the ref
      const departmentName = departmentInputRef.current.value;

      const apiBaseUrl = process.env.REACT_APP_API_KEY;

      const response = await axios.post(`${apiBaseUrl}/auth/addDepartment`, {
        department: departmentName,
      });
      // setDepartments(response.data.departments);
      setDepartments(response.data.departments.map(dep => dep.department));
      setDeptAddMode(false);
      setInputs({ ...inputs, txtDepartment: '' });
      toast.success('Department Added Successfully');
    } catch (error) {
      console.error('Error adding department:', error);
    }
  };

  const RemoveDepartment = async () => {
    try {
      const response = await axios.delete(`${apiBaseUrl}/auth/removeDepartment`, {
        data: { department: inputs.department },
      });
      setDepartments(response.data.departments);
      setInputs({ ...inputs, department: '' });
    } catch (error) {
      console.error('Error removing department:', error);
    }
  };

  const SaveFees = async () => {
    try {
      const response = await axios.post(`${apiBaseUrl}/auth/saveFees`, {
        department: inputs.department,
        category: inputs.category,
        feesName: inputs.feesName,
        opFees: inputs.opFees,
        ipFees: inputs.ipFees,
      });
      setFeesList(response.data.feesList);
      setDisplayedFees(response.data.feesList);

      setIsSaving(false);
      setInputs({
        ...inputs,
        category: '',
        feesName: '',
        opFees: 0,
        ipFees: 0,
      });
      toast.success('Saved Successfully');
    } catch (error) {
      console.error('Error saving fees:', error);
    }
  };


  // const UpdateFees = async () => {
  //   try {
  //     // Find the selected fee in the feesList
  //     const selectedFee = feesList.find((fee) => fee.department === inputs.department);

  //     if (!selectedFee) {
  //       console.error('Selected fee not found in feesList');
  //       return;
  //     }

  //     const response = await axios.put(`${apiBaseUrl}/auth/updateFees/${selectedFee._id}`, {
  //       department: inputs.department,
  //       category: inputs.category,
  //       feesName: inputs.feesName,
  //       opFees: inputs.opFees,
  //       ipFees: inputs.ipFees,
  //     });

  //     // Update feesList by mapping over the previous list and replacing the updated fee
  //     setFeesList((prevFeesList) =>
  //       prevFeesList.map((fee) => (fee._id === selectedFee._id ? response.data.updatedFee : fee))
  //     );

  //     // Update displayedFees in the same way
  //     setDisplayedFees((prevFeesList) =>
  //       prevFeesList.map((fee) => (fee._id === selectedFee._id ? response.data.updatedFee : fee))
  //     );

  //     setIsUpdating(false);
  //     setEditMode(false);
  //     setInputs({
  //       ...inputs,
  //       category: '',
  //       feesName: '',
  //       opFees: 0,
  //       ipFees: 0,
  //     });
  //   } catch (error) {
  //     console.error('Error updating fees:', error);
  //   }
  // };


  const UpdateFees = async () => {
    try {
      const response = await axios.put(`${apiBaseUrl}/auth/updateFees/${inputs._id}`, {
        department: inputs.department,
        category: inputs.category,
        feesName: inputs.feesName,
        opFees: inputs.opFees,
        ipFees: inputs.ipFees,
      });

      // Update feesList by mapping over the previous list and replacing the updated fee
      setFeesList((prevFeesList) =>
        prevFeesList.map((fee) => (fee._id === inputs._id ? response.data.updatedFee : fee))
      );

      // Update displayedFees by mapping over feesList
      setDisplayedFees((prevFeesList) =>
        prevFeesList.map((fee) => (fee._id === inputs._id ? response.data.updatedFee : fee))
      );

      setIsUpdating(false);
      setEditMode(false);
      setInputs({
        ...inputs,
        category: '',
        feesName: '',
        opFees: 0,
        ipFees: 0,
      });
      toast.success('Updated Successfully');
    } catch (error) {
      console.error('Error updating fees:', error);
    }
  };

  const ClearPage = () => {
    setDeptAddMode(false);
    setEditMode(false);
    setInputs({
      txtDepartment: '',
      department: '',
      category: '',
      feesName: '',
      opFees: '',
      ipFees: '',
      filterDept: 'All',
    });
  };

  const FilterDatas = async () => {
    try {
      let filteredFeesList;

      if (inputs.filterDept === 'All') {
        // If "All" is selected, display all items
        filteredFeesList = [...feesList];
      } else {
        // Otherwise, filter by the selected department
        const response = await axios.get(`${apiBaseUrl}/auth/filterFees/${inputs.filterDept}`);
        filteredFeesList = response.data.filteredFeesList;
      }

      setFeesList(filteredFeesList);
      setDisplayedFees(filteredFeesList);
    } catch (error) {
      console.error('Error filtering fees:', error);
    }
  };


  const GetUpdateValues = (selectedFee) => {
    setInputs({
      ...inputs,
      _id: selectedFee._id,
      department: selectedFee.department,
      category: selectedFee.category,
      feesName: selectedFee.feesName,
      opFees: selectedFee.opFees,
      ipFees: selectedFee.ipFees,
    });
    setEditMode(true);
  };

  const DeleteFees = async (id, rowIndex) => {
    try {
      const response = await axios.delete(`${apiBaseUrl}/auth/deleteFees/${id}`);
      setFeesList(response.data.updatedFeesList);
      setDisplayedFees(response.data.updatedFeesList);
    } catch (error) {
      console.error('Error deleting fees:', error);
    }
  };

  return (
    <div className="container">
      <h5 style={{ textAlign: 'left' }}>Fees Master &rarr;</h5>
      <Paper elevation={3} className="background-All pb-2 pl-2 pr-2">
        <div className="row">
          <div className="col-lg-8 col-md-8 col-sm-10 col-12 offset-md-2 offset-sm-1 background-All pt-2 pb-2">
            {/* Department Entry */}
            <div className="row">
              <div className="col-4 col-lg-2">
                <InputLabel className="badge">Department</InputLabel>
              </div>
              <div className="col-lg-6 col-5">
                <div style={{ display: 'flex', alignItems: 'center' }}>
                  {deptAddMode ? (
                    <>
                      <TextField
                        inputRef={departmentInputRef} // Add the ref to the input field
                        className="form-control form-control-sm"
                        value={inputs.txtDepartment}
                        onChange={(e) => setInputs({ ...inputs, txtDepartment: e.target.value })}
                        placeholder="Enter Department"
                        onKeyDown={(e) => {
                          // Check if the pressed key is Enter
                          if (e.key === 'Enter') {
                            AddDepartment();
                          }
                        }}
                      />
                      <IconButton onClick={AddDepartment} size="small" color="success">
                        <AddIcon />
                      </IconButton>
                    </>
                  ) : (
                    <>
                      <Select
                        className="form-control form-control-sm"
                        value={inputs.department}
                        onChange={(e) => setInputs({ ...inputs, department: e.target.value })}
                      >
                        <MenuItem value="All">All</MenuItem>
                        {departments.map((department) => (
                          <MenuItem key={department} value={department}>
                            {department}
                          </MenuItem>
                        ))}
                      </Select>
                      <IconButton onClick={RemoveDepartment} size="small" color="error">
                        <RemoveIcon />
                      </IconButton>
                      <IconButton onClick={() => setDeptAddMode(true)} size="small" color="success">
                        <AddIcon />
                      </IconButton>
                    </>
                  )}
                </div>
              </div>
            </div>

            {/* Category */}
            <div className="row">
              <div className="col-4 col-lg-2">
                <InputLabel className="badge">Category</InputLabel>
              </div>
              <div className="col-8 col-lg-6">
                <TextField
                  className="form-control form-control-sm"
                  autoComplete="off"
                  value={inputs.category}
                  onChange={(e) => setInputs({ ...inputs, category: e.target.value })}
                />
              </div>
            </div>

            {/* Fees Name */}
            <div className="row pt-1">
              <div className="col-4 col-lg-2">
                <InputLabel className="badge">Fees Name&nbsp;<span className="fa fa-asterisk" style={{ fontSize: '6px', color: 'Red' }}></span></InputLabel>
              </div>
              <div className="col-8 col-lg-6">
                <TextField
                  className="form-control form-control-sm"
                  autoComplete="off"
                  value={inputs.feesName}
                  onChange={(e) => setInputs({ ...inputs, feesName: e.target.value })}
                />
              </div>
            </div>

            {/* OP and IP Fees */}
            <div className="row pt-1">
              <div className="col-4 col-lg-2">
                <InputLabel className="badge">OP Fees</InputLabel>
              </div>
              <div className="col-8 col-lg-2">
                <TextField
                  type="number"
                  inputMode="numeric"
                  className="form-control form-control-sm"
                  autoComplete="off"
                  value={inputs.opFees}
                  onChange={(e) => setInputs({ ...inputs, opFees: e.target.value })}
                />
              </div>
              <div className="col-4 col-lg-2">
                <InputLabel className="badge">IP Fees</InputLabel>
              </div>
              <div className="col-8 col-lg-2 mt-lg-0 mt-1">
                <TextField
                  type="number"
                  inputMode="numeric"
                  className="form-control form-control-sm"
                  autoComplete="off"
                  value={inputs.ipFees}
                  onChange={(e) => setInputs({ ...inputs, ipFees: e.target.value })}
                />
              </div>
            </div>

            {/* Save, Update, Clear Buttons */}
            <div className="row pt-2">
              <div className="col text-center">
                {!editMode ? (
                  <Button
                    className="btn btn-success btn-sm"
                    onClick={SaveFees}
                    disabled={isSaving}
                  >
                    {isSaving ? 'Saving...' : 'Save'}
                  </Button>
                ) : (
                  <Button
                    className="btn btn-success btn-sm"
                    onClick={UpdateFees}
                    disabled={isUpdating}
                  >
                    {isUpdating ? 'Updating...' : 'Update'}
                  </Button>
                )}
                <Button className="btn btn-danger btn-sm" onClick={ClearPage}>
                  Clear
                </Button>
              </div>
              <div className="col-lg-3"></div>
            </div>
          </div>
        </div>

        {/* Fees Details */}
        <div className="row pt-3">
          <div className="col-12 bg-info text-light text-center">
            <Typography>Fees Details</Typography>
          </div>
        </div>

        {/* Filter Section */}
        <div className="row pt-3 background-All">
          <div className="col-12">
            <div className="row">
              <div className="col-3 col-lg-1">
                <InputLabel className="badge mt-2"><strong>Department :</strong> </InputLabel>
              </div>
              <div className="col-8 col-lg-4">
                <Select
                  className="form-control form-control-sm mt-2"
                  value={inputs.filterDept}
                  onChange={(e) => {
                    setInputs({ ...inputs, filterDept: e.target.value });
                    // Trigger the filter function here
                    // FilterDatas();
                  }}
                >
                  <MenuItem value="All">All</MenuItem>
                  {departments.map((department) => (
                    <MenuItem key={department} value={department}>
                      {department}
                    </MenuItem>
                  ))}
                </Select>
              </div>
              <div className="col">
                <Button className="btn btn-sm btn-secondary mt-2" style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }} onClick={FilterDatas}>
                  Filter
                </Button>
              </div>
            </div>
          </div>
        </div>

        {/* Fees Table */}
        <div className="row background-All">
          <div className="col-12">
            <TableContainer component={Paper} style={{ maxHeight: '250px' }}>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell><strong>Department</strong></TableCell>
                    <TableCell><strong>Category</strong></TableCell>
                    <TableCell><strong>Fees Type</strong></TableCell>
                    <TableCell><strong>OP Fees</strong></TableCell>
                    <TableCell><strong>IP Fees</strong></TableCell>
                    <TableCell></TableCell>
                    <TableCell></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {(rowsPerPage > 0
                    ? displayedFees.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                    : displayedFees
                  ).map((fee, rowIndex) => (
                    <TableRow key={fee._id} hidden={selectedFilter !== 'All' && selectedFilter !== fee.department}>
                      <TableCell>{fee.department}</TableCell>
                      <TableCell>{fee.category}</TableCell>
                      <TableCell>{fee.feesName}</TableCell>
                      <TableCell>{fee.opFees.toFixed(2)}</TableCell>
                      <TableCell>{fee.ipFees.toFixed(2)}</TableCell>
                      <TableCell>
                        <Button style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }} onClick={() => GetUpdateValues(fee)}>
                          Edit
                        </Button>
                      </TableCell>
                      <TableCell>
                        <Button style={{ backgroundColor: 'red', color: 'white', border: 'none' }} onClick={() => DeleteFees(fee._id, rowIndex)}>
                          Delete
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            {/* Render TablePagination component */}
            <TablePagination
              rowsPerPageOptions={[3, 5, 10]}  // Customize the available rows per page options
              component="div"
              count={displayedFees.length}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={(e, newPage) => setPage(newPage)}
              onRowsPerPageChange={(e) => {
                setRowsPerPage(parseInt(e.target.value, 10));
                setPage(0);
              }}
            />
          </div>
        </div>
      </Paper>
    </div>
  );
};

export default FeesMaster;
