import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  Table,
  TableContainer,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  TextField,
  Paper,
  IconButton,
  TablePagination,
} from '@mui/material';
import { useNavigate } from 'react-router-dom'; // Import useHistory
import SearchIcon from '@mui/icons-material/Search';

const ReportList = () => {
  const navigate = useNavigate();
  const [bills, setBills] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [loading, setLoading] = useState(true); // Add loading state

  const currentDate = new Date().toISOString().split('T')[0]; // Get current date in "yyyy-MM-dd" format
  const [selectedDate, setSelectedDate] = useState(currentDate);


  useEffect(() => {
    const fetchBills = async () => {
      try {
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        // const response = await axios.get(`${apiBaseUrl}/auth/bills`);
        const response = await axios.get(`${apiBaseUrl}/auth/reports`, {
          params: { date: selectedDate },
        });
        setBills(response.data.bills);
        setLoading(false); // Set loading to false when data is loaded
      } catch (error) {
        console.error('Error fetching bills:', error);
        setLoading(false); // Set loading to false on error
      }
    };

    fetchBills();
  }, [selectedDate]);


  const searchTermLower = searchTerm.toLowerCase();

  const filteredBills = bills.filter((bill) => {
    const billIdString = bill.billId.toString(); // Convert billId to a string
    const pNumString = bill.pNum.toString();
    const pNameLower = bill.pName.toLowerCase();

    return (
      billIdString.includes(searchTerm) || // Use billIdString here
      pNumString.includes(searchTerm) ||
      pNameLower.includes(searchTermLower)
    );
  });


  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleRowClick = (objbillId) => {
    // Navigate to billDetails component with the selected billId
    navigate(`/labResultentry/${objbillId}`);
  };

  return (
    <div className="container">
        <h5 style={{ textAlign: 'left'}}>Reports &rarr;</h5>
      <TextField
        label="Select a Date"
        type="date"
        variant="outlined"
        style={{width:'200px', marginBottom:'15px'}}
        value={selectedDate}
        onChange={(e) => setSelectedDate(e.target.value)}
      />

      <TextField
        label="Search by Report ID, Name, Phone"
        variant="outlined"
        fullWidth
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        InputProps={{
          endAdornment: (
            <IconButton>
              <SearchIcon />
            </IconButton>
          ),
        }}
        style={{ marginBottom: 16 }}
      />

      {loading ? ( // Conditional rendering based on loading state
        // <p>Loading...</p>
        <img
          src={require('../../assets/images/loading.gif')}
          alt="bb"
          style={{ width: '100px', height: '100px' }}
        />
      ) : (
        <TableContainer component={Paper}>
          <Table>
            <TableHead  style={{backgroundColor:'#8F00FF'}}>
              <TableRow>
                <TableCell style={{ color:'white'}}><strong>Bill Date</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Bill ID</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Patient Name</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Phone</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Doctor</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Bill Total</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Amount Paid</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Discount</strong></TableCell>
                <TableCell style={{ color:'white'}}><strong>Due</strong></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredBills
                .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage)
                .map((bill) => (
                  <TableRow
                    key={bill._id}
                    onClick={() => handleRowClick(bill.objbillId)} // Pass the billId to the function
                    style={{ cursor: 'pointer' }}
                  >
                    <TableCell>{bill.billDate}</TableCell>
                    <TableCell>{bill.billId}</TableCell>
                    <TableCell>{bill.pSal}. {bill.pName}</TableCell>
                    <TableCell>{bill.pNum}</TableCell>
                    <TableCell>{bill.drName}</TableCell>
                    <TableCell>{bill.billAmount}</TableCell>
                    <TableCell>{bill.amountPaid}</TableCell>
                    <TableCell>{bill.discountAmount}</TableCell>
                    <TableCell>{bill.amountDue}</TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      <TablePagination
        rowsPerPageOptions={[10, 25, 50]}
        component="div"
        count={filteredBills.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
      />
    </div>
  );
};

export default ReportList;
