import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import { Button } from 'react-bootstrap';
import { TextField, Grid, Autocomplete } from '@mui/material';

const GroupTestCreation = () => {
    const apiBaseUrl = process.env.REACT_APP_API_KEY;

    // State variables
    const [availableTests, setAvailableTests] = useState([]);
    const [selectedTests, setSelectedTests] = useState([]);
    const [groupDetails, setGroupDetails] = useState({
        groupName: '',
        groupPrice: '',
        groupCategory: ''
    });
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredTests, setFilteredTests] = useState([]);

    // Add subcategory field to each selected test
    const handleSubcategoryChange = (testId, subcategory) => {
        const updatedTests = selectedTests.map((test) =>
            test._id === testId ? { ...test, subcategory } : test
        );
        setSelectedTests(updatedTests);
    };

    useEffect(() => {
        axios.get(`${apiBaseUrl}/auth/tests`)
            .then(response => {
                setAvailableTests(response.data);
            })
            .catch(error => {
                console.error('Error fetching available tests:', error);
            });
    }, []);

    useEffect(() => {
        const filtered = availableTests.filter(test =>
            test.name.toLowerCase().includes(searchQuery.toLowerCase())
        );
        setFilteredTests(filtered);
    }, [searchQuery, availableTests]);

    const handleGroupDetailsChange = (e) => {
        const { name, value } = e.target;
        setGroupDetails(prevDetails => ({
            ...prevDetails,
            [name]: value
        }));
    };

    const handleRemoveTest = (test) => {
        const updatedTests = selectedTests.filter(selectedTest => selectedTest !== test);
        setSelectedTests(updatedTests);
    };

    const handleGroupTestCreation = (e) => {
        e.preventDefault();

        const groupTest = {
            groupCategory: groupDetails.groupCategory,
            groupName: groupDetails.groupName,
            groupPrice: groupDetails.groupPrice,
            testFields: selectedTests.map(test => ({
                testId: test._id,
                testName: '',
                subCat : test.subcategory || ''
                // subcategory: test.subcategory || '', // Include subcategory
            }))
        };

        // Make an API call to save the data on the server
        axios.post(`${apiBaseUrl}/auth/create-groupTest`, groupTest)
            .then(response => {
                toast.success('Group Test Created successfully');
                setGroupDetails({
                    groupName: '',
                    groupPrice: '',
                    groupCategory: ''
                });
                setSelectedTests([]);
            })
            .catch(error => {
                console.error('Submission error:', error);
            });
    };

    return (
        <div className='container'>
                    <h5 style={{ textAlign: 'left' }}>Create Group &rarr;</h5>
            <form action="" onSubmit={handleGroupTestCreation}>
                <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                    <Grid item xs={12}>
                        <TextField
                            label="Group Test Category"
                            variant="outlined"
                            name="groupCategory"
                            required
                            fullWidth
                            value={groupDetails.groupCategory}
                            onChange={handleGroupDetailsChange}
                        />
                    </Grid>
                </Grid>

                <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                    <Grid item xs={12}>
                        <TextField
                            label="Group Test Name"
                            variant="outlined"
                            name="groupName"
                            required
                            fullWidth
                            value={groupDetails.groupName}
                            onChange={handleGroupDetailsChange}
                        />
                    </Grid>
                </Grid>

                <Grid container spacing={2} style={{ marginBottom: '16px' }}>
                    <Grid item xs={12}>
                        <TextField
                            label="Price"
                            variant="outlined"
                            name="groupPrice"
                            required
                            fullWidth
                            value={groupDetails.groupPrice}
                            onChange={handleGroupDetailsChange}
                        />
                    </Grid>
                </Grid>

                <Autocomplete
                    multiple
                    id="test-select"
                    options={availableTests}
                    getOptionLabel={(option) => option.name}
                    value={selectedTests}
                    onChange={(event, newValue) => setSelectedTests(newValue)}
                    renderInput={(params) => (
                        <TextField
                            {...params}
                            label="Search Tests"
                            variant="outlined"
                        />
                    )}
                />

                <ul>
                    {selectedTests.map((test) => (
                        <li key={test._id}>
                            {test.name}
                            <TextField
                                label="Subcategory"
                                variant="outlined"
                                value={test.subcategory || ''}
                                onChange={(e) =>
                                    handleSubcategoryChange(test._id, e.target.value)
                                }
                            />
                            <Button
                                style={{
                                    backgroundColor: '#8B0000',
                                    color: 'white',
                                    border: 'none',
                                }}
                                variant="outlined"
                                onClick={() => handleRemoveTest(test)}
                            >
                                Remove
                            </Button>
                        </li>
                    ))}
                </ul>

                <Button type="submit" style={{backgroundColor: '#8F00FF', color: 'white', border: 'none', marginTop: '20px' }}>Create Group Test</Button>
            </form>
        </div>
    );
};

export default GroupTestCreation;
