import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  Typography,
  Box,
  Grid,
  Paper,
  Button,
  Table,
  TableContainer,
  TableHead,
  TableRow,
  TableCell,
  TableBody,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { useNavigate, useParams } from 'react-router-dom';
import { format } from 'date-fns';

const PrescriptionList = () => {
  const { patientId } = useParams();
  const navigate = useNavigate();
  const [bills, setBills] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [isPrescription, setIsPrescription] = useState(false);
  const [selectedDate, setSelectedDate] = useState(null);

  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const apiBaseUrl = process.env.REACT_APP_API_KEY;

  useEffect(() => {
    const fetchBills = async () => {
      try {
        const response = await axios.get(`${apiBaseUrl}/auth/prescriptionsList/${patientId}`);
        setBills(response.data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching bills:', error);
        setLoading(false);
      }
    };

    fetchBills();
  }, [patientId, apiBaseUrl]);

  const numberOfVisits = bills.length;
  const earliestVisitDate = bills.length > 0
    ? format(new Date(Math.min(...bills.map(bill => new Date(bill.createdAt).getTime()))), 'dd-MMM-yyyy')
    : 'N/A';

  const searchTermLower = searchTerm.toLowerCase();
  const filteredBills = bills.filter((bill) => {
    const pNumString = bill.patientId?.pNum?.toString() || '';
    const pNameLower = bill.patientId?.pName?.toLowerCase() || '';
    return (
      pNumString.includes(searchTerm) ||
      pNameLower.includes(searchTermLower)
    );
  });

  const handleNavigate = (objbillId) => {
    navigate(`/newPre/${objbillId}`);
  };

  const handleEmailPrescription = (e, bill) => {
    e.stopPropagation();
    console.log('Email prescription for bill:', bill);
  };

  const handleWhatsAppPrescription = (e, bill) => {
    e.stopPropagation();
    console.log('Send prescription via WhatsApp for bill:', bill);
  };

  const printPrescription = async (e, patientId) => {
    e.stopPropagation();
    setIsPrescription(prevState => ({ ...prevState, [patientId]: true }));
    try {
      const response = await axios.post(
        `${apiBaseUrl}/auth/print-prescriptions/${patientId}`,
        {},
        {
          responseType: 'blob',
          headers: { 'Content-Type': 'application/json' },
        }
      );

      const blob = new Blob([response.data], { type: 'application/pdf' });
      const pdfUrl = URL.createObjectURL(blob);
      window.open(pdfUrl, '_blank');
    } catch (error) {
      console.error('Error printing prescription:', error);
    } finally {
      setIsPrescription(prevState => ({ ...prevState, [patientId]: false }));
    }
  };

  const handleDateClick = (date) => {
    setSelectedDate(date);
    const element = document.getElementById(date);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', height: '100vh' }}>
      {/* Mobile Date Scrollbar */}
      {isMobile && (
        <Box
          sx={{
            width: '100%',
            height: '60px',
            overflowX: 'auto',
            borderBottom: '1px solid #e0e0e0',
            padding: '8px',
            backgroundColor: '#f5f5f5',
            display: 'flex',
            gap: '8px',
          }}
        >
          {filteredBills.map((bill) => {
            const date = format(new Date(bill.createdAt), 'dd-MMM-yyyy');
            return (
              <Box
                key={date}
                sx={{
                  padding: '8px 12px',
                  borderRadius: '4px',
                  backgroundColor: selectedDate === date ? '#8F00FF' : '#e0e0e0',
                  color: selectedDate === date ? 'white' : 'inherit',
                  cursor: 'pointer',
                  flexShrink: 0,
                  '&:hover': {
                    backgroundColor: selectedDate === date ? '#8F00FF' : '#d5d5d5',
                  },
                }}
                onClick={() => handleDateClick(date)}
              >
                <Typography variant="body2">{date}</Typography>
              </Box>
            );
          })}
        </Box>
      )}

      {/* Desktop Date Scrollbar */}
      {!isMobile && (
        <Box
          sx={{
            width: '200px',
            height: '100vh',
            overflowY: 'auto',
            borderRight: '1px solid #e0e0e0',
            padding: '16px',
            backgroundColor: '#f5f5f5',
          }}
        >
          <Typography variant="h6" sx={{ fontWeight: 'bold', marginBottom: '16px' }}>
            Visits
          </Typography>
          {filteredBills.map((bill) => {
            const date = format(new Date(bill.createdAt), 'dd-MMM-yyyy');
            return (
              <Box
                key={date}
                sx={{
                  padding: '8px',
                  marginBottom: '8px',
                  borderRadius: '4px',
                  backgroundColor: selectedDate === date ? '#8F00FF' : 'transparent',
                  color: selectedDate === date ? 'white' : 'inherit',
                  cursor: 'pointer',
                  '&:hover': {
                    backgroundColor: selectedDate === date ? '#8F00FF' : '#e0e0e0',
                  },
                }}
                onClick={() => handleDateClick(date)}
              >
                <Typography variant="body2">{date}</Typography>
              </Box>
            );
          })}
        </Box>
      )}

      {/* Main Content */}
      <Box sx={{ 
        flex: 1, 
        padding: '16px', 
        overflowY: 'auto', 
        height: isMobile ? 'calc(100vh - 60px)' : '100vh' 
      }}>
        <Typography variant="h5" sx={{ textAlign: 'left', mb: 2 }}>
          Prescription &rarr;
        </Typography>

        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Typography variant="h6">
            {numberOfVisits} visits Since {earliestVisitDate}
          </Typography>
        </Box>

        <Grid container justifyContent="center" alignItems="center" mb={2}>
          {filteredBills.length > 0 ? (
            <Button
              onClick={() => handleNavigate(filteredBills[0].billId._id)}
              sx={{
                backgroundColor: '#8F00FF',
                color: 'white',
                fontWeight: 'bold',
                boxShadow: '0 2px 5px rgba(0, 0, 0, 0.2)',
                '&:hover': { backgroundColor: '#7B1FA2' },
              }}
            >
              Create Visit for Patient
            </Button>
          ) : (
            <Typography>No visits available</Typography>
          )}
        </Grid>

        {loading ? (
          <Box display="flex" justifyContent="center" alignItems="center">
            <img
              src={require('../../assets/images/loading.gif')}
              alt="loading"
              style={{ width: '100px', height: '100px' }}
            />
          </Box>
        ) : (
          <>
            {filteredBills.map((bill) => {
              const date = format(new Date(bill.createdAt), 'dd-MMM-yyyy');
              return (
                <Paper
                  key={bill._id}
                  id={date}
                  sx={{
                    marginBottom: '20px',
                    padding: '20px',
                    borderRadius: '10px',
                    boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
                    backgroundColor: '#ffffff',
                  }}
                >
                  <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
                    <Box>
                      <Typography variant="h6" sx={{ fontWeight: 'bold', color: '#8F00FF' }}>
                        {date}
                      </Typography>
                      <Typography variant="body2" sx={{ color: '#666' }}>
                        By {bill?.doctorName?.drName || 'Unknown'}
                      </Typography>
                    </Box>

                    <Box>
                      <Button
                        variant="contained"
                        sx={{ backgroundColor: '#4CAF50', color: 'white', mr: 1, textTransform: 'none' }}
                        onClick={(e) => handleEmailPrescription(e, bill)}
                      >
                        Email
                      </Button>
                      <Button
                        variant="contained"
                        sx={{ backgroundColor: '#25D366', color: 'white', mr: 1, textTransform: 'none' }}
                        onClick={(e) => handleWhatsAppPrescription(e, bill)}
                      >
                        WhatsApp
                      </Button>
                      <Button
                        variant="contained"
                        sx={{ backgroundColor: '#8F00FF', color: 'white', textTransform: 'none' }}
                        onClick={(e) => printPrescription(e, bill._id)}
                        disabled={isPrescription[bill._id]}
                      >
                        {isPrescription[bill._id] ? 'Generating PDF...' : 'Print'}
                      </Button>
                    </Box>
                  </Box>

                  <Grid container spacing={2}>
                    <Grid item xs={12} md={6}>
                      <Typography><strong>Patient Name:</strong> {bill.billId?.pSalutation ? `${bill.billId.pSalutation}.` : ''} {bill.billId?.pName || ''}</Typography>
                      <Typography><strong>Phone:</strong> {bill.billId?.pNum || ''}</Typography>
                      <Typography><strong>Prescription ID:</strong> {bill.billNO || ''}</Typography>
                    </Grid>

                    <Grid item xs={12} md={6}>
                      <Box display="flex" gap={2} flexWrap="wrap">
                        <Typography><strong>BP:</strong> {bill.bloodPressure}</Typography>
                        <Typography><strong>HR:</strong> {bill.heartRate}</Typography>
                        <Typography><strong>RR:</strong> {bill.respiratoryRate}</Typography>
                        <Typography><strong>Temp:</strong> {bill.temperature}</Typography>
                        <Typography><strong>Ht:</strong> {bill.height}</Typography>
                        <Typography><strong>Wt:</strong> {bill.weight}</Typography>
                      </Box>
                    </Grid>

                    <Grid item xs={12}>
                      <Typography><strong>Complaints:</strong> <span dangerouslySetInnerHTML={{ __html: bill.complaints }} /></Typography>
                      <Typography><strong>Clinical Findings:</strong> <span dangerouslySetInnerHTML={{ __html: bill.clinicalFindings }} /></Typography>
                      <Typography><strong>Diagnosis:</strong> <span dangerouslySetInnerHTML={{ __html: bill.diagnosis }} /></Typography>
                      <Typography><strong>Known Diagnosis:</strong> <span dangerouslySetInnerHTML={{ __html: bill.knownDiagnosis }} /></Typography>
                    </Grid>

                    <Grid item xs={12}>
                      <Typography variant="h6" sx={{ marginBottom: '10px', fontWeight: 'bold', color: '#8F00FF' }}>
                        Medicine Details
                      </Typography>
                      <TableContainer component={Paper} sx={{ overflowX: 'auto' }}>
                        <Table>
                          <TableHead>
                            <TableRow>
                              <TableCell><strong>Medicine Name</strong></TableCell>
                              <TableCell><strong>Dosage</strong></TableCell>
                              <TableCell><strong>Frequency</strong></TableCell>
                              <TableCell><strong>Duration</strong></TableCell>
                              <TableCell><strong>Tablets</strong></TableCell>
                            </TableRow>
                          </TableHead>
                          <TableBody>
                            {bill.medicines?.map((medicine, index) => (
                              <TableRow key={index}>
                                <TableCell>{medicine.medicineName}</TableCell>
                                <TableCell>{medicine.foodType}</TableCell>
                                <TableCell>{medicine.frequency}</TableCell>
                                <TableCell>{medicine.duration}</TableCell>
                                <TableCell>{medicine.tablets}</TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      </TableContainer>
                    </Grid>

                    <Grid item xs={12}>
                      <Typography><strong>Investigations:</strong></Typography>
                      <ul>
                        {bill.selectedTests?.map((test) => (
                          <li key={test._id}>{test.testName}</li>
                        ))}
                      </ul>
                    </Grid>
                  </Grid>
                </Paper>
              );
            })}
          </>
        )}
      </Box>
    </Box>
  );
};

export default PrescriptionList;