import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import axios from 'axios';
import {
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Checkbox,
    FormControlLabel,
    Button,
    Grid,
    Typography,
} from '@mui/material';

const UserAccess = () => {
    const [users, setUsers] = useState([]);
    const [selectedUser, setSelectedUser] = useState('');
    const [selectedPermissions, setSelectedPermissions] = useState([]);
    const [selectAll, setSelectAll] = useState(false);

    useEffect(() => {
        // Fetch the list of users from your backend API
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios
            .get(`${apiBaseUrl}/auth/getUser`) // Replace with your actual API endpoint
            .then((response) => {
                // Assuming the response.data contains the list of users
                setUsers(response.data);
            })
            .catch((error) => {
                console.error('Error fetching users:', error);
            });
    }, []);

    useEffect(() => {
        if (selectedUser) {
            // Fetch user permissions based on the selected user's ID
            const apiBaseUrl = process.env.REACT_APP_API_KEY;
            axios
                .get(`${apiBaseUrl}/auth/getAccess/${selectedUser}`) // Replace with your actual API endpoint
                .then((response) => {
                    // Assuming the response.data contains the user's permissions as an array
                    setSelectedPermissions(response.data.permissions);
                })
                .catch((error) => {
                    console.error('Error fetching user permissions:', error);
                });
        }
    }, [selectedUser]);

    const handleUserChange = (event) => {
        setSelectedUser(event.target.value);
    };

    const handlePermissionChange = (event) => {
        const permission = event.target.value;
        if (event.target.checked) {
            setSelectedPermissions([...selectedPermissions, permission]);
        } else {
            setSelectedPermissions(selectedPermissions.filter((p) => p !== permission));
        }
    };

    const handleSelectAll = () => {
        setSelectAll(!selectAll);
        setSelectedPermissions(selectAll ? [] : ['UpdatePatient', 'StaffManagement', 'TestMaster', 'TestMasterList', 'GroupMaster', 'GroupMasterList', 'CollReports', 'Bills', 'LabReports', 'UserAccess', 'createBill', 'createDoctor']); // Add your permission values
    };

    const handleFormSubmit = (event) => {
        event.preventDefault();
        // Send selectedUser and selectedPermissions to your backend for saving
        const data = {
            user: selectedUser,
            permissions: selectedPermissions,
        };
        const apiBaseUrl = process.env.REACT_APP_API_KEY;
        axios
            .post(`${apiBaseUrl}/auth/store-user-access`, data) // Replace with your API endpoint for saving permissions
            .then((response) => {
                console.log('Permissions saved successfully:', response.data);
                toast.success('Permissions saved successfully');

            })
            .catch((error) => {
                console.error('Error saving permissions:', error);
            });
    };

    return (
        <div className='container'>
            {/* <Typography variant="h4">User Access</Typography> */}
            <h5 style={{ textAlign: 'center', marginTop: '20px' }}>User Access</h5>
            <form onSubmit={handleFormSubmit}>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <FormControl fullWidth>
                            <InputLabel>Select User</InputLabel>
                            <Select
                                required
                                value={selectedUser}
                                onChange={handleUserChange}
                            >
                                <MenuItem value="">
                                    <em>Select a user</em>
                                </MenuItem>
                                {users.map((user) => (
                                    <MenuItem key={user._id} value={user._id}>
                                        {user.username}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                    <Grid item xs={12}>
                        <FormControl fullWidth>
                            <Typography variant="subtitle1">Permissions:</Typography>
                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectAll}
                                        onChange={handleSelectAll}
                                    />
                                }
                                label="Select All"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('createBill')}
                                        onChange={handlePermissionChange}
                                        value="createBill"
                                    />
                                }
                                label="Create Bill"
                            />


                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('Bills')}
                                        onChange={handlePermissionChange}
                                        value="Bills"
                                    />
                                }
                                label="Bill List"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('LabReports')}
                                        onChange={handlePermissionChange}
                                        value="LabReports"
                                    />
                                }
                                label="Lab Report"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('feesMaster')}
                                        onChange={handlePermissionChange}
                                        value="feesMaster"
                                    />
                                }
                                label="Fees Master"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('TestMaster')}
                                        onChange={handlePermissionChange}
                                        value="TestMaster"
                                    />
                                }
                                label="Test Master"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('TestMasterList')}
                                        onChange={handlePermissionChange}
                                        value="TestMasterList"
                                    />
                                }
                                label="Test Master List"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('GroupMaster')}
                                        onChange={handlePermissionChange}
                                        value="GroupMaster"
                                    />
                                }
                                label="Group Master"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('GroupMasterList')}
                                        onChange={handlePermissionChange}
                                        value="GroupMasterList"
                                    />
                                }
                                label="Group Master List"
                            />

<FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('ProfileMaster')}
                                        onChange={handlePermissionChange}
                                        value="ProfileMaster"
                                    />
                                }
                                label="Profile Master"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('ProfileMasterList')}
                                        onChange={handlePermissionChange}
                                        value="ProfileMasterList"
                                    />
                                }
                                label="Profile Master List"
                            />


                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('createDoctor')}
                                        onChange={handlePermissionChange}
                                        value="createDoctor"
                                    />
                                }
                                label="Create Doctor"
                            />


                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('UpdatePatient')}
                                        onChange={handlePermissionChange}
                                        value="UpdatePatient"
                                    />
                                }
                                label="Update Patient"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('StaffManagement')}
                                        onChange={handlePermissionChange}
                                        value="StaffManagement"
                                    />
                                }
                                label="Staff Management"
                            />


                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('CollReports')}
                                        onChange={handlePermissionChange}
                                        value="CollReports"
                                    />
                                }
                                label="Collection Reports"
                            />

<FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('testperformance')}
                                        onChange={handlePermissionChange}
                                        value="testperformance"
                                    />
                                }
                                label="Test Performance"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('patinetPerformance')}
                                        onChange={handlePermissionChange}
                                        value="patinetPerformance"
                                    />
                                }
                                label="Test Sumarry"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('mostVisited')}
                                        onChange={handlePermissionChange}
                                        value="mostVisited"
                                    />
                                }
                                label="Frequent Patients"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('frequenTest')}
                                        onChange={handlePermissionChange}
                                        value="frequenTest"
                                    />
                                }
                                label="Frequent Tests"
                            />

                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('patientPromotion')}
                                        onChange={handlePermissionChange}
                                        value="patientPromotion"
                                    />
                                }
                                label="Patient Promotion"
                            />



                            <FormControlLabel
                                control={
                                    <Checkbox
                                        checked={selectedPermissions.includes('UserAccess')}
                                        onChange={handlePermissionChange}
                                        value="UserAccess"
                                    />
                                }
                                label="User Access"
                            />

                        </FormControl>

                    </Grid>
                    <Grid item xs={12}>
                        <Button type="submit" variant="contained" color="primary" style={{ backgroundColor: '#8F00FF', color: 'white', border: 'none' }}>
                            Save
                        </Button>
                    </Grid>
                </Grid>
            </form>
        </div>
    );
};

export default UserAccess;
